INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'introspection'), 2, 'code_output', 'What does this print?', 'print(type(print))', 'python', '<class ''builtin_function_or_method''>', 'print is written in C, not in Python.', 'Functions built into CPython (written in C) have type builtin_function_or_method; functions you write with def have type function.', NULL, NULL, 45);
