INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'running'), 1, 'mcq', 'Which file is a Jupyter notebook?', NULL, NULL, 'analysis.ipynb', 'The extension is short for ''interactive Python notebook''.', '.ipynb files hold cells, outputs and plots. .py files are plain scripts; .pyc files are compiled bytecode that Python makes for itself.', NULL, NULL, 86);
