INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'line-structure'), 2, 'true_false', 'This snippet is valid and prints 6: Python keeps reading one statement across lines while a bracket is open.', 'total = (1 +\n         2 +\n         3)\nprint(total)', 'python', 'True', 'What does Python do while a bracket is still open?', 'Inside (), [] or {} a statement can carry on over several lines. This is the clean way to split a long formula or a long list of arguments.', NULL, NULL, 87);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'line-structure'), 2, 'true_false', '`x = 1; y = 2` is valid Python: a semicolon can separate two statements on one line.', NULL, NULL, 'True', 'It''s allowed, but is it common?', 'Semicolons work, but PEP 8 discourages them; Python code puts one statement per line. Unlike JavaScript, you never need a semicolon at the end of a line.', NULL, NULL, 88);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'cli-args'), 2, 'code_output', 'What does this print?', 'import sys\nsys.argv = ["train.py", "--lr", "0.1"]   # what `python train.py --lr 0.1` gives\nprint(sys.argv[1:], type(sys.argv[2]).__name__)', 'python', '[''--lr'', ''0.1''] str', 'The terminal only ever passes text.', 'sys.argv is a list of strings: the script name first, then every argument. ''0.1'' is a str until you convert it with float().', NULL, NULL, 89);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''--lr'', ''0.1''] str', 1), (@q, 'B', '[''train.py'', ''--lr''] str', 0), (@q, 'C', '[''--lr'', ''0.1''] float', 0), (@q, 'D', '[''--lr'', 0.1] float', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'cli-args'), 2, 'mcq', 'You run `python train.py data.csv`. Inside train.py, what is `sys.argv[0]`?', NULL, NULL, '''train.py''', 'Position 0 is taken before your own arguments start.', 'sys.argv[0] is the script''s name; your arguments start at sys.argv[1]. The word ''python'' is the program, not part of argv.', NULL, NULL, 90);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '''data.csv''', 0), (@q, 'B', '''python''', 0), (@q, 'C', '''train.py''', 1), (@q, 'D', 'The first line of data.csv', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'cli-args'), 2, 'fill_blank', 'The list that holds a script''s command-line arguments is sys.____.', NULL, NULL, 'argv', 'Short for ''argument vector'', a name inherited from C.', 'sys.argv[0] is the script name and sys.argv[1:] are the arguments, all as strings.', NULL, NULL, 91);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'arithmetic'), 2, 'code_output', 'What does this print?', 'print(2 ^ 3)', 'python', '1', 'In Python, ^ is not the power operator.', '^ is bitwise XOR: 10 XOR 11 = 01, which is 1. The power operator is **, so 2 ** 3 is 8. A classic bug when porting maths from a spreadsheet.', '  2 = 1 0\n  3 = 1 1\nXOR = 0 1   -> 1   (1 where the bits differ)', NULL, 92);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '8', 0), (@q, 'B', '1', 1), (@q, 'C', '6', 0), (@q, 'D', '9', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'print'), 2, 'code_output', 'What does this print?', 'print("epoch", 3, "loss", 0.25, True, None)', 'python', 'epoch 3 loss 0.25 True None', 'print turns each argument into text for you.', 'print calls str() on every argument, so ints, floats, bools and None can be mixed freely. Only + between a str and a number raises TypeError.', NULL, NULL, 93);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', 'epoch3loss0.25TrueNone', 0), (@q, 'C', 'epoch 3 loss 0.25', 0), (@q, 'D', 'epoch 3 loss 0.25 True None', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'arithmetic'), 2, 'code_output', 'What does this print?', 'print((0 - 1) % 5, (4 + 1) % 5)', 'python', '4 0', '% with a positive divisor always lands in 0..divisor-1.', 'Python''s % wraps around: one step back from 0 is 4, one step forward from 4 is 0. That makes % perfect for circular buffers and round-robin GPU assignment.', '   0 -> 1 -> 2 -> 3 -> 4\n   ^                   |\n   +-------------------+   (i + 1) % 5 / (i - 1) % 5', 'Like a clock: one hour before 0 is 11, not -1.', 94);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '-1 0', 0), (@q, 'B', '4 5', 0), (@q, 'C', '4 0', 1), (@q, 'D', '-1 5', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'precedence'), 2, 'code_output', 'What does this print?', 'print(2 * 3 % 4, 2 * (3 % 4))', 'python', '2 6', '* and % have the same precedence.', 'Same precedence means left to right: (2 * 3) % 4 = 6 % 4 = 2. The brackets force 3 % 4 = 3 first, giving 6.', NULL, NULL, 95);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '6 2', 0), (@q, 'B', '2 2', 0), (@q, 'C', '6 6', 0), (@q, 'D', '2 6', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'precedence'), 2, 'code_output', 'What does this print?', 'print("a" + "b" * 3)', 'python', 'abbb', 'String * and + follow the same precedence as with numbers.', '* happens before +, so ''b'' * 3 = ''bbb'' first, then ''a'' + ''bbb''. Write (''a'' + ''b'') * 3 for ''ababab''.', NULL, NULL, 96);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ababab', 0), (@q, 'B', 'abbb', 1), (@q, 'C', 'TypeError', 0), (@q, 'D', 'abab', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'input'), 2, 'code_output', 'What does this print?', 'import io, sys\nsys.stdin = io.StringIO("3 4\\n")   # pretend the user typed 3 4\na, b = map(int, input().split())\nsys.stdin = sys.__stdin__\nprint(a * b)', 'python', '12', 'split() cuts the line into pieces and map(int, ...) converts each one.', 'input() gives ''3 4''; split() gives [''3'', ''4'']; map(int, ...) converts both. This one-liner is the standard way to read two numbers on coding-interview platforms.', NULL, NULL, 97);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '34', 0), (@q, 'C', '12', 1), (@q, 'D', '''3''''4''', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'input'), 2, 'true_false', 'input(''Name: '') shows the prompt ''Name: '', waits for Enter, and returns what was typed WITHOUT the trailing newline.', NULL, NULL, 'True', 'Do you need to strip the Enter key yourself?', 'input() removes the newline for you. sys.stdin.readline(), the faster alternative, keeps it (''Ravi\\n'').', NULL, NULL, 98);
