INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conversion'), 2, 'code_output', 'What does this print?', 'print(int("3.5"))', 'python', 'ValueError', 'int() on a string wants a whole-number string.', 'int(''3.5'') raises ValueError because ''3.5'' isn''t an integer literal. Use int(float(''3.5'')) to get 3.', NULL, NULL, 34);
