INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dynamic-typing'), 2, 'true_false', 'Python is dynamically typed but also strongly typed: `"1" + 1` raises a TypeError instead of quietly converting.', NULL, NULL, 'True', 'Compare with JavaScript, where ''1'' + 1 is ''11''.', 'Dynamic: types are checked at runtime and belong to values, not names. Strong: Python won''t silently mix str and int; you convert explicitly.', NULL, NULL, 37);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dynamic-typing'), 2, 'code_output', 'What does this print?', 'x = 5\nprint(isinstance(x, int), type(x) == float)', 'python', 'True False', 'isinstance asks ''is x an int (or a subclass)?''.', 'x is an int, so isinstance(x, int) is True and its type is not float. isinstance is the usual way to check types.', NULL, NULL, 38);
