INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unpacking'), 2, 'code_output', 'What does this print?', 'a, b = 1, 2\na, b = b, a\nprint(a, b)', 'python', '2 1', 'The right side is fully evaluated before anything is assigned.', 'b, a is built as the tuple (2, 1) first, then unpacked into a and b. No temp variable needed.', NULL, NULL, 39);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '2 2', 0), (@q, 'B', '1 2', 0), (@q, 'C', '1 1', 0), (@q, 'D', '2 1', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unpacking'), 2, 'code_output', 'What does this print?', 'first, *rest = [1, 2, 3, 4]\nprint(first, rest)', 'python', '1 [2, 3, 4]', 'The star collects whatever is left over.', 'first takes 1 and *rest gathers the remaining items into a list.', NULL, 'Like JavaScript''s const [first, ...rest] = arr.', 40);
