INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unpacking'), 2, 'code_output', 'What does this print?', 'a, b = [1, 2, 3]\nprint(a, b)', 'python', 'ValueError', 'Count the names and the values.', 'Two names but three values: ValueError: too many values to unpack. Use a, *b = ... to collect the extras.', NULL, NULL, 41);
