INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'naming'), 2, 'mcq', 'Which of these can NOT be used as a variable name at all?', NULL, NULL, 'for', 'One of them is part of Python''s grammar.', 'for is a reserved keyword, so it''s a SyntaxError. list is allowed but a bad idea: it hides the built-in list().', NULL, NULL, 42);
