INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'naming'), 2, 'code_output', 'What does this print?', 'list = [1, 2]\nprint(list("ab"))', 'python', 'TypeError', 'What does the name list refer to after line 1?', 'Line 1 shadows the built-in list with a list object, and calling a list raises TypeError: ''list'' object is not callable. Avoid names like list, str, dict, input, sum.', NULL, NULL, 43);
