INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'floats'), 2, 'code_output', 'What does this print?', 'print(round(0.1 + 0.2, 2) == 0.3)', 'python', 'True', 'Rounding hides the tiny error at the end.', 'round(0.30000000000000004, 2) is 0.3, which equals the float literal 0.3. Fine for display; for comparisons prefer math.isclose.', NULL, NULL, 46);
