INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'binding'), 3, 'code_output', 'What does this print?', 'a = [1]\nb = a\ndel a\nprint(b)', 'python', '[1]', 'del removes a name, not necessarily the object.', 'del a removes the label a. The list still has another name (b) pointing at it, so it stays alive. It''s freed only when no references remain.', NULL, NULL, 47);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'NameError', 0), (@q, 'B', '[1]', 1), (@q, 'C', '[]', 0), (@q, 'D', 'None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'binding'), 3, 'code_output', 'What does this print?', 'def f(a, b):\n    a = a + [1]\n    b.append(1)\n\nx, y = [], []\nf(x, y)\nprint(x, y)', 'python', '[] [1]', 'One line rebinds a local name, the other mutates the shared object.', 'Python passes object references (''call by sharing''). a = a + [1] makes a new list for the local name only; b.append(1) changes the caller''s list.', NULL, NULL, 48);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1] [1]', 0), (@q, 'B', '[1] []', 0), (@q, 'C', '[] []', 0), (@q, 'D', '[] [1]', 1);
