INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conversion'), 3, 'code_output', 'What does this print?', 'print(int("0x1A", 16), int("101", 2), int("1_000"))', 'python', '26 5 1000', 'The second argument to int() is the number base.', 'Base 16: 0x1A = 26. Base 2: 101 = 5. int() also accepts underscores between digits, like the literal 1_000.', NULL, NULL, 50);
