INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'identity'), 3, 'code_output', 'What does this print?', 'a = [1]\nb = a\na += [2]\nprint(b)', 'python', '[1, 2]', 'For a list, += changes the list itself.', 'list += calls extend in place, so b (the same list) sees [1, 2].', NULL, NULL, 53);
