INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'identity'), 3, 'code_output', 'What does this print?', 't = (1, [2])\nt[1].append(3)\nprint(t)', 'python', '(1, [2, 3])', 'The tuple holds a reference to the list. Which object is being changed?', 'A tuple can''t change which objects it holds, but the list inside it is still mutable. That''s also why such a tuple can''t be a dict key.', NULL, NULL, 55);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(1, [2, 3])', 1), (@q, 'B', 'TypeError', 0), (@q, 'C', '(1, [2])', 0), (@q, 'D', '(1, [2], 3)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'identity'), 3, 'true_false', 'In CPython, two objects whose lifetimes don''t overlap can end up with the same id().', NULL, NULL, 'True', 'id() is the memory address in CPython. What happens to freed memory?', 'id is only unique among objects alive at the same time. Once an object is freed, its address can be reused, so storing id()s of temporary objects is unreliable.', NULL, NULL, 56);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'caching'), 3, 'code_output', 'What does this print?', 'print(int("256") is int("256"), int("257") is int("257"))', 'python', 'True False', 'CPython keeps a ready-made set of small integers.', 'CPython pre-creates ints from -5 to 256 and always reuses them. 257 built at runtime gives two separate objects, so `is` is False even though == is True.', 'small-int cache: [-5 ... 0 ... 256]   shared\nint("256") ---> same cached object\nint("257") ---> new object each time', NULL, 57);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True True', 0), (@q, 'B', 'True False', 1), (@q, 'C', 'False True', 0), (@q, 'D', 'False False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'caching'), 3, 'mcq', 'Which range of integers does CPython pre-create and share (''small-int cache'')?', NULL, NULL, '-5 to 256', 'It''s slightly wider than a byte and includes a few negatives.', 'CPython caches -5..256. Java caches Integer -128..127 by default, which is where the third option comes from. Neither is something your code should rely on.', NULL, NULL, 58);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '-5 to 256', 1), (@q, 'B', '0 to 1000', 0), (@q, 'C', '0 to 255', 0), (@q, 'D', '-128 to 127', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'caching'), 3, 'true_false', 'You should compare numbers with `is` when you know they are small, because it''s faster than ==.', NULL, NULL, 'False', 'What happens the day a value goes above 256?', '`is` on numbers depends on a CPython implementation detail. Always use == for values; keep `is` for None, True, False and sentinel objects. Python 3.8+ even warns about `x is 5`.', NULL, NULL, 59);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'floats'), 3, 'code_output', 'What does this print?', 'import math\nprint(0.1 + 0.2 == 0.3, math.isclose(0.1 + 0.2, 0.3))', 'python', 'False True', 'One comparison demands every bit match; the other allows a tiny tolerance.', 'Exact == fails because of the rounding error. math.isclose compares with a relative tolerance (1e-9 by default). NumPy''s equivalent is np.isclose / np.allclose.', NULL, NULL, 60);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False True', 1), (@q, 'B', 'True False', 0), (@q, 'C', 'True True', 0), (@q, 'D', 'False False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'floats'), 3, 'code_output', 'What does this print?', 'print(1e16 + 1 == 1e16)', 'python', 'True', 'A float has about 15-16 significant decimal digits.', 'At 1e16 the gap between neighbouring floats is 2, so adding 1 rounds back to 1e16. Big + small loses the small part.', NULL, NULL, 61);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'OverflowError', 0), (@q, 'B', '1e16', 0), (@q, 'C', 'False', 0), (@q, 'D', 'True', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'floats'), 3, 'code_output', 'What does this print?', 'x = float("nan")\nprint(x == x, x != x)', 'python', 'False True', 'NaN means ''not a number''. Is an unknown equal to an unknown?', 'By the IEEE 754 rules, NaN is not equal to anything, including itself. Use math.isnan(x) to test for it (pandas uses isna()).', NULL, NULL, 62);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True True', 0), (@q, 'B', 'True False', 0), (@q, 'C', 'False False', 0), (@q, 'D', 'False True', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'floats'), 3, 'code_output', 'What does this print?', 'print(round(2.675, 2))', 'python', '2.67', 'What is 2.675 actually stored as in binary?', '2.675 is stored as 2.67499999999999982236431605997495353221893310546875, so it rounds down to 2.67. Not a bug: the decimal you typed isn''t the number stored.', NULL, NULL, 63);
