INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dynamic-typing'), 2, 'mcq', 'After `x = 5` and then `x = "five"`, what actually changed?', NULL, NULL, 'The name x now points at a different object (a str); the int 5 itself was not modified', 'Values have types; names are just labels.', 'Rebinding moves the label x to a new object. The type belongs to the object, which is what ''dynamically typed'' means.', NULL, NULL, 83);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The name x now points at a different object (a str); the int 5 itself was not modified', 1), (@q, 'B', 'Nothing: x still holds 5', 0), (@q, 'C', 'The int object 5 was converted into the string ''five''', 0), (@q, 'D', 'Python changed the declared type of x from int to str', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'floats'), 2, 'mcq', 'You''re storing prices in rupees and paise and need exact sums. What''s the right choice?', NULL, NULL, 'decimal.Decimal built from strings, or integers counting paise', 'Which types avoid binary rounding error?', 'Binary floats can''t hold most decimal fractions exactly. Decimal(''19.99'') or integer paise (1999) keep money exact. For ML metrics floats are fine; compare with a tolerance.', NULL, NULL, 84);
