INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conversion'), 3, 'true_false', 'float(''inf''), float(''-inf'') and float(''nan'') are all valid conversions that don''t raise an error.', NULL, NULL, 'True', 'IEEE floats have special values beyond ordinary numbers.', 'These strings convert to infinity, minus infinity and NaN. You''ll see inf and nan in ML when a loss explodes or a division by zero sneaks in.', NULL, NULL, 85);
