INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'core-types'), 1, 'mcq', 'A training script has `lr = 0.001`, `epochs = 10`, `model_name = "bert"` and `use_gpu = True`. What are their types, in order?', NULL, NULL, 'float, int, str, bool', 'A dot makes a float; quotes make a str; True has no quotes.', '0.001 is a float, 10 is an int, ''bert'' is a str and True is a bool. Python works these out from the values; you never write the types yourself.', NULL, NULL, 87);
