INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dynamic-typing'), 2, 'mcq', 'This prints 8 abab [1, 1]. What idea does it show?', 'def double(x):\n    return x * 2\n\nprint(double(4), double("ab"), double([1]))', 'python', 'Duck typing: the function works with any object that supports * 2, whatever its type', 'The function never checks what x is. It only needs x * 2 to work.', 'Python runs whatever * means for the object it gets: number multiply, string repeat, list repeat. This is ''duck typing''.', NULL, '''If it walks like a duck and quacks like a duck, it''s a duck'': behaviour matters, not declared type.', 97);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Implicit conversion: Python turned every argument into a number', 0), (@q, 'B', 'Function overloading: Python made three versions of double', 0), (@q, 'C', 'Duck typing: the function works with any object that supports * 2, whatever its type', 1), (@q, 'D', 'Generic type parameters declared on the function', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 2, 'true_false', 'A variable assigned at the top level of a notebook cell is a global, so a function defined later can read it.', NULL, NULL, 'True', 'Notebook cells all run in one module namespace.', 'Top-level names in a notebook are globals. A function can read them, which is handy but also how a function quietly depends on a variable you later change or delete.', NULL, NULL, 98);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 2, 'code_output', 'What does this print?', 'if True:\n    msg = "hi"\nfor i in range(3):\n    pass\nprint(msg, i)', 'python', 'hi 2', 'Do if blocks and for loops create their own scope in Python?', 'Only functions (and classes, modules, comprehensions) create scopes. msg and the loop variable i are still alive after the blocks; i keeps its last value, 2.', NULL, 'Like JavaScript''s var, not let: no block scope.', 99);
