INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'naming'), 2, 'mcq', 'Which name follows the Python convention for a constant such as the maximum sequence length?', NULL, NULL, 'MAX_SEQ_LEN', 'Constants are ''shouted''.', 'UPPER_SNAKE_CASE signals ''don''t change this''. Python doesn''t enforce it: it''s a convention, like a code review rule.', NULL, NULL, 100);
