INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-precision'), 2, 'code_output', 'What does this print?', 'import torch\nprint(torch.tensor(0.1).dtype, torch.tensor([1, 2]).dtype)', 'python', 'torch.float32 torch.int64', 'PyTorch picks a default float type that is smaller than Python''s float.', 'A Python float becomes float32 in PyTorch (Python itself uses 64-bit floats), and Python ints become int64. NumPy, by contrast, defaults to float64.', NULL, NULL, 101);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'torch.float64 torch.int32', 0), (@q, 'B', 'torch.float64 torch.int64', 0), (@q, 'C', 'torch.float32 torch.int64', 1), (@q, 'D', 'torch.float32 torch.int32', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-precision'), 2, 'true_false', 'Python''s built-in float is a 64-bit IEEE 754 double, the same format as NumPy''s float64.', NULL, NULL, 'True', 'There''s only one size of float in plain Python.', 'Python has a single float type: a 64-bit double with about 15-16 significant digits. NumPy and PyTorch add smaller types like float32 and float16.', NULL, NULL, 102);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'binding'), 3, 'code_output', 'What does this print?', 'base = {"lr": 0.1, "layers": [64]}\nexp = base.copy()\nexp["lr"] = 0.01\nexp["layers"].append(32)\nprint(base)', 'python', '{''lr'': 0.1, ''layers'': [64, 32]}', '.copy() makes a new dict, but what about the list inside it?', 'A shallow copy has its own keys, so changing exp[''lr''] is safe. But both dicts point at the SAME inner list, so append shows up in base. Use copy.deepcopy for nested experiment configs.', 'base --> {''lr'': 0.1,  ''layers'': --+\nexp  --> {''lr'': 0.01, ''layers'': --+--> [64, 32]\n          own values             shared list', NULL, 103);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{''lr'': 0.1, ''layers'': [64]}', 0), (@q, 'B', '{''lr'': 0.01, ''layers'': [64]}', 0), (@q, 'C', '{''lr'': 0.01, ''layers'': [64, 32]}', 0), (@q, 'D', '{''lr'': 0.1, ''layers'': [64, 32]}', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'binding'), 3, 'code_output', 'What does this print?', 'x = y = []\nx.append(1)\nprint(y)', 'python', '[1]', 'How many lists does `x = y = []` create?', 'Chained assignment evaluates [] once and binds both names to that one list. With numbers it seems harmless because ints can''t be mutated; with lists it''s an aliasing bug. Write x, y = [], [] for two lists.', 'x = y = []      x --+\n                    +--> [1]\n                y --+', NULL, 104);
