INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'core-types'), 3, 'code_output', 'What does this print?', 'print(isinstance(True, int), type(True) == int)', 'python', 'True False', 'isinstance accepts subclasses; type() == doesn''t.', 'bool is a subclass of int, so isinstance(True, int) is True, but its exact type is bool. A JSON validator that checks isinstance(v, int) will accept True as a number.', NULL, NULL, 105);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False False', 0), (@q, 'B', 'False True', 0), (@q, 'C', 'True True', 0), (@q, 'D', 'True False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'core-types'), 3, 'mcq', 'What is z in this snippet?', 'z = 1j\nprint(type(z).__name__, z ** 2)', 'python', 'A complex number (the imaginary unit); z ** 2 is (-1+0j)', 'A number ending in j is the imaginary unit.', 'Python has a built-in complex type: 1j squared is -1, shown as (-1+0j). You meet it in signal processing and FFTs (np.fft returns complex arrays).', NULL, NULL, 106);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A NameError, because j isn''t defined', 0), (@q, 'B', 'A float equal to 1.0', 0), (@q, 'C', 'The integer 1 with a unit label j', 0), (@q, 'D', 'A complex number (the imaginary unit); z ** 2 is (-1+0j)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'core-types'), 3, 'code_output', 'What does this print?', 'preds = [1, 0, 1, 1]\nlabels = [1, 1, 1, 0]\ncorrect = [p == y for p, y in zip(preds, labels)]\nprint(sum(correct) / len(correct))', 'python', '0.5', 'What does sum() do with True and False?', 'Each comparison gives a bool, and bools add like 1 and 0. Two of four predictions match, so the accuracy is 2 / 4 = 0.5. NumPy does the same with (preds == labels).mean().', NULL, NULL, 107);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '0.5', 1), (@q, 'C', '[True, False, True, False]', 0), (@q, 'D', '2', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conversion'), 3, 'code_output', 'What does this print?', 'print(float("1e3"), int("1e3"))', 'python', 'ValueError', 'Python evaluates every argument before print shows anything.', 'float() accepts scientific notation but int() does not, so int(''1e3'') raises ValueError and nothing is printed. Use int(float(''1e3'')) for values like ''1e3'' from a config.', NULL, NULL, 108);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1e3 1000', 0), (@q, 'B', '1000.0 1e3', 0), (@q, 'C', '1000.0 1000', 0), (@q, 'D', 'ValueError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conversion'), 3, 'code_output', 'What does this print?', 'print(bin(10), hex(255), oct(8))', 'python', '0b1010 0xff 0o10', 'These return strings with a prefix that names the base.', 'bin, hex and oct return strings like ''0b1010''. To go back, int(''0xff'', 16) or int(''ff'', 16) both give 255.', NULL, NULL, 109);
