INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unpacking'), 3, 'code_output', 'What does this print?', 'a, b = {"x": 1, "y": 2}\nprint(a, b)', 'python', 'x y', 'What do you get when you iterate over a dict?', 'Iterating a dict gives its keys, so unpacking takes the keys in insertion order. Use a, b = d.values() or d.items() for the other parts.', NULL, NULL, 122);
