INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unpacking'), 3, 'code_output', 'What does this print?', 'a, b = 1', 'python', 'TypeError', 'Is there anything to unpack in an int?', 'TypeError: cannot unpack non-iterable int object. Compare ValueError, which you get when the thing IS iterable but has the wrong number of items. A function that returns one value instead of a pair shows up like this.', NULL, NULL, 123);
