INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unpacking'), 3, 'mcq', 'Which of these lines is a SyntaxError?', NULL, NULL, '*a, *b = [1, 2, 3]', 'How would Python split the values if there were two stars?', 'Only one starred target is allowed per unpacking, since two would be ambiguous. The others are valid: b = [], a = [1], b = [2].', NULL, NULL, 124);
