INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'split-join'), 2, 'code_output', 'What does this print?', 'print("one  two".split(" "), "one  two".split())', 'python', '[''one'', '''', ''two''] [''one'', ''two'']', 'There are two spaces between the words.', 'split('' '') cuts at every single space, so the gap between the two spaces becomes ''''. split() with no argument treats any run of whitespace as one separator and drops empties.', NULL, NULL, 46);
