INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing'), 3, 'code_output', 'What does this print?', 's = "abcdef"\nprint(s[-1:-4:-1])', 'python', 'fed', 'Start at -1, step backwards, stop BEFORE -4.', 'Indexes -1, -2, -3 are ''f'', ''e'', ''d''. -4 (''c'') is the excluded stop.', ' a   b   c   d   e   f\n-6  -5  -4  -3  -2  -1\n         x   <---<---*   start -1, step -1\n        stop (excluded)', NULL, 50);
