INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unicode'), 2, 'fill_blank', 'To turn the str s into bytes you call s.____("utf-8").', NULL, NULL, 'encode', 'bytes.decode goes the other way.', 's.encode(''utf-8'') -> bytes; b.decode(''utf-8'') -> str. Encode on the way out (files, network), decode on the way in.', NULL, NULL, 91);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'escapes'), 2, 'mcq', 'You need the Windows path C:\\new\\data.csv in your code. Which option is safe?', NULL, NULL, 'r"C:\\new\\data.csv" or "C:/new/data.csv"', 'What does \\n mean inside a normal string?', 'In a normal (or f-) string \\n becomes a newline and the path breaks silently. A raw string keeps the backslashes, and Windows also accepts forward slashes. pathlib.Path is the modern choice.', NULL, NULL, 92);
