INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 3, 'fill_blank', 'Since Python 3.9, the method that removes one exact leading substring (unlike lstrip) is s.____("...").', NULL, NULL, 'removeprefix', 'There''s a matching method for the end of the string.', 'removeprefix / removesuffix remove one exact substring if present. lstrip / rstrip remove any characters from a set.', NULL, NULL, 94);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 1, 'code_output', 'What does this print?', 'print("  Data Science ".strip().lower())', 'python', 'data science', 'Methods can be chained: each one works on the result of the one before.', 'strip() removes the outer spaces, then lower() makes every letter lowercase. Chaining like this is the usual first step when cleaning text labels.', NULL, NULL, 95);
