INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'text-cleaning'), 2, 'mcq', 'What does `" ".join(s.split())` do to a string s?', 'print(" ".join("too   many    spaces".split()))', 'python', 'Collapses every run of spaces, tabs and newlines into one space and trims both ends', 'split() with no argument treats any run of whitespace as one gap.', 'split() gives [''too'', ''many'', ''spaces''] and '' ''.join puts single spaces back. It''s the standard one-liner for collapsing messy whitespace in scraped text.', NULL, NULL, 99);
