INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'char-tests'), 2, 'code_output', 'What does this print?', 'print("abc".isalpha(), "abc1".isalnum(), "   ".isspace(), "".isspace())', 'python', 'True True True False', 'What should ''are ALL characters spaces?'' answer for a string with no characters?', 'isalpha: only letters. isalnum: letters or digits. isspace: only whitespace. Every is... test returns False on the empty string, so check for '''' separately.', NULL, NULL, 100);
