INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing'), 4, 'code_output', 'What does this print?', 'print("abc"[True], "abc"[-False])', 'python', 'b a', 'bool is a subclass of int.', 'True works as index 1 and -False is 0, so you get ''b'' and ''a''. Legal, but code that indexes with a bool is almost always a bug from a comparison result used by mistake.', NULL, NULL, 146);
