INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fstrings'), 4, 'mcq', 'Why do logging guides recommend `logger.debug("batch %s", batch)` over `logger.debug(f"batch {batch}")`?', NULL, NULL, 'With %-style arguments the message is only formatted if the record is actually emitted; the f-string is built every time, even when DEBUG is off', 'What happens to the f-string when debug logging is disabled?', 'The f-string is evaluated before logger.debug is even called, so a costly repr of a large tensor runs for nothing. Passing arguments lets logging skip the formatting. It also lets tools like Sentry group messages by their template.', NULL, 'Like a parameterised SQL query: the template stays fixed and the values are bound later.', 147);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'With %-style arguments the message is only formatted if the record is actually emitted; the f-string is built every time, even when DEBUG is off', 1), (@q, 'B', '%-formatting is faster than f-strings in every case', 0), (@q, 'C', 'The f-string version logs at a different level', 0), (@q, 'D', 'f-strings are not allowed in logging calls', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fstrings'), 4, 'code_output', 'What does this print?', 'print(f"{1e6:,.0f}", f"{-0.0001:.2f}", f"{65:c}")', 'python', '1,000,000 -0.00 A', 'Rounding a tiny negative number keeps its sign.', ',.0f groups thousands with no decimals. -0.0001 rounds to zero but stays negative, so it shows as -0.00, a common surprise in reports. :c turns a code point into its character.', NULL, NULL, 148);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1,000,000.0 -0.00 A', 0), (@q, 'B', '1,000,000 0.00 A', 0), (@q, 'C', '1,000,000 -0.00 A', 1), (@q, 'D', '1e+06 -0.00 65', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'escapes'), 4, 'true_false', '`''\\N{EURO SIGN}''` is a single character, the same as `''\\u20ac''`.', 'print(len("\\N{EURO SIGN}"), "\\N{EURO SIGN}" == "\\u20ac")', 'python', 'True', '\\N{...} looks a character up by its official Unicode name.', '\\N{EURO SIGN} is one character, the same as \\u20ac. Named escapes make code with special characters readable: ''\\N{NO-BREAK SPACE}'' is clearer than ''\\xa0''.', NULL, NULL, 149);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unicode'), 4, 'code_output', 'What does this print?', 'data = "id,name".encode("utf-8-sig")   # how Excel often saves CSV\nprint(repr(data.decode("utf-8")[:3]), repr(data.decode("utf-8-sig")[:3]))', 'python', '''\\ufeffid'' ''id,''', 'Some files start with three invisible bytes called a BOM (byte order mark).', 'Decoding with plain utf-8 keeps the BOM as ''\\ufeff'', so the first CSV column becomes ''\\ufeffid'' and df[''id''] raises KeyError. Read such files with encoding=''utf-8-sig''.', 'bytes:  EF BB BF  69 64 2C ...\n        \\_BOM_/   i  d  ,\nutf-8      -> ''\\ufeffid,...''\nutf-8-sig  -> ''id,...''', NULL, 150);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '''\\ufeffid'' ''id,''', 1), (@q, 'B', '''id,'' ''id,''', 0), (@q, 'C', 'UnicodeDecodeError', 0), (@q, 'D', '''\\xef\\xbb\\xbf'' ''id,''', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unicode'), 4, 'code_output', 'What does this print?', 'print(sorted(["\\u00e9clair", "fig", "egg"]))', 'python', '[''egg'', ''fig'', ''éclair'']', 'Strings sort by code point, and é is U+00E9.', 'é (233) sorts after every ASCII letter, so ''éclair'' ends up last instead of next to ''egg''. Language-aware ordering needs locale.strxfrm or a library like PyICU.', NULL, 'Like a database collation: binary order isn''t dictionary order.', 151);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''éclair'', ''egg'', ''fig'']', 0), (@q, 'B', 'TypeError', 0), (@q, 'C', '[''egg'', ''fig'', ''éclair'']', 1), (@q, 'D', '[''egg'', ''éclair'', ''fig'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'split-join'), 4, 'code_output', 'What does this print?', 'print("a\\r\\nb\\x0bc\\x1cd".splitlines())', 'python', '[''a'', ''b'', ''c'', ''d'']', 'splitlines knows more line boundaries than just \\n.', 'splitlines also splits on \\r\\n, \\r, vertical tab (\\x0b), file separator (\\x1c) and more. Text from PDFs or old systems can contain these, so splitlines and split(''\\n'') can give different row counts.', NULL, NULL, 152);
