INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing-slicing'), 2, 'code_output', 'What does this print?', 'nums = [0, 1, 2, 3, 4, 5, 6]\nprint(nums[::2])', 'python', '[0, 2, 4, 6]', 'The third slice number is the step.', '[::2] takes every second item from start to end: 0, 2, 4, 6.', ' [ 0  1  2  3  4  5  6 ]\n   ^     ^     ^     ^     step 2: take, skip, take...\n -> [0, 2, 4, 6]', NULL, 25);
