INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stack-queue'), 2, 'code_output', 'What does this print?', 'from collections import deque\nq = deque(["a", "b"])\nq.append("c")\nprint(q.popleft(), list(q))', 'python', 'a [''b'', ''c'']', 'A queue is first in, first out.', 'popleft() takes from the front: ''a'' comes out and [''b'', ''c''] is left. deque does this in O(1).', ' popleft <- [ a | b | c ] <- append\n   front                  back', NULL, 41);
