INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing-slicing'), 3, 'code_output', 'What does this print?', 'a = [1, 2, 3]\na[1:2] = [7, 8, 9]\nprint(a)', 'python', '[1, 7, 8, 9, 3]', 'A normal slice assignment can replace a piece with a bigger piece.', 'The slice [1:2] (just the 2) is replaced by three items, so the list grows: [1, 7, 8, 9, 3].', ' before: [ 1 | 2 | 3 ]\n              ^^^ a[1:2]\n after:  [ 1 | 7 | 8 | 9 | 3 ]', NULL, 46);
