INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 3, 'code_output', 'What does this print?', 'a = [1, 2]\na.extend("hi")\nprint(a)', 'python', '[1, 2, ''h'', ''i'']', 'A string is iterable, one character at a time.', 'extend iterates whatever it''s given; iterating ''hi'' yields ''h'' then ''i''. Use append(''hi'') to add the whole string.', NULL, NULL, 49);
