INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 3, 'code_output', 'What does this print?', 'a = [1, 2]\nb = a\na += [3]\nprint(b)\na = a + [4]\nprint(b)', 'python', '[1, 2, 3]\n[1, 2, 3]', 'One of these mutates, the other builds a new list.', 'a += [3] extends the existing list in place (b sees it). a = a + [4] creates a new list and rebinds only a, so b stays [1, 2, 3].', ' a += [3]:     a, b --> [1, 2, 3]       (same list grew)\n a = a + [4]:  a ----> [1, 2, 3, 4]    (new list)\n               b ----> [1, 2, 3]', NULL, 50);
