INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 2, 'code_output', 'What does this print?', 'data = list(range(7))\nbatches = [data[i:i + 3] for i in range(0, len(data), 3)]\nprint(batches)', 'python', '[[0, 1, 2], [3, 4, 5], [6]]', 'range(0, 7, 3) gives the start of each batch; slices never go out of range.', 'Starts are 0, 3, 6. The last slice data[6:9] just returns [6], a short final batch. This is what a DataLoader does with drop_last=False.', ' data:   0 1 2 | 3 4 5 | 6\n         -----   -----   -\n batch:    0       1     2   (short last batch)', NULL, 94);
