INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 2, 'code_output', 'What does this print?', 'a = [3, 1, 2]\nprint(a.index(2), a.count(5))', 'python', '2 0', 'index finds a position; count counts how many.', '2 sits at position 2. 5 never appears, so count gives 0 (count never raises; index would raise for a missing value).', NULL, NULL, 95);
