INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 2, 'true_false', '`[1, 2, 3].index(4)` returns -1, like JavaScript''s indexOf.', NULL, NULL, 'False', 'Python prefers to fail loudly.', 'list.index raises ValueError when the value is missing. Check `if x in a:` first, or catch ValueError. (str.find returns -1, but lists have no find.)', NULL, NULL, 99);
