INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 2, 'mcq', 'What is the average time complexity of `d[key]` for a dict with n keys?', NULL, NULL, 'O(1)', 'It doesn''t scan the keys.', 'Dict lookup hashes the key and jumps to a slot, so on average it''s constant time regardless of size.', NULL, NULL, 40);
