INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'crud'), 3, 'code_output', 'What does this print?', 'd = {"a": 1, "b": 2, "c": 3}\nprint(d.popitem(), d)', 'python', '(''c'', 3) {''a'': 1, ''b'': 2}', 'popitem is last in, first out.', 'dict.popitem() removes and returns the most recently inserted pair (LIFO).', ' insert order:  a -> b -> c\n                          ^ popitem() takes the newest', NULL, 41);
