INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hashability'), 3, 'code_output', 'What does this print?', 'key = (1, [2])\nd = {key: "x"}', 'python', 'TypeError', 'A tuple is only hashable if everything inside is.', 'hash() of a tuple hashes each item; the list inside is unhashable, so TypeError.', NULL, NULL, 48);
