INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merging'), 3, 'code_output', 'What does this print?', 'base = {"opt": {"lr": 0.1}}\nmerged = {**base}\nmerged["opt"]["lr"] = 0.5\nprint(base)', 'python', '{''opt'': {''lr'': 0.5}}', 'Is the inner dict copied?', 'Merging is shallow: merged[''opt''] is the same inner dict object as base[''opt''], so the change shows in base. Use copy.deepcopy for nested configs.', ' base   --> { "opt": * }\n                     |\n                     v\n                  {"lr": ...}   <- one inner dict\n                     ^\n merged --> { "opt": * }', NULL, 52);
