INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 3, 'true_false', 'A dict finds a key by computing hash(key) to pick a slot, then confirming with == because different keys can share a hash.', NULL, NULL, 'True', 'What happens if two keys land on the same slot?', 'The hash narrows down where to look; == confirms the match. That''s why keys need consistent __hash__ and __eq__.', NULL, NULL, 59);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iteration'), 4, 'code_output', 'What does this print?', 'd = {"a": 1, "b": 2}\nfor k in d:\n    if k == "a":\n        del d[k]', 'python', 'RuntimeError', 'The dict changes size while the loop is walking it.', 'Changing the number of keys during iteration raises RuntimeError: dictionary changed size during iteration. Loop over list(d) instead.', NULL, 'Like a Java ConcurrentModificationException: you can''t restructure a collection while an iterator walks it.', 60);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'KeyError', 0), (@q, 'B', 'ValueError', 0), (@q, 'C', 'Nothing is printed; d is {''b'': 2}', 0), (@q, 'D', 'RuntimeError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iteration'), 4, 'code_output', 'What does this print?', 'a = {"x": 1, "y": 2, "z": 3}\nb = {"y": 0, "w": 9}\nprint(sorted(a.keys() & b.keys()), sorted(a.keys() - b))', 'python', '[''y''] [''x'', ''z'']', 'keys() views behave like sets.', 'Key views support set operators directly: common keys [''y''], keys only in a [''x'', ''z'']. No conversion to set needed.', NULL, NULL, 61);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''y''] [''w'']', 0), (@q, 'B', '[''w'', ''x'', ''y'', ''z''] [''x'', ''z'']', 0), (@q, 'C', '[''y''] [''x'', ''z'']', 1), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ordering'), 4, 'code_output', 'What does this print?', 'from collections import OrderedDict\na = OrderedDict(x=1, y=2)\nb = OrderedDict(y=2, x=1)\nprint(a == b, dict(a) == dict(b), a == dict(b))', 'python', 'False True True', 'OrderedDict compares order only against another OrderedDict.', 'Two OrderedDicts are equal only if order matches; comparing with a plain dict (or two plain dicts) ignores order.', NULL, NULL, 62);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False True False', 0), (@q, 'B', 'False False False', 0), (@q, 'C', 'True True True', 0), (@q, 'D', 'False True True', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hashability'), 4, 'code_output', 'What does this print?', 'class P:\n    def __init__(self, x):\n        self.x = x\n    def __eq__(self, other):\n        return self.x == other.x\n\nprint({P(1): "a"})', 'python', 'TypeError', 'Defining __eq__ changes what Python assumes about __hash__.', 'If a class defines __eq__ but not __hash__, Python sets __hash__ to None, making instances unhashable. Add __hash__ (or use a frozen dataclass).', NULL, NULL, 63);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 1), (@q, 'B', 'AttributeError', 0), (@q, 'C', '{<__main__.P object>: ''a''}', 0), (@q, 'D', 'KeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hashability'), 4, 'code_output', 'What does this print?', 'class Key:\n    def __init__(self, v):\n        self.v = v\n    def __hash__(self):\n        return hash(self.v)\n    def __eq__(self, o):\n        return self.v == o.v\n\nk = Key(1)\nd = {k: "found"}\nk.v = 2\nprint(d.get(k), d.get(Key(1)))', 'python', 'None None', 'After the change, k hashes to a new slot. Key(1) hashes to the old slot, but is it == to what''s stored?', 'Looking up k now probes the slot for hash(2) and finds nothing. Key(1) probes the right slot, but the stored key now has v=2, so == fails. The entry is unreachable: never mutate a key.', ' stored in slot for hash(1):  k (now v=2)\n d.get(k)      -> looks in slot for hash(2) -> empty\n d.get(Key(1)) -> slot for hash(1) -> k == Key(1)? no', 'Changing your locker number after storing your bag: the attendant now looks in the wrong locker.', 64);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'None found', 0), (@q, 'B', 'found found', 0), (@q, 'C', 'found None', 0), (@q, 'D', 'None None', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hashability'), 4, 'code_output', 'What does this print?', 'x = float("nan")\nd = {x: 1}\nprint(d[x], float("nan") in d)', 'python', '1 False', 'nan != nan, but Python checks identity before ==.', 'The lookup with the same object x succeeds because dicts check `is` first. A different NaN object is not equal (nan != nan), so it isn''t found.', NULL, NULL, 65);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1 False', 1), (@q, 'B', 'False False', 0), (@q, 'C', '1 True', 0), (@q, 'D', 'KeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'collections'), 4, 'code_output', 'What does this print?', 'from collections import Counter\na = Counter(cat=3, dog=1)\nb = Counter(cat=1, dog=4)\nprint(a - b, a + b)', 'python', 'Counter({''cat'': 2}) Counter({''dog'': 5, ''cat'': 4})', 'Counter arithmetic keeps only positive counts.', 'a - b gives cat 2 and dog -3, and the -3 is dropped. a + b gives cat 4, dog 5 (printed most common first). Use a.subtract(b) to keep negatives.', '        cat  dog\n a       3    1\n b       1    4\n a - b   2   -3 -> dropped\n a + b   4    5', NULL, 66);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', 'Counter({''cat'': 2, ''dog'': 0}) Counter({''dog'': 5, ''cat'': 4})', 0), (@q, 'C', 'Counter({''cat'': 2, ''dog'': -3}) Counter({''dog'': 5, ''cat'': 4})', 0), (@q, 'D', 'Counter({''cat'': 2}) Counter({''dog'': 5, ''cat'': 4})', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'collections'), 4, 'code_output', 'What does this print?', 'class Defaulting(dict):\n    def __missing__(self, key):\n        return key.upper()\n\nd = Defaulting(a="x")\nprint(d["a"], d["b"], d.get("c"), len(d))', 'python', 'x B None 1', '__missing__ is only consulted by d[key].', 'dict.__getitem__ calls __missing__ for absent keys (this is how defaultdict works). .get() doesn''t use it, and this __missing__ doesn''t store anything.', NULL, NULL, 67);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'x B C 1', 0), (@q, 'B', 'KeyError', 0), (@q, 'C', 'x B None 1', 1), (@q, 'D', 'x B None 2', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sets'), 4, 'mcq', 'Why can printing a set of strings show a different order each time you start Python, while a set of small ints looks stable?', NULL, NULL, 'String hashes are randomised per process (PYTHONHASHSEED); small ints hash to themselves', 'What does hash(''a'') depend on?', 'Since 3.3, str/bytes hashes are salted per process to resist hash-flooding attacks. hash(5) == 5, so int sets keep a predictable layout.', NULL, 'Like seats being reshuffled at every concert: the audience is the same, the seating plan isn''t.', 68);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'String hashes are randomised per process (PYTHONHASHSEED); small ints hash to themselves', 1), (@q, 'B', 'Sets sort strings alphabetically only sometimes', 0), (@q, 'C', 'Set order depends on available memory', 0), (@q, 'D', 'Strings are stored in insertion order but ints aren''t', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'code_output', 'What does this print?', 'print(hash(-1), hash(-2), hash(-1) == hash(-2))', 'python', '-2 -2 True', 'In CPython''s C code, -1 is reserved as an error signal from hash functions.', 'CPython can''t return -1 from a hash function (it means ''error''), so hash(-1) is remapped to -2. Collisions are normal; == sorts them out.', NULL, NULL, 69);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '-1 -2 False', 0), (@q, 'B', '-2 -1 False', 0), (@q, 'C', '-2 -2 True', 1), (@q, 'D', '1 2 False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'mcq', 'Which statement best describes the CPython (3.6+) dict layout?', NULL, NULL, 'A sparse index table of small ints pointing into a dense, insertion-ordered array of (hash, key, value) entries', 'Order preservation fell out of this design.', 'The compact dict keeps entries densely in insertion order and uses a separate sparse index table with open addressing. That saves memory and makes iteration order = insertion order.', ' indices: [ -, 1, -, 0, -, 2, -, - ]   (sparse, by hash)\n                |     |     |\n entries: 0: (h, "lr",  0.1)          (dense, in insert\n          1: (h, "bs",  32)            order)\n          2: (h, "ep",  10)', NULL, 70);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A sparse index table of small ints pointing into a dense, insertion-ordered array of (hash, key, value) entries', 1), (@q, 'B', 'A sorted array searched with binary search', 0), (@q, 'C', 'An array of linked-list buckets, like Java''s HashMap', 0), (@q, 'D', 'A balanced binary search tree ordered by key', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 4, 'mcq', 'A dict lookup is O(1) on average. When does it degrade toward O(n)?', NULL, NULL, 'When many keys collide on the same hash, so probing has to check many slots', 'What makes probing long?', 'With pathological keys that share hashes, every lookup walks a long probe sequence. That''s the hash-flooding attack string-hash randomisation defends against.', ' good hashes:  [k1][  ][k2][  ][k3]   1 probe each\n collisions:   [k1][k2][k3][k4][k5]   probe, probe, probe...', NULL, 71);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'When many keys collide on the same hash, so probing has to check many slots', 1), (@q, 'B', 'When keys are strings longer than 64 characters', 0), (@q, 'C', 'When the dict was built with a comprehension', 0), (@q, 'D', 'When the dict has more than 2^16 keys', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 4, 'true_false', 'CPython resizes a dict''s hash table when it becomes about two-thirds full, to keep probe sequences short.', NULL, NULL, 'True', 'Open addressing gets slow as the table fills up.', 'The usable fraction is about 2/3; past that the table grows. Like list over-allocation, this makes inserts amortised O(1).', NULL, NULL, 72);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 4, 'code_output', 'What does this print?', 'import sys\nd = {"a": 1}\ns = {"a"}\nl = ["a"]\nprint(sys.getsizeof(d) > sys.getsizeof(l), sys.getsizeof(s) > sys.getsizeof(l))', 'python', 'True True', 'Hash tables keep empty slots on purpose.', 'Dicts and sets reserve spare slots and store hashes, so even a one-item dict or set is bigger than a one-item list. O(1) lookup is paid for in memory.', NULL, NULL, 73);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False True', 0), (@q, 'B', 'True False', 0), (@q, 'C', 'False False', 0), (@q, 'D', 'True True', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'fill_blank', 'When two keys hash to the same slot, CPython dicts find another slot in the same table instead of chaining a linked list. This strategy is called open ____ (one word).', NULL, NULL, 'addressing', 'The opposite of ''separate chaining''.', 'Open addressing probes other slots in the same array (CPython uses a perturbed pseudo-random probe sequence).', NULL, NULL, 74);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'comprehensions'), 4, 'true_false', 'Inverting a dict with `{v: k for k, v in d.items()}` is lossless as long as every value in d is hashable.', NULL, NULL, 'False', 'Hashable isn''t the only requirement for a clean inversion.', 'Values must also be unique; duplicate values collapse into one key and earlier keys are silently dropped.', NULL, NULL, 75);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merging'), 4, 'code_output', 'What does this print?', 'def deep_merge(a, b):\n    out = dict(a)\n    for k, v in b.items():\n        if isinstance(v, dict) and isinstance(out.get(k), dict):\n            out[k] = deep_merge(out[k], v)\n        else:\n            out[k] = v\n    return out\n\nbase = {"opt": {"lr": 0.1, "mom": 0.9}, "bs": 32}\nprint(deep_merge(base, {"opt": {"lr": 0.01}}) == (base | {"opt": {"lr": 0.01}}))', 'python', 'False', 'What does | do to the nested ''opt'' dict?', '| replaces the whole ''opt'' value, losing ''mom''. deep_merge merges recursively and keeps mom=0.9, so the results differ. That''s why config libraries ship a deep merge.', ' base | override:  opt -> {lr: 0.01}            (mom lost)\n deep_merge:       opt -> {lr: 0.01, mom: 0.9}  (merged)', NULL, 76);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', 'RecursionError', 0), (@q, 'C', 'True', 0), (@q, 'D', 'False', 1);
