INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 1, 'code_output', 'What does this print?', 'vocab = {"<pad>": 0, "hello": 1, "world": 2}\nprint([vocab[w] for w in ["hello", "world"]])', 'python', '[1, 2]', 'Look up each word''s id.', 'A vocabulary maps tokens to integer ids, so ''hello world'' becomes [1, 2]. That list of ids is what a language model actually receives.', NULL, NULL, 81);
