INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'get-setdefault'), 3, 'code_output', 'What does this print?', 'd = {"k": None}\nprint(d.get("k", "default"))', 'python', 'None', 'The default is used only when the key is MISSING.', '''k'' exists; its value just happens to be None, so get returns None. JSON nulls arrive like this; handle them with `d.get(''k'') or ''default''` or an explicit None check.', NULL, NULL, 105);
