INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sets'), 3, 'code_output', 'What does this print?', 'print({1, 2} <= {1, 2, 3}, {1, 2} < {1, 2}, {1, 2}.isdisjoint({3}))', 'python', 'True False True', '<= is subset, < is proper (strict) subset.', '{1, 2} is inside {1, 2, 3}; a set is not a strict subset of itself; {1, 2} and {3} share nothing. Handy for ''are all required columns present?'' checks.', NULL, NULL, 118);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False False True', 0), (@q, 'B', 'True False True', 1), (@q, 'C', 'True True True', 0), (@q, 'D', 'True False False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sets'), 3, 'code_output', 'What does this print?', 's = {1, 2}\nfor x in s:\n    s.add(x + 10)', 'python', 'RuntimeError', 'Sets have the same rule as dicts.', 'Adding to a set while looping over it raises ''Set changed size during iteration''. Loop over a copy (for x in list(s)) or collect the new items separately.', NULL, NULL, 119);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'RuntimeError', 1), (@q, 'B', 'TypeError', 0), (@q, 'C', 'Nothing is printed; the loop never ends', 0), (@q, 'D', 'Nothing is printed; s grows to 4 items', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 3, 'mcq', 'Why can `if 0.9 in scores.values():` be slow for a dict with a million entries?', NULL, NULL, 'Values aren''t hashed; checking a values view scans every value, O(n)', 'Only one side of a dict has an index.', 'Keys are in the hash table; values are just stored. `in d.values()` is a linear scan. If you search by value often, keep a reverse dict.', NULL, NULL, 120);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It''s fast; values() is hashed like keys()', 0), (@q, 'B', 'Values aren''t hashed; checking a values view scans every value, O(n)', 1), (@q, 'C', 'Floats can''t be compared with in', 0), (@q, 'D', 'values() copies the dict first', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 3, 'mcq', 'Why must two objects that compare equal (`a == b`) also have equal hashes?', NULL, NULL, 'A lookup uses the hash to pick the slot; if equal keys hashed differently, d[b] would look in the wrong place and miss a', 'Which step happens first in a lookup: hash or ==?', 'The hash chooses where to look; == only confirms inside that spot. That''s why 1, 1.0 and True all hash to 1, and why __eq__ without a matching __hash__ is disabled.', NULL, NULL, 121);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Python checks hashes instead of == to save time, so == is never called', 0), (@q, 'B', 'Otherwise the dict would keep its keys sorted wrongly', 0), (@q, 'C', 'A lookup uses the hash to pick the slot; if equal keys hashed differently, d[b] would look in the wrong place and miss a', 1), (@q, 'D', 'It''s a style rule with no effect on dicts', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 4, 'code_output', 'What does this print?', 'from collections import defaultdict\ntree = lambda: defaultdict(tree)\nt = tree()\nt["a"]["b"]["c"] = 1\nprint(t["a"]["b"]["c"], len(t), "x" in t)', 'python', '1 1 False', 'Each missing key creates another tree.', 'The factory returns a new defaultdict of the same kind, so any depth of nesting is created on demand (''autovivification''). `in` doesn''t trigger the factory.', NULL, NULL, 122);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1 1 True', 0), (@q, 'B', '1 1 False', 1), (@q, 'C', '1 3 False', 0), (@q, 'D', 'KeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merging'), 4, 'code_output', 'What does this print?', 'd = {"a": 1}\nd |= [("b", 2)]\nprint(d)\nprint({"a": 1} | [("b", 2)])', 'python', '{''a'': 1, ''b'': 2}\nTypeError', '|= behaves like update; | wants two dicts.', 'd |= accepts anything update accepts, including a list of pairs. d | other requires other to be a dict. The same split as list += (any iterable) vs + (lists only).', NULL, NULL, 123);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{''a'': 1}\nTypeError', 0), (@q, 'B', '{''a'': 1, ''b'': 2}\nTypeError', 1), (@q, 'C', 'TypeError', 0), (@q, 'D', '{''a'': 1, ''b'': 2}\n{''a'': 1, ''b'': 2}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 4, 'code_output', 'What does this print?', 'import json\nprint(json.dumps({"loss": float("nan")}))', 'python', '{"loss": NaN}', 'Python''s json module is lenient by default.', 'It writes NaN, which is NOT valid JSON: a JavaScript dashboard''s JSON.parse will reject the whole payload. Pass allow_nan=False to fail early, or replace NaN with None.', NULL, NULL, 124);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ValueError', 0), (@q, 'B', '{"loss": NaN}', 1), (@q, 'C', '{"loss": null}', 0), (@q, 'D', '{"loss": "nan"}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 4, 'code_output', 'What does this print?', 'import json\ns = json.dumps({1: "a", "1": "b"})\nprint(s, json.loads(s))', 'python', '{"1": "a", "1": "b"} {''1'': ''b''}', '1 and ''1'' are different dict keys but the same JSON key.', 'dumps converts the int key to ''1'' and writes duplicate keys without complaint; loads keeps the last. Mixed int/str keys silently lose data on a JSON round trip.', NULL, NULL, 125);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{"1": "a", "1": "b"} {1: ''a'', ''1'': ''b''}', 0), (@q, 'B', '{"1": "b"} {''1'': ''b''}', 0), (@q, 'C', '{"1": "a", "1": "b"} {''1'': ''b''}', 1), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'get-setdefault'), 4, 'mcq', 'In a hot loop over millions of rows, what does `groups.setdefault(key, []).append(row)` waste compared with `defaultdict(list)`?', NULL, NULL, 'It builds a new empty list on every call, even when the key already exists', 'Arguments are evaluated before the method runs.', 'The [] default is created (and then thrown away) on every call. defaultdict only calls list() for a genuinely missing key, so it''s faster and clearer for grouping.', NULL, NULL, 126);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It copies the existing list before appending', 0), (@q, 'B', 'It builds a new empty list on every call, even when the key already exists', 1), (@q, 'C', 'Nothing; they compile to the same code', 0), (@q, 'D', 'It rehashes the whole dict on every call', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iteration'), 4, 'code_output', 'What does this print?', 'd = {"x": 1}\nprint(d.values() == d.values(), d.keys() == {"x"}, sorted(d.items() & {("x", 1)}))', 'python', 'False True [(''x'', 1)]', 'keys() and items() act like sets; values() doesn''t.', 'Values may be unhashable and repeated, so values views have no set behaviour and == falls back to identity: two separate views are never equal. Compare list(d.values()) instead.', NULL, NULL, 127);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True True [(''x'', 1)]', 0), (@q, 'B', 'False False []', 0), (@q, 'C', 'True False [(''x'', 1)]', 0), (@q, 'D', 'False True [(''x'', 1)]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iteration'), 4, 'code_output', 'What does this print?', 'd = {"a": 1}\nfor k in d:\n    del d[k]\n    d["b"] = 2', 'python', 'RuntimeError', 'The size stayed at 1. Does Python still notice?', 'Python 3.8+ also tracks key changes, raising ''dictionary keys changed during iteration''. Deleting one key and adding another doesn''t fool it.', NULL, NULL, 128);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Nothing is printed; d is {''b'': 2}', 0), (@q, 'B', 'RuntimeError', 1), (@q, 'C', 'KeyError', 0), (@q, 'D', 'The loop never ends', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ordering'), 4, 'code_output', 'What does this print?', 'from collections import OrderedDict\ncache = OrderedDict()\nfor k in ["a", "b", "c"]:\n    cache[k] = 1\ncache.move_to_end("a")\ncache.popitem(last=False)\nprint(list(cache))', 'python', '[''c'', ''a'']', 'move_to_end marks ''a'' as recently used; popitem(last=False) evicts from the front.', 'After the move the order is b, c, a; evicting the oldest removes b. That''s an LRU cache in a few lines, a classic interview question.', ' insert:       [a, b, c]\n move_to_end:  [b, c, a]     (a = most recent)\n evict front:  [c, a]        (b was least recent)', 'Like a browser cache: whatever you used last moves to the ''fresh'' end, and the stalest entry is evicted first.', 129);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''b'', ''c'', ''a'']', 0), (@q, 'B', '[''a'', ''b'']', 0), (@q, 'C', '[''b'', ''c'']', 0), (@q, 'D', '[''c'', ''a'']', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hashability'), 4, 'code_output', 'What does this print?', 'from dataclasses import dataclass\n\n@dataclass(frozen=True)\nclass K:\n    x: int\n\n@dataclass\nclass M:\n    x: int\n\nprint({K(1): "a"}[K(1)])\nhash(M(1))', 'python', 'a\nTypeError', 'A dataclass with eq=True (the default) must decide what to do about __hash__.', 'frozen=True makes instances immutable and generates __hash__ from the fields, so they work as keys. A plain dataclass defines __eq__, so __hash__ is set to None: unhashable.', NULL, NULL, 130);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'a\nTypeError', 1), (@q, 'B', 'a\na', 0), (@q, 'C', 'KeyError', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hashability'), 4, 'true_false', 'A frozen dataclass is hashable even if one of its fields holds a list.', NULL, NULL, 'False', 'The generated __hash__ hashes a tuple of the field values.', 'hash() of the instance hashes (field1, field2, ...), and a list inside raises TypeError at that moment. frozen only blocks reassigning fields; it doesn''t make the values themselves immutable.', NULL, NULL, 131);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'comprehensions'), 4, 'code_output', 'What does this print?', 'fns = {k: (lambda: k) for k in "ab"}\nprint(fns["a"]())', 'python', 'b', 'When does the lambda look up k: when it''s made, or when it''s called?', 'Closures capture the variable, not its value. By the time fns[''a'']() runs, the loop has finished and k is ''b''. Bind it early with lambda k=k: k.', NULL, 'The same bug as JS closures created in a `var` loop, which all see the final i.', 132);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'NameError', 0), (@q, 'B', 'k', 0), (@q, 'C', 'a', 0), (@q, 'D', 'b', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'comprehensions'), 4, 'code_output', 'What does this print?', 'i = iter(range(4))\nprint({next(i): next(i) for _ in range(2)})', 'python', '{0: 1, 2: 3}', 'In a dict comprehension, is the key or the value evaluated first?', 'Since Python 3.8 the key is evaluated before the value (matching dict literals), so each step pulls key then value: {0: 1, 2: 3}.', NULL, NULL, 133);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{1: 0, 3: 2}', 0), (@q, 'B', 'StopIteration', 0), (@q, 'C', '{0: 0, 2: 2}', 0), (@q, 'D', '{0: 1, 2: 3}', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'collections'), 4, 'code_output', 'What does this print?', 'from collections import Counter\nc = Counter(a=2, b=1)\nc.subtract(Counter(a=3))\nprint(c["a"], +c)', 'python', '-1 Counter({''b'': 1})', 'subtract keeps negatives; unary + keeps only positives.', 'subtract() works in place and allows negative counts (a = -1). +c returns a new Counter with zero and negative counts removed.', NULL, NULL, 134);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '-1 Counter({''b'': 1})', 1), (@q, 'C', '-1 Counter({''a'': -1, ''b'': 1})', 0), (@q, 'D', '0 Counter({''b'': 1})', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'collections'), 4, 'fill_blank', 'Since Python 3.10, `Counter("aab").____()` returns 3, the sum of all the counts.', NULL, NULL, 'total', 'It''s an adjective meaning ''whole sum''.', 'total() adds up all counts. Before 3.10 you wrote sum(c.values()). Handy for turning counts into frequencies: c[w] / c.total().', NULL, NULL, 135);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sets'), 4, 'code_output', 'What does this print?', 's = {frozenset({1, 2})}\nprint({1, 2} in s)', 'python', 'True', 'A plain set is unhashable, so how can `in` work?', 'set.__contains__ has a special case: if the probe is an unhashable set, it retries with a temporary frozenset of it. A dict lookup with a set key would still raise TypeError.', NULL, NULL, 136);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'KeyError', 0), (@q, 'C', 'TypeError', 0), (@q, 'D', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'true_false', 'Deleting most of the keys from a huge dict immediately shrinks the memory it uses.', NULL, NULL, 'False', 'Deleted slots are marked, not compacted.', 'CPython leaves ''dummy'' markers and doesn''t shrink on delete; the table only resizes during later inserts. To reclaim memory from a big filtered dict, build a new one.', NULL, NULL, 137);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'mcq', 'Why do 100,000 instances of the same class use less memory for their attribute dicts than 100,000 separate plain dicts would?', NULL, NULL, 'Instance __dict__s share one keys table (key-sharing dicts) and store only their own values', 'All instances usually have the same attribute names.', 'PEP 412 key-sharing dicts let instances of a class share the key/hash part and keep only values per object. __slots__ goes further by removing the dict.', NULL, NULL, 138);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Instances store attributes in a list instead of a dict', 0), (@q, 'B', 'They don''t; each instance dict is a full copy', 0), (@q, 'C', 'Python compresses dicts of the same size', 0), (@q, 'D', 'Instance __dict__s share one keys table (key-sharing dicts) and store only their own values', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'code_output', 'What does this print?', 'class E:\n    def __eq__(self, o):\n        print("eq called")\n        return True\n    def __hash__(self):\n        return 1\n\nk = E()\nd = {k: "v"}\nprint(d[k])\nprint(d[E()])', 'python', 'v\neq called\nv', 'Python checks identity before calling __eq__.', 'Looking up the very same object short-circuits on `is`, so __eq__ never runs. A different object with the same hash needs __eq__ to confirm.', ' d[key]:  hash(key) -> slot\n          stored is key?  -- yes --> found (no __eq__)\n                |no\n          stored == key?  -- yes --> found', NULL, 139);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'eq called\nv\neq called\nv', 0), (@q, 'B', 'v\nv', 0), (@q, 'C', 'v\neq called\nv', 1), (@q, 'D', 'v\nKeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 4, 'mcq', 'Loading a checkpoint fails with: Missing keys ''fc.weight'' ... Unexpected keys ''module.fc.weight''. What''s the usual fix?', NULL, NULL, 'Strip the ''module.'' prefix from every key with a dict comprehension before load_state_dict', 'Compare the two key names character by character.', 'Models saved while wrapped in DataParallel/DDP get ''module.'' in every key. {k.removeprefix(''module.''): v for k, v in sd.items()} makes the names match.', NULL, NULL, 140);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Call load_state_dict twice', 0), (@q, 'B', 'Convert the state_dict to a list', 0), (@q, 'C', 'Strip the ''module.'' prefix from every key with a dict comprehension before load_state_dict', 1), (@q, 'D', 'Retrain the model from scratch', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 4, 'code_output', 'What does this print?', 'cfg = {"lr": 0.1, "bs": 32}\nresults = {tuple(sorted(cfg.items())): 0.91}\nsame = {"bs": 32, "lr": 0.1}\nprint(results[tuple(sorted(same.items()))])', 'python', '0.91', 'A dict can''t be a key, but a sorted tuple of its items can.', 'Sorting the items makes the key independent of insertion order, and the tuple is hashable. That''s how you cache experiment results per hyperparameter setting.', NULL, NULL, 141);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'None', 0), (@q, 'B', 'KeyError', 0), (@q, 'C', 'TypeError', 0), (@q, 'D', '0.91', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 4, 'code_output', 'What does this print?', 'import json\nimport numpy as np\nprint(json.dumps({"a": np.float64(0.5)}))\njson.dumps({"b": np.float32(0.5)})', 'python', '{"a": 0.5}\nTypeError', 'One NumPy float type is a subclass of Python''s float.', 'np.float64 subclasses float, so json accepts it; np.float32 doesn''t, giving ''Object of type float32 is not JSON serializable''. Convert metrics with float(x) before logging.', NULL, NULL, 142);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '{"a": np.float64(0.5)}\nTypeError', 0), (@q, 'C', '{"a": 0.5}\n{"b": 0.5}', 0), (@q, 'D', '{"a": 0.5}\nTypeError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'crud'), 1, 'mcq', 'Which line creates an empty dictionary?', NULL, NULL, 'd = {}', 'Curly braces are for dicts (and, with items, sets).', '{} is an empty dict, [] an empty list, () an empty tuple and set() an empty set. In ML code you''d start a metrics log like this: metrics = {}.', NULL, NULL, 143);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'd = []', 0), (@q, 'B', 'd = {}', 1), (@q, 'C', 'd = ()', 0), (@q, 'D', 'd = set()', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 1, 'true_false', 'A tokenizer''s vocabulary, which maps each token to a number, is naturally stored as a dict.', NULL, NULL, 'True', 'You look up a token and want its id back fast.', 'token -> id is a key -> value lookup, and dicts do it in O(1). Tokenizers keep this dict plus the reverse (id -> token) to decode.', ' "the"  -> 1\n "cat"  -> 2      "the cat" -> [1, 2]\n "<unk>"-> 0      (unknown words)', NULL, 144);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'get-setdefault'), 2, 'mcq', 'When is `d[k]` a better choice than `d.get(k)`?', NULL, NULL, 'When the key must exist: a KeyError points straight at the bug instead of a None leaking further', 'Failing loudly is sometimes the point.', 'get hides a missing required key behind None, and the crash shows up later somewhere unrelated. Use d[k] for required fields and get for truly optional ones.', NULL, 'Like a required field in an API schema: reject the request at once rather than storing a null and failing in a report a week later.', 145);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'When the dict is empty', 0), (@q, 'B', 'Never; get is always safer', 0), (@q, 'C', 'When the key is a string', 0), (@q, 'D', 'When the key must exist: a KeyError points straight at the bug instead of a None leaking further', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 2, 'mcq', 'What''s the difference between `json.load` and `json.loads`?', NULL, NULL, 'load reads from an open file object; loads parses a string', 'The s stands for ''string''.', 'json.load(f) reads JSON from a file object; json.loads(text) parses text you already have (e.g. an HTTP response body). The same pair exists for writing: dump and dumps.', NULL, NULL, 146);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'loads loads several files at once', 0), (@q, 'B', 'There''s no difference', 0), (@q, 'C', 'load reads from an open file object; loads parses a string', 1), (@q, 'D', 'load is the older, slower version', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 2, 'fill_blank', 'To write readable, indented JSON, call `json.dumps(cfg, ____=2)`.', NULL, NULL, 'indent', 'The keyword describes how far each level is pushed in.', 'indent=2 puts each key on its own line with two spaces per level, the usual format for config files you commit to git.', NULL, NULL, 147);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 3, 'mcq', 'What is the average cost of building a dict from n (key, value) pairs?', NULL, NULL, 'O(n): each insert is O(1) on average, including occasional resizes', 'Add up n average-O(1) inserts.', 'Each insert hashes the key and drops it in a slot. Resizes double the table, so their cost spreads out (amortised), just like list appends.', NULL, NULL, 148);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'O(1): dicts are built lazily', 0), (@q, 'B', 'O(n^2): each insert scans the earlier keys', 0), (@q, 'C', 'O(n): each insert is O(1) on average, including occasional resizes', 1), (@q, 'D', 'O(n log n): keys are kept sorted', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merging'), 3, 'true_false', '`{**a, **b}` works in Python 3.5+, while `a | b` needs Python 3.9 or newer.', NULL, NULL, 'True', 'The | operator for dicts was added by PEP 584.', 'Unpacking in dict literals came first (PEP 448, 3.5); the merge operators | and |= arrived in 3.9. Older servers and Colab images may still matter.', NULL, NULL, 149);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sets'), 3, 'mcq', 'Which set expression gives the tokens that appear in the test set but never in training (out-of-vocabulary tokens)?', NULL, NULL, 'test_tokens - train_tokens', 'In test, and not in train.', 'a - b keeps what''s in a but not in b. A high OOV rate warns you that the model will see many words it never learned.', '   train         test\n (  ....  ( both )  OOV )\n                    ^^^\n          test_tokens - train_tokens', NULL, 150);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'train_tokens - test_tokens', 0), (@q, 'B', 'test_tokens & train_tokens', 0), (@q, 'C', 'test_tokens - train_tokens', 1), (@q, 'D', 'test_tokens | train_tokens', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 4, 'mcq', 'Why do larger projects move configs from plain dicts to dataclasses or pydantic models?', NULL, NULL, 'A typo like cfg[''lerning_rate''] fails late or silently; typed fields catch wrong names and types at load time', 'What happens when you misspell a dict key?', 'A dict accepts any key, so a typo creates a new key (on write) or a KeyError deep inside training (on read). A schema validates names, types and ranges once, up front.', NULL, 'Like moving from untyped JS objects to TypeScript interfaces.', 151);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Dict lookups are too slow for configs', 0), (@q, 'B', 'Dataclasses use less memory than any dict', 0), (@q, 'C', 'A typo like cfg[''lerning_rate''] fails late or silently; typed fields catch wrong names and types at load time', 1), (@q, 'D', 'Dicts can''t be saved to JSON', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iteration'), 4, 'true_false', 'In Python 3, `for k, v in d.items():` first copies every pair into a new list, as Python 2 did.', NULL, NULL, 'False', 'What does items() return in Python 3?', 'items() returns a view, a lightweight window over the dict, with no copy. That''s why it''s cheap, and also why changing the dict''s size during the loop is an error.', NULL, NULL, 152);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'crud'), 1, 'mcq', 'What happens when you read `d["missing"]` and that key isn''t in the dict?', NULL, NULL, 'It raises KeyError', 'Square brackets insist that the key exists.', 'd[k] raises KeyError for a missing key (IndexError is the list version). d.get(k) returns None instead. In a web backend an unhandled KeyError on a request field becomes a 500 error, so validate required fields and use get for optional ones.', NULL, NULL, 153);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It raises KeyError', 1), (@q, 'B', 'It raises IndexError', 0), (@q, 'C', 'It returns None', 0), (@q, 'D', 'It returns an empty string', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'crud'), 1, 'true_false', 'Two different keys in one dict can hold the same value, e.g. `{"amy": 90, "bob": 90}`.', NULL, NULL, 'True', 'Which side must be unique: keys or values?', 'Keys are unique; values can repeat freely. That''s why there''s no built-in lookup by value, and why flipping a dict (value -> key) can lose entries when values repeat.', NULL, NULL, 154);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 1, 'mcq', 'Why store hyperparameters as `{"lr": 0.001, "batch_size": 32}` rather than as the list `[0.001, 32]`?', NULL, NULL, 'Each value has a name, so code reads cfg[''lr''] instead of remembering that position 0 means learning rate', 'Which one is easier to read six months later?', 'Named keys make a config self-describing and order-independent: adding a new setting doesn''t shift the others. That''s why YAML/JSON configs, Hugging Face model configs and experiment trackers all use key -> value mappings.', NULL, 'Like named query parameters ?lr=0.001&batch_size=32 instead of a positional URL like /0.001/32.', 155);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A list can''t be saved to a file', 0), (@q, 'B', 'Lists can''t hold floats', 0), (@q, 'C', 'Dicts use less memory than lists', 0), (@q, 'D', 'Each value has a name, so code reads cfg[''lr''] instead of remembering that position 0 means learning rate', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'crud'), 1, 'fill_blank', 'To get all the keys of `d` as a list, write `list(d.____())`.', NULL, NULL, 'keys', 'The plural of the thing you look values up by.', 'd.keys() returns a view of the keys and list() turns it into a list. list(d) gives the same result, because iterating a dict yields its keys.', NULL, NULL, 156);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sets'), 1, 'true_false', 'A set can hold the same value twice.', NULL, NULL, 'False', 'What is a set''s main job?', 'A set keeps at most one copy of each value; adding a duplicate does nothing. That''s why len(set(user_ids)) is the quick way to count unique users.', NULL, NULL, 157);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 1, 'mcq', 'After `json.loads`, what Python type does a JSON array such as `[1, 2, 3]` become?', NULL, NULL, 'list', 'JSON arrays are ordered and allow duplicates.', 'JSON objects become dicts and JSON arrays become lists. JSON has no tuples or sets, so even a tuple you dumped comes back as a list.', NULL, NULL, 158);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'list', 1), (@q, 'B', 'dict', 0), (@q, 'C', 'set', 0), (@q, 'D', 'tuple', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'get-setdefault'), 2, 'fill_blank', 'Count words without a KeyError: `counts[w] = counts.____(w, 0) + 1`.', NULL, NULL, 'get', 'The method that takes a fallback value.', 'counts.get(w, 0) gives the current count, or 0 the first time a word appears, then the +1 result is stored. For big jobs Counter(words) does the same in one call and adds most_common().', NULL, NULL, 159);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iteration'), 2, 'true_false', '`for k in d.keys():` and `for k in d:` loop over exactly the same things.', NULL, NULL, 'True', 'What does iterating a dict give you?', 'Iterating a dict yields its keys, so .keys() is redundant in a plain loop (linters flag it). .keys() earns its place when you want the view object itself, e.g. for set operations like d.keys() & other.keys().', NULL, NULL, 160);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merging'), 2, 'mcq', 'You merge default settings with a user''s overrides. Which expression lets the user''s values win?', NULL, NULL, '{**defaults, **user}', 'On a clash, the dict unpacked later wins.', 'Later entries overwrite earlier ones, so the defaults go first and the overrides last. defaults | user is the 3.9+ spelling of the same thing; user | defaults lets the defaults win and silently ignores what the user chose. zip pairs up keys with keys.', NULL, 'Like CSS: a later rule for the same property overrides an earlier one.', 161);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'user | defaults', 0), (@q, 'B', 'dict(zip(defaults, user))', 0), (@q, 'C', '{**defaults, **user}', 1), (@q, 'D', '{**user, **defaults}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'collections'), 2, 'mcq', 'When is `Counter` a better fit than `defaultdict(int)`?', NULL, NULL, 'When you''re counting and want most_common(), counter arithmetic, and 0 for missing keys without inserting them', 'One of them was built specifically for tallies.', 'Both start missing counts at 0, but Counter adds counting tools: most_common(n), + and - between counters, total(), and reads of missing keys that don''t insert them. defaultdict(int) is the general tool when the counts are just one part of a bigger structure.', NULL, NULL, 162);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'When you need the keys kept sorted', 0), (@q, 'B', 'When the values must be lists', 0), (@q, 'C', 'Never; Counter is just an older name for defaultdict(int)', 0), (@q, 'D', 'When you''re counting and want most_common(), counter arithmetic, and 0 for missing keys without inserting them', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sets'), 2, 'fill_blank', '`list(dict.____(items))` removes duplicates from a list while keeping the first-seen order.', NULL, NULL, 'fromkeys', 'It builds a dict from an iterable of keys.', 'dict.fromkeys(items) makes each item a key (with value None); duplicates collapse and the dict keeps insertion order. list(set(items)) also de-duplicates but loses the order, which matters for things like a list of class names.', NULL, NULL, 163);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 2, 'true_false', 'Checking `key in d` takes about the same time whether `d` has 10 keys or 10 million.', NULL, NULL, 'True', 'Does a hash lookup scan the keys?', 'On average a dict membership test is O(1): hash the key, jump to its slot, confirm with ==. A list `in` is O(n), so over that range it gets about a million times slower. That''s the reason to keep lookup tables (vocabularies, caches, blocklists) in dicts or sets.', NULL, NULL, 164);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hashability'), 2, 'mcq', 'Why can a tuple be a dict key while a list can''t?', NULL, NULL, 'A key''s hash must never change; a tuple is immutable, but a list could change after insertion and be lost', 'What would happen if a key changed after it was stored?', 'The dict files each key under its hash. If a list key were mutated, its hash would change and lookups would go to the wrong slot, so Python refuses lists outright (TypeError: unhashable type). A tuple of hashable items can''t change, so its hash is stable.', ' d[(1, 2)] = "x"\n hash((1, 2)) -> slot 5 -> stored\n tuple can''t change -> always slot 5 -> found\n a list could change -> new hash -> wrong slot', 'Like a primary key in a database table: rows aren''t allowed to change it after insert.', 165);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Lists are too large to be keys', 0), (@q, 'B', 'Tuples are faster to compare than lists', 0), (@q, 'C', 'A key''s hash must never change; a tuple is immutable, but a list could change after insertion and be lost', 1), (@q, 'D', 'Dicts only accept keys of a fixed length', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'comprehensions'), 2, 'mcq', 'An API should keep only the allowed fields from a client''s JSON body. Which line does that?', NULL, NULL, '{k: v for k, v in payload.items() if k in ALLOWED}', 'You want a dict back, filtered by key.', 'A dict comprehension with an if filters pairs by key. The second option builds a set of names, the third a list of values. Allow-listing fields like this stops a client sneaking in keys such as is_admin (a ''mass assignment'' bug). Make ALLOWED a set so each check is O(1).', NULL, NULL, 166);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{k for k in payload if k in ALLOWED}', 0), (@q, 'B', '[v for k, v in payload.items() if k in ALLOWED]', 0), (@q, 'C', '{k: v for k, v in payload.items() if k in ALLOWED}', 1), (@q, 'D', '{k: v for k in ALLOWED for v in payload}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 2, 'true_false', '`json.dumps` sorts the keys alphabetically by default.', NULL, NULL, 'False', 'Dicts remember insertion order. Does dumps keep it?', 'dumps writes keys in the dict''s insertion order. Pass sort_keys=True when you need a stable, canonical text, e.g. to hash a config or to keep diffs of committed JSON files small.', NULL, NULL, 167);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 2, 'mcq', 'A tokenizer meets a word that isn''t in `vocab`. Which lookup maps it to the unknown-token id without changing the vocab?', NULL, NULL, 'vocab.get(tok, UNK_ID)', 'One option raises, and one quietly writes to the vocab.', 'get returns the fallback without inserting anything. vocab[tok] raises KeyError before `or` ever runs. setdefault stores the word, so the vocab grows with every typo seen at inference. The last option searches the ids instead of the tokens and then indexes a missing key.', NULL, NULL, 168);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'vocab.setdefault(tok, UNK_ID)', 0), (@q, 'B', 'vocab.get(tok, UNK_ID)', 1), (@q, 'C', 'UNK_ID if tok in vocab.values() else vocab[tok]', 0), (@q, 'D', 'vocab[tok] or UNK_ID', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'crud'), 3, 'mcq', 'When can''t you build a dict with the keyword form, as in `dict(lr=0.1)`?', NULL, NULL, 'When a key isn''t a valid Python name, such as ''learning-rate'', ''class'' or the int 1; use a {...} literal instead', 'Keyword arguments have naming rules.', 'dict(a=1) turns keyword argument names into string keys, so each key must be a legal identifier: no dashes, no keywords like class, no ints. A literal {''learning-rate'': 0.1, 1: ''dog''} has no such limit. Related: dict(**cfg) and f(**cfg) raise TypeError (''keywords must be strings'') when cfg has non-string keys.', NULL, NULL, 169);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'When a key isn''t a valid Python name, such as ''learning-rate'', ''class'' or the int 1; use a {...} literal instead', 1), (@q, 'B', 'When the dict will later be passed to json.dumps', 0), (@q, 'C', 'When the values are floats', 0), (@q, 'D', 'When there are more than 255 keys', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'get-setdefault'), 3, 'mcq', 'This memoisation attempt calls `compute` on every pass (calls ends at 3). Why, and what''s the fix?', 'calls = 0\n\ndef compute(k):\n    global calls\n    calls += 1\n    return k * 2\n\ncache = {}\nfor _ in range(3):\n    cache.setdefault("a", compute("a"))\nprint(calls)', 'python', 'The default argument is evaluated before setdefault runs, even when the key exists; check `if k not in cache:` first', 'When are a function''s arguments evaluated?', 'Python evaluates compute(''a'') first and only then calls setdefault, which throws the value away when ''a'' already exists. The expensive work repeats every time and the cache does nothing. Check membership first (if k not in cache: cache[k] = compute(k)), or use functools.lru_cache for pure functions.', ' cache.setdefault("a", compute("a"))\n                       ^ runs FIRST, every time\n then: "a" in cache? yes -> new value thrown away', 'Like cooking a meal and only then checking the fridge, where yesterday''s portion was waiting.', 170);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Strings can''t be used as cache keys', 0), (@q, 'B', 'setdefault only works on a defaultdict', 0), (@q, 'C', 'setdefault clears the dict on every call', 0), (@q, 'D', 'The default argument is evaluated before setdefault runs, even when the key exists; check `if k not in cache:` first', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iteration'), 3, 'true_false', '`("lr", 0.1) in cfg.items()` is a fast hash lookup, not a scan over every pair.', NULL, NULL, 'True', 'The view can find the key first, then compare the value.', 'An items view checks membership by looking the key up in the hash table and then comparing the stored value with ==, so it''s O(1) on average and works even when the values are unhashable. By contrast `0.1 in cfg.values()` has no index and scans every value.', NULL, NULL, 171);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ordering'), 3, 'mcq', 'A frontend team''s code depends on the key order of the JSON your Python API returns. Is that safe?', NULL, NULL, 'Python keeps insertion order and json.dumps preserves it, but JSON objects are unordered by spec, so clients shouldn''t rely on it; send an array when order matters', 'There are two layers: what Python does, and what JSON promises.', 'Your side is stable: dicts keep insertion order and dumps writes keys in that order. But the JSON standard (RFC 8259) treats objects as unordered, and other serialisers, gateways or languages may reorder them. If the order means something (a ranking, pipeline steps), send a list.', NULL, 'Like relying on SQL rows coming back in insertion order without an ORDER BY: it usually works, until it doesn''t.', 172);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'No: json.dumps writes keys in a random order', 0), (@q, 'B', 'Yes: the JSON spec guarantees object key order', 0), (@q, 'C', 'Only when every key is an int', 0), (@q, 'D', 'Python keeps insertion order and json.dumps preserves it, but JSON objects are unordered by spec, so clients shouldn''t rely on it; send an array when order matters', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ordering'), 3, 'true_false', 'Dict insertion order is a language guarantee from Python 3.7; CPython 3.6 already kept the order, but only as an implementation detail.', NULL, NULL, 'True', 'One version changed the code, the next changed the docs.', '3.6 introduced the compact dict layout, which kept order as a side effect; 3.7 made it part of the language spec, so every Python implementation must do it. Code for 3.5 and older couldn''t rely on it, which is why OrderedDict is so common in older ML code.', NULL, NULL, 173);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hashability'), 3, 'mcq', 'A label map built from user-entered data ends up with the keys ''Cat'', ''cat'' and ''cat ''. What''s the robust fix?', NULL, NULL, 'Normalise every key in one helper (e.g. key.strip().lower()) and use it for both inserts and lookups', 'To a dict these are three different strings.', 'String keys match exactly, so case and whitespace variants become separate classes and split your training data. Normalising in one place, used at write time and read time, keeps training, serving and analytics in agreement. The same applies to email addresses as user ids in a backend.', NULL, NULL, 174);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Sort the keys', 0), (@q, 'B', 'Use a frozenset of the variants as the key', 0), (@q, 'C', 'Normalise every key in one helper (e.g. key.strip().lower()) and use it for both inserts and lookups', 1), (@q, 'D', 'Use a list instead of a dict', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'comprehensions'), 3, 'mcq', 'You want to invert `role_of` without losing anyone. Which approach works?', 'from collections import defaultdict\nrole_of = {"amy": "admin", "bob": "user", "cat": "user"}\nby_role = defaultdict(list)\nfor name, role in role_of.items():\n    by_role[role].append(name)\nprint(dict(by_role))', 'python', 'The defaultdict(list) loop in the snippet, which groups names per role', 'Several people can share one role.', 'With repeated values, a one-to-one inversion keeps only the last name per role; zip and sorting don''t change that. Grouping into lists keeps everyone: {''admin'': [''amy''], ''user'': [''bob'', ''cat'']}. Pick based on whether the mapping is really one-to-one (label2id) or many-to-one (user -> role).', NULL, NULL, 175);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The defaultdict(list) loop in the snippet, which groups names per role', 1), (@q, 'B', 'dict(zip(role_of.values(), role_of.keys()))', 0), (@q, 'C', '{role: name for name, role in role_of.items()}', 0), (@q, 'D', '{v: k for k, v in sorted(role_of.items())}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merging'), 3, 'mcq', 'Config layers: built-in defaults, then a config file, then environment variables, then command-line flags, with later layers winning. Which expression builds the final config?', NULL, NULL, 'defaults | file_cfg | env_cfg | cli_cfg', 'With |, the right-hand side wins.', '| works left to right and the right side wins, so the most important layer goes last. Remember it''s shallow: a nested ''optimizer'' dict in cli_cfg replaces the whole nested dict from the lower layers, which is why config tools like Hydra and OmegaConf deep-merge. & isn''t defined for dicts at all.', ' defaults  {lr: 0.1,  bs: 32, epochs: 10}\n file_cfg  {bs: 64}\n env_cfg   {epochs: 3}\n cli_cfg   {lr: 0.01}\n result    {lr: 0.01, bs: 64, epochs: 3}', NULL, 176);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{**cli_cfg, **defaults}', 0), (@q, 'B', 'defaults | file_cfg | env_cfg | cli_cfg', 1), (@q, 'C', 'cli_cfg | env_cfg | file_cfg | defaults', 0), (@q, 'D', 'defaults & file_cfg & env_cfg & cli_cfg', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'collections'), 3, 'true_false', '`json.dumps(defaultdict(list, a=[1]))` works, because defaultdict is a subclass of dict.', NULL, NULL, 'True', 'Does json check for exactly dict, or for any dict subclass?', 'json serialises any dict subclass, so defaultdict, Counter and OrderedDict all dump as plain JSON objects. The default factory isn''t saved, though: json.loads gives back a plain dict, so code that relied on auto-created keys hits KeyError after a reload.', NULL, NULL, 177);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sets'), 3, 'mcq', '`set(rows)` on a list of dict rows raises TypeError. How does the snippet de-duplicate them?', 'rows = [{"id": 1, "x": 5}, {"x": 5, "id": 1}, {"id": 2, "x": 7}]\nseen, unique = set(), []\nfor r in rows:\n    key = tuple(sorted(r.items()))\n    if key not in seen:\n        seen.add(key)\n        unique.append(r)\nprint(len(unique))', 'python', 'It turns each row into a hashable fingerprint, tuple(sorted(r.items())), and keeps the rows whose fingerprint is new', 'Dicts are unhashable, but what about a tuple of their items?', 'Dicts can''t go in a set, so each row gets a hashable fingerprint. Sorting the items makes rows with the same fields in a different order count as duplicates (2 unique rows here). If rows have a real id, de-duplicate on that instead. Nested dict values need a deeper fingerprint, such as json.dumps(r, sort_keys=True).', NULL, NULL, 178);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It sorts the list first, which makes set() work', 0), (@q, 'B', 'It uses frozenset(rows)', 0), (@q, 'C', 'It turns each row into a hashable fingerprint, tuple(sorted(r.items())), and keeps the rows whose fingerprint is new', 1), (@q, 'D', 'It calls set() twice', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 3, 'mcq', 'Why is `x in d.keys()` as fast as `x in d`, while `x in list(d.keys())` is slow?', NULL, NULL, 'The keys view looks x up in the hash table; list() copies every key into a list that `in` then scans, O(n)', 'What does list() build?', 'A keys view is a thin window onto the dict, so membership is a hash lookup. Wrapping it in list() costs O(n) to copy and O(n) per search. The habit comes from Python 2, where keys() returned a list, and it can make a hot loop quadratic.', ' x in d.keys()        -> hash(x) -> slot -> done   O(1)\n x in list(d.keys())  -> copy n keys, then\n                         compare one by one        O(n)', NULL, 179);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The keys view looks x up in the hash table; list() copies every key into a list that `in` then scans, O(n)', 1), (@q, 'B', 'keys() caches its answer between calls', 0), (@q, 'C', 'It isn''t; all three are O(1)', 0), (@q, 'D', 'list() sorts the keys', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 3, 'fill_blank', 'The built-in function a dict calls on a key to decide which slot to look in is ____().', NULL, NULL, 'hash', 'It''s the function that fails with ''unhashable type''.', 'hash(key) returns an integer; the dict uses some of its bits to pick a slot, then == confirms the match. Objects whose __hash__ is None (lists, dicts, sets) can''t be keys for exactly this reason.', NULL, NULL, 180);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 3, 'mcq', 'An endpoint returns `{"created": datetime.now()}` and `json.dumps` raises TypeError. What''s the usual fix?', NULL, NULL, 'Convert the datetime to an ISO-8601 string with dt.isoformat(), or pass a default= hook such as default=str', 'JSON has no date type.', 'JSON only has strings, numbers, booleans, null, arrays and objects, so dates travel as strings. isoformat() gives ''2026-01-01T00:00:00'', which every client can parse. default=str is a quick catch-all for logs; for an API be explicit so the format stays stable. Frameworks such as FastAPI do this conversion for you. Never send pickle to clients.', NULL, 'The same as JS, where JSON.stringify(new Date()) turns the date into an ISO string.', 181);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Use pickle instead of JSON for API responses', 0), (@q, 'B', 'Call json.dumps twice', 0), (@q, 'C', 'Wrap the datetime in a list', 0), (@q, 'D', 'Convert the datetime to an ISO-8601 string with dt.isoformat(), or pass a default= hook such as default=str', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 3, 'mcq', 'Training builds `label2id = {lab: i for i, lab in enumerate(set(labels))}`, and the serving process rebuilds it the same way. Served predictions come out as the wrong classes. Why?', NULL, NULL, 'The order of a set of strings can change between processes (hash randomisation), so the ids differ; use sorted(set(labels)) and save the map with the model', 'Will a new Python process list the same set of strings in the same order?', 'String hashes are salted per process, so the set''s iteration order, and therefore every id, can differ between training and serving. sorted() gives a deterministic order, and saving label2id / id2label next to the weights (as Hugging Face configs do) removes the guesswork.', ' training: set -> [''dog'', ''cat''] -> dog=0, cat=1\n serving:  set -> [''cat'', ''dog''] -> cat=0, dog=1\n model says 0 (meant dog) -> served as "cat"', NULL, 182);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The order of a set of strings can change between processes (hash randomisation), so the ids differ; use sorted(set(labels)) and save the map with the model', 1), (@q, 'B', 'set() drops the last label', 0), (@q, 'C', 'enumerate starts counting at 1 in the serving process', 0), (@q, 'D', 'Dict comprehensions build keys in a random order', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hashability'), 4, 'mcq', 'Why do both lookups find the float key?', 'from fractions import Fraction\nfrom decimal import Decimal\nd = {0.5: "half"}\nprint(d[Fraction(1, 2)], d[Decimal("0.5")])', 'python', 'Equal numbers of the built-in numeric types are guaranteed equal hashes, and 0.5 == Fraction(1, 2) == Decimal(''0.5'')', 'What must == and hash() agree on?', 'Python defines numeric hashing so that x == y implies hash(x) == hash(y) across int, float, Fraction and Decimal. The lookup lands in the right slot and == confirms it. It''s the same rule that collapses 1, 1.0 and True into one key, where the first key object inserted is the one kept.', NULL, NULL, 183);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Python converts every numeric key to float before storing it', 0), (@q, 'B', 'Equal numbers of the built-in numeric types are guaranteed equal hashes, and 0.5 == Fraction(1, 2) == Decimal(''0.5'')', 1), (@q, 'C', 'Fraction and Decimal are subclasses of float', 0), (@q, 'D', 'Dict lookups compare str(key)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'mcq', 'Two equal users end up as two separate keys. Which rule does this class break?', 'class User:\n    def __init__(self, uid):\n        self.uid = uid\n    def __eq__(self, other):\n        return self.uid == other.uid\n    __hash__ = object.__hash__\n\nseen = {User(1): "a", User(1): "b"}\nprint(len(seen))', 'python', 'Objects that compare equal must have equal hashes; here the hash is identity-based while __eq__ is value-based', 'Equal values, but where does each one get filed?', 'object.__hash__ is based on identity, so the two equal users land in different slots and == never gets a chance to compare them. Fix it with def __hash__(self): return hash(self.uid), or a frozen dataclass. Python disables hashing when you define only __eq__ precisely to prevent this; re-attaching object.__hash__ brings the bug back.', ' User(1) #A -> hash(identity A) -> slot 3\n User(1) #B -> hash(identity B) -> slot 6\n               (== is never asked)\n result: 2 "equal" keys', NULL, 184);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '__hash__ must be defined before __eq__ in the class body', 0), (@q, 'B', 'Dict keys must be built-in immutable types', 0), (@q, 'C', 'Objects that compare equal must have equal hashes; here the hash is identity-based while __eq__ is value-based', 1), (@q, 'D', '__eq__ must return a bool', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'true_false', 'CPython stores each key''s hash inside the dict entry, so when the table grows it re-slots the keys without calling `__hash__` again.', NULL, NULL, 'True', 'Re-hashing every long string on each resize would be wasteful.', 'Each entry holds (hash, key, value). A resize rebuilds the index table from the stored hashes, so a key''s __hash__ runs once on insert (and once per lookup), never during growth. It''s also why a key whose hash changes after insertion is lost: the dict trusts the stored value.', NULL, NULL, 185);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iteration'), 4, 'true_false', '`d.items() & other` only works if all the values in `d` are hashable, even though `(k, v) in d.items()` works with unhashable values.', NULL, NULL, 'True', 'A set operation builds a real set of the pairs.', '& on an items view creates a set of (key, value) tuples, so a list value raises TypeError: unhashable type. Membership is different: it looks the key up and compares the value with ==, so the value is never hashed. keys() views never have this problem, because keys are always hashable.', NULL, NULL, 186);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ordering'), 4, 'mcq', 'A plain dict (not an OrderedDict) serves as a small LRU cache. How do you mark key `k` as most recently used?', NULL, NULL, 'd[k] = d.pop(k), which removes it and re-inserts it at the end', 'Overwriting a key keeps its position. What actually moves it?', 'Assigning to an existing key (directly or via update) keeps its old position, and plain dicts have no move_to_end (AttributeError). Popping and re-inserting puts it at the end, and next(iter(d)) is then the least recently used key to evict. OrderedDict.move_to_end does the same, and functools.lru_cache already does all of it for function results.', ' d: [a, b, c]\n d["a"] = d["a"]       -> [a, b, c]   (no move)\n d["a"] = d.pop("a")   -> [b, c, a]   (a = newest)\n evict next(iter(d))   -> "b"', NULL, 187);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'd[k] = d.pop(k), which removes it and re-inserts it at the end', 1), (@q, 'B', 'd[k] = d[k], which re-assigns it', 0), (@q, 'C', 'd.move_to_end(k)', 0), (@q, 'D', 'd.update({k: d[k]})', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'collections'), 4, 'mcq', 'What does `|` mean between two Counters, e.g. `Counter(a=3, b=1) | Counter(a=1, b=2)`?', NULL, NULL, 'Element-wise maximum: Counter({''a'': 3, ''b'': 2})', 'Counter treats | and & as multiset union and intersection.', 'Counter overrides | to take the larger count per key and & to take the smaller one, while + adds counts. So the dict intuition ''right side wins'' is wrong for Counters. Merging token counts from two corpora needs +; | gives the highest count seen in either.', NULL, NULL, 188);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Element-wise maximum: Counter({''a'': 3, ''b'': 2})', 1), (@q, 'B', 'Sum of the counts: Counter({''a'': 4, ''b'': 3})', 0), (@q, 'C', 'Right side wins, like dict |: Counter({''a'': 1, ''b'': 2})', 0), (@q, 'D', 'Keys in both, count 1 each: Counter({''a'': 1, ''b'': 1})', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 4, 'mcq', 'Your API returns `{"id": 12345678901234567890}` from a Python int. Python reads it back exactly, but the JavaScript frontend shows a different id. Why, and what''s the usual fix?', NULL, NULL, 'JS numbers are 64-bit floats that lose integer precision above 2**53; send large ids as strings', 'Python ints have unlimited precision. Do JavaScript numbers?', 'json.dumps writes the exact digits and Python''s json.loads reads them back exactly. JSON.parse, however, turns every number into a double, which holds integers exactly only up to 2**53 (about 9e15), so the last digits change. Big public APIs ship an extra string id field for exactly this. Snowflake and bigint ids are the usual victims.', NULL, 'Like pasting a 20-digit card number into a spreadsheet cell formatted as a number: the last digits silently turn into zeros.', 189);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'JSON forbids integers larger than 2**31', 0), (@q, 'B', 'The frontend re-sorts the keys', 0), (@q, 'C', 'json.dumps rounds big ints to 15 digits', 0), (@q, 'D', 'JS numbers are 64-bit floats that lose integer precision above 2**53; send large ids as strings', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 4, 'mcq', 'This immutable-update style is common in React reducers. In Python, what does the loop cost for n keys?', 'state = {}\nfor i in range(5):\n    state = {**state, f"k{i}": i}\nprint(len(state))', 'python', 'O(n^2) overall: each step copies the whole dict to add one key; assign in place when nobody else holds a reference', 'What does {**state, ...} build on every pass?', 'Each iteration builds a brand-new dict holding all previous keys, so step i costs O(i) and the loop costs O(n^2), with lots of garbage for the allocator. In-place state[k] = v is O(1) on average. Keep copy-on-write for boundaries where sharing matters, such as handing a config to callers, not inside hot loops.', ' step 1: copy 0 keys  + add 1\n step 2: copy 1 key   + add 1\n step n: copy n-1     + add 1\n total ~ n^2 / 2 key copies', 'Like recopying a whole notebook by hand every time you want to add one line.', 190);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'O(n log n): the keys are re-sorted each time', 0), (@q, 'B', 'O(n): dict unpacking is free', 0), (@q, 'C', 'O(1) per step, because only the new key is hashed', 0), (@q, 'D', 'O(n^2) overall: each step copies the whole dict to add one key; assign in place when nobody else holds a reference', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 4, 'mcq', '`@functools.lru_cache` on `def build_model(cfg: dict)` raises TypeError. Which cache key works for nested configs like `{"opt": {"lr": 0.1}}`?', NULL, NULL, 'json.dumps(cfg, sort_keys=True)', 'The key must be hashable, independent of key order, and cover nested values.', 'lru_cache hashes its arguments, and dicts are unhashable. tuple(sorted(cfg.items())) works for flat configs, but the tuple contains the inner dict, so hashing it raises TypeError. id(cfg) differs for equal copies and can be reused after an object is freed (wrong hits). frozenset(cfg) ignores the values. A sort_keys JSON string is canonical and nested-safe (as long as the values are JSON-serialisable), and doubles as an experiment id.', NULL, NULL, 191);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'id(cfg)', 0), (@q, 'B', 'json.dumps(cfg, sort_keys=True)', 1), (@q, 'C', 'tuple(sorted(cfg.items()))', 0), (@q, 'D', 'frozenset(cfg)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hashability'), 4, 'fill_blank', 'If a class defines `__eq__` but not `__hash__`, Python sets its `__hash__` attribute to ____.', NULL, NULL, 'None', 'The value that means ''nothing here''.', '__hash__ = None marks instances as unhashable, so using one as a key raises TypeError instead of silently breaking the ''equal objects have equal hashes'' rule. Define __hash__ from the same fields as __eq__, or use @dataclass(frozen=True).', NULL, NULL, 192);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'crud'), 1, 'mcq', 'How do you add a new setting `dropout` with the value 0.1 to the dict `cfg`?', NULL, NULL, 'cfg["dropout"] = 0.1', 'The same syntax you use to change an existing value.', 'Assigning to a key adds it if it''s missing and overwrites it if it''s there. Dicts have no add, append or insert methods (those belong to sets and lists), so the other options raise AttributeError.', NULL, NULL, 193);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'cfg["dropout"] = 0.1', 1), (@q, 'B', 'cfg.append({"dropout": 0.1})', 0), (@q, 'C', 'cfg.add("dropout", 0.1)', 0), (@q, 'D', 'cfg.insert("dropout", 0.1)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'crud'), 1, 'true_false', 'A dict''s values can be any type, including lists and other dicts.', NULL, NULL, 'True', 'The restriction you may have heard about applies to keys.', 'Values have no rules at all: numbers, strings, lists, functions, other dicts. Only keys must be hashable. That''s why a JSON API response, with lists and objects nested inside each other, maps so naturally onto Python dicts.', NULL, NULL, 194);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iteration'), 1, 'mcq', 'Which loop gives you only the values of the dict `prices`?', NULL, NULL, 'for v in prices.values():', 'Looping over a dict directly gives you something else.', 'values() yields just the values. Looping over the dict itself (or over keys()) yields the keys, and items() yields (key, value) pairs. For a total, sum(prices.values()) does it in one line.', ' prices = {"tea": 20, "coffee": 30}\n for x in prices          -> "tea", "coffee"\n for x in prices.values() -> 20, 30\n for x in prices.items()  -> ("tea", 20), ("coffee", 30)', NULL, 195);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'for v in prices.values():', 1), (@q, 'B', 'for v in prices.items():', 0), (@q, 'C', 'for v in prices:', 0), (@q, 'D', 'for v in prices.keys():', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'crud'), 1, 'fill_blank', 'Remove the key ''tmp'' from `d` and get its value back in one step: `v = d.____(''tmp'')`.', NULL, NULL, 'pop', 'Same name as the list method that removes and returns an item.', 'd.pop(k) deletes the key and returns its value; it raises KeyError if the key is missing unless you pass a default, d.pop(k, None). `del d[k]` also removes the key but gives you nothing back.', NULL, NULL, 196);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sets'), 1, 'mcq', 'Which expression gives every tag that appears in set `a`, set `b`, or both?', NULL, NULL, 'a | b', 'You want the combination of the two sets.', '| is union (everything in either set). & is intersection (only the shared items), - is ''in a but not b'', and + isn''t defined for sets (TypeError). Duplicates disappear automatically, because a set holds each value once.', '   a       b\n ( x  ( y ) z )      a | b -> x, y, z   (union)\n                     a & b -> y         (intersection)\n                     a - b -> x', NULL, 197);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'a | b', 1), (@q, 'B', 'a + b', 0), (@q, 'C', 'a & b', 0), (@q, 'D', 'a - b', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hashability'), 1, 'true_false', 'Strings, numbers and tuples of strings or numbers can all be used as dict keys.', NULL, NULL, 'True', 'What do these types have in common?', 'All of them are immutable and hashable, so their hash never changes while they sit in the dict. Tuples are handy for composite keys, such as (user_id, item_id) in a recommendation table.', NULL, NULL, 198);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 1, 'mcq', 'What does `json.dumps(cfg)` return?', NULL, NULL, 'A str of JSON text', 'The trailing ''s'' stands for ''string''.', 'dumps = ''dump to string'': it returns JSON text you can log, send in an HTTP body or store in a database. json.dump (no s) writes to an open file instead, and json.loads goes the other way, from text back to a dict.', NULL, NULL, 199);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A str of JSON text', 1), (@q, 'B', 'A new dict', 0), (@q, 'C', 'Nothing; it writes to a file', 0), (@q, 'D', 'bytes', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 1, 'mcq', 'A classifier uses `label_map = {''cat'': 0, ''dog'': 1, ''bird'': 2}`. What does `len(label_map)` usually tell you?', NULL, NULL, 'The number of classes, i.e. how many outputs the model''s last layer needs', 'len() of a dict counts its keys.', 'Each key is one class, so len(label_map) is 3 and the final layer needs 3 outputs (logits). Building the model from len(label_map) instead of a hard-coded 3 keeps the two in sync when a class is added.', NULL, NULL, 200);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The number of characters in the label names', 0), (@q, 'B', 'The number of training examples', 0), (@q, 'C', 'The number of classes, i.e. how many outputs the model''s last layer needs', 1), (@q, 'D', 'The highest accuracy the model can reach', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'collections'), 1, 'fill_blank', '`from collections import ____` gives a dict subclass that counts how often each item appears.', NULL, NULL, 'Counter', 'Its name says what it does; it starts with a capital letter.', 'Counter([''a'', ''b'', ''a'']) gives Counter({''a'': 2, ''b'': 1}), and missing items count as 0 instead of raising KeyError. most_common(k) returns the top k, e.g. the most frequent predicted labels.', NULL, NULL, 201);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'get-setdefault'), 1, 'mcq', 'Why would you read a value with `d.get(''k'', default)` rather than `d[''k'']`?', NULL, NULL, 'get returns the default instead of raising KeyError when the key is missing', 'What happens with each one when the key isn''t there?', 'd[''k''] raises KeyError for a missing key; get returns None, or the default you pass. Use get for optional fields, and d[''k''] when the key must exist, so a missing one fails loudly. get never changes the dict.', NULL, 'Like Java''s `map.getOrDefault(key, fallback)`: a missing key gives you the fallback instead of an error.', 202);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'd[''k''] is slower because it copies the dict', 0), (@q, 'B', 'get returns the default instead of raising KeyError when the key is missing', 1), (@q, 'C', 'get is the only way to read nested dicts', 0), (@q, 'D', 'get also adds the key to the dict', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'crud'), 2, 'mcq', 'A cleanup step removes the key ''debug'' from `cfg`, which may or may not have it. Which line never raises?', NULL, NULL, 'cfg.pop("debug", None)', 'One of these takes a fallback value.', 'pop with a default returns that default when the key is missing instead of raising KeyError. `del` and pop without a default both raise for a missing key, and dicts have no remove method (that''s for lists and sets). The pop(k, None) idiom makes the cleanup idempotent.', NULL, 'Like an idempotent DELETE endpoint that returns 204 whether or not the resource still existed.', 203);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'cfg.pop("debug")', 0), (@q, 'B', 'cfg.remove("debug")', 0), (@q, 'C', 'cfg.pop("debug", None)', 1), (@q, 'D', 'del cfg["debug"]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iteration'), 2, 'mcq', 'You want to print a dict''s keys in alphabetical order without changing the dict. Which loop does that?', NULL, NULL, 'for k in sorted(d):', 'Dicts and key views have no sort method.', 'sorted() accepts any iterable, and iterating a dict gives its keys, so sorted(d) is a new sorted list of keys; d itself is untouched. d.sort() and d.keys().sort() raise AttributeError, and sorted(d.values()) sorts the values, not the keys.', NULL, NULL, 204);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'for k in d.keys().sort():', 0), (@q, 'B', 'for k in d.sort():', 0), (@q, 'C', 'for k in sorted(d.values()):', 0), (@q, 'D', 'for k in sorted(d):', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'comprehensions'), 2, 'true_false', 'When a key appears twice in a dict comprehension''s input, the dict keeps the last value seen for that key.', NULL, NULL, 'True', 'Think of each pair as `d[k] = v`, run in order.', 'A comprehension assigns each pair in turn, so a later pair overwrites an earlier one, and the key keeps its original position. When you build a label map from raw rows, duplicates vanish silently: compare len(d) with the number of rows if that matters.', NULL, NULL, 205);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merging'), 2, 'mcq', '`cfg = cfg.update(overrides)` leaves `cfg` as None. Why?', NULL, NULL, 'update changes the dict in place and returns None', 'What do list.sort() and list.append() return?', 'Methods that change an object in place return None, and the assignment then throws away your dict. Write `cfg.update(overrides)` on its own line, or build a new dict with `cfg = cfg | overrides` (Python 3.9+).', NULL, NULL, 206);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'update returns a copy, and the copy is empty', 0), (@q, 'B', 'update deletes keys that aren''t in overrides', 0), (@q, 'C', 'update changes the dict in place and returns None', 1), (@q, 'D', 'overrides must be a list of pairs', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'collections'), 2, 'mcq', 'Which is the cleanest way to group training examples by their label?', NULL, NULL, 'by_label = defaultdict(list), then by_label[y].append(x) for each pair', 'You need a list per label that appears the first time the label does.', 'defaultdict(list) creates an empty list the first time a label is seen, so the append always works. A plain dict raises KeyError on the first append for each label. Counter adds numbers, not lists, and a set of pairs loses the grouping (and duplicates).', ' pairs:  (1,cat) (2,dog) (3,cat)\n by_label:\n   cat -> [1, 3]\n   dog -> [2]', NULL, 207);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'by_label = set(), then by_label.add((y, x))', 0), (@q, 'B', 'by_label = defaultdict(list), then by_label[y].append(x) for each pair', 1), (@q, 'C', 'by_label = Counter(), then by_label[y] += x', 0), (@q, 'D', 'by_label = {}, then by_label[y].append(x)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sets'), 2, 'fill_blank', '`{}` is an empty dict, so an empty set has to be written as ____.', NULL, NULL, 'set()', 'Call the type itself.', 'Curly braces with nothing inside were dicts long before sets existed, so {} stays a dict. {1, 2} is a set because it has items and no colons. `seen = {}` followed by `seen.add(x)` fails with AttributeError, a common first bug in de-duplication code.', NULL, NULL, 208);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 2, 'true_false', '`len(d)` takes the same time for a dict with 10 keys as for one with 10 million keys.', NULL, NULL, 'True', 'Does the dict have to count its keys each time?', 'A dict keeps track of how many entries it holds, so len() is O(1). The same goes for lists, sets and strings. Note the difference with `v in d.values()`, which does have to look at every value.', NULL, NULL, 209);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 2, 'mcq', 'After `data = json.loads(''{"done": true, "err": null}'')`, what are `data[''done'']` and `data[''err'']`?', NULL, NULL, 'True and None', 'json converts JSON values into the matching Python objects.', 'JSON true/false become Python True/False and null becomes None, so `if data[''err''] is None:` works as expected. Going the other way, json.dumps writes True as true and None as null.', NULL, NULL, 210);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1 and 0', 0), (@q, 'B', '''true'' and ''null''', 0), (@q, 'C', 'True and None', 1), (@q, 'D', 'True and ''null''', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 2, 'true_false', 'In PyTorch, `model.state_dict()` is a dict-like mapping from parameter names such as ''fc.weight'' to tensors.', NULL, NULL, 'True', 'Checkpoints are saved and loaded by name.', 'It''s an OrderedDict of names to tensors, which is why checkpoint errors talk about ''missing keys'' and ''unexpected keys''. Because it''s a dict, you can inspect it with .keys(), filter it with a comprehension or rename keys before loading.', NULL, NULL, 211);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ordering'), 2, 'mcq', '`d = {''b'': 2, ''a'': 1}`. After `keys = sorted(d)`, what is true?', NULL, NULL, 'keys is the list [''a'', ''b''], and d still iterates as ''b'', ''a''', 'What type does sorted() always return?', 'sorted() always returns a new list, here of the keys, and never touches the original. To get a dict in key order, rebuild it: dict(sorted(d.items())). Insertion order is what d keeps; sorted ignores it.', NULL, NULL, 212);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'd is now sorted too, because sorted works in place', 0), (@q, 'B', 'keys is [''b'', ''a''], because dicts keep insertion order', 0), (@q, 'C', 'keys is the list [''a'', ''b''], and d still iterates as ''b'', ''a''', 1), (@q, 'D', 'keys is a new dict sorted by key', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'get-setdefault'), 3, 'mcq', 'In `cache`, None is a legitimate stored value. Which single lookup tells ''key missing'' apart from ''key stored as None''?', NULL, NULL, 'v = cache.get(k, _MISSING), then check `v is _MISSING`, where _MISSING = object()', 'You need a default that can never be a real value.', 'A fresh object() is a unique sentinel: no stored value can be that exact object, so `is _MISSING` only fires for a missing key. get(k) returns None both ways, `not v` also fires for 0 and '''', and get(k, None) is the same as get(k). `k in cache` works too, at the cost of a second lookup.', ' cache = {"a": None}\n get("a", _MISSING) -> None        (stored, value None)\n get("b", _MISSING) -> _MISSING    (missing)\n get("a") / get("b") -> None / None (can''t tell)', NULL, 213);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'v = cache.get(k, _MISSING), then check `v is _MISSING`, where _MISSING = object()', 1), (@q, 'B', 'v = cache.get(k, None), then check `v == None`', 0), (@q, 'C', 'v = cache.get(k), then check `v is None`', 0), (@q, 'D', 'v = cache.get(k), then check `not v`', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iteration'), 3, 'true_false', '`list(d.keys())` and `list(d.values())` are guaranteed to line up position by position, as long as `d` isn''t changed in between.', NULL, NULL, 'True', 'All three views walk the same internal entry array.', 'The docs guarantee that keys, values and items iterate in the same order when there are no changes in between, so zip(d.keys(), d.values()) rebuilds the pairs. Still, d.items() says what you mean and can''t drift if someone adds a line between the two calls.', NULL, NULL, 214);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'comprehensions'), 3, 'mcq', '`words = [''<pad>'', ''hello'', ''world'']`. Which builds the token-to-id vocabulary `{''<pad>'': 0, ''hello'': 1, ''world'': 2}`?', NULL, NULL, '{w: i for i, w in enumerate(words)}', 'enumerate yields (index, item). Which side should be the key?', 'The comprehension swaps the pair so the token is the key. dict(enumerate(words)) and {i: w ...} build the reverse map, id-to-token, which you also need for decoding. The set version loses the order of iteration and calls index() each time, an O(n) scan that makes the build O(n^2).', NULL, NULL, 215);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{w: i for i, w in enumerate(words)}', 1), (@q, 'B', '{i: w for i, w in enumerate(words)}', 0), (@q, 'C', 'dict(enumerate(words))', 0), (@q, 'D', '{w: words.index(w) for w in set(words)}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merging'), 3, 'mcq', '`merged = dict(defaults, **overrides)` raises TypeError for some `overrides`. Which ones?', NULL, NULL, 'Ones with non-string keys, e.g. {1: ''a''}: ** unpacking needs keyword names', '`**` turns each key into a keyword argument.', 'Keyword arguments must be strings, so dict({}, **{1: ''a''}) fails with ''keywords must be strings''. Shared keys are fine (overrides win), and so are nested values (they''re shared, not copied). `defaults | overrides` or `{**defaults, **overrides}` accept any hashable keys.', NULL, NULL, 216);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Empty dicts', 0), (@q, 'B', 'Ones that share keys with defaults', 0), (@q, 'C', 'Ones with non-string keys, e.g. {1: ''a''}: ** unpacking needs keyword names', 1), (@q, 'D', 'Ones with nested dict values', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'collections'), 3, 'true_false', '`Counter.most_common()` with no argument returns every item sorted by count, and items with equal counts keep the order they were first seen in.', NULL, NULL, 'True', 'Counter is a dict, and dicts remember insertion order.', 'most_common() sorts by count with a stable sort, so ties stay in first-seen order: Counter(''abcab'').most_common() gives [(''a'', 2), (''b'', 2), (''c'', 1)]. If ties must be broken by name instead, for reproducible reports, sort yourself: sorted(c.items(), key=lambda kv: (-kv[1], kv[0])).', NULL, NULL, 217);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sets'), 3, 'mcq', 'You cache the similarity of two documents, and sim(a, b) is the same as sim(b, a). Which cache key stores each pair once?', NULL, NULL, 'frozenset((a, b)) (or tuple(sorted((a, b))))', 'The key must be hashable and ignore order.', 'A frozenset is hashable and order-free, so (a, b) and (b, a) map to one entry. The plain tuple stores both orders separately (twice the work), a set is unhashable (TypeError), and string concatenation can collide: ''ab'' + ''c'' equals ''a'' + ''bc''. Sorted tuples work when ids are comparable.', NULL, 'Like a friendship table keyed by an unordered pair: Asha-Ravi and Ravi-Asha are the same row.', 218);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{a, b}', 0), (@q, 'B', 'a + b, the two ids joined as one string', 0), (@q, 'C', '(a, b)', 0), (@q, 'D', 'frozenset((a, b)) (or tuple(sorted((a, b))))', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 3, 'true_false', '`min(d, key=d.get)` looks at every key, so it''s O(n) even though each `d.get` call is O(1).', NULL, NULL, 'True', 'How can min() know the smallest without seeing all of them?', 'A dict is unordered by value, so finding the smallest value means checking every one. Doing this inside a loop, e.g. picking the lowest-loss run after every epoch, makes the loop O(n^2); keep a running best, or a heap (heapq) when you need repeated minimums.', NULL, NULL, 219);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 3, 'fill_blank', 'Load a checkpoint even though the new head has different keys: `model.load_state_dict(sd, ____=False)`.', NULL, NULL, 'strict', 'The keyword that controls whether every key must match.', 'With strict=False, PyTorch loads the keys that match and returns lists of missing and unexpected keys instead of raising. Always look at those lists: a typo such as a ''module.'' prefix can make strict=False load nothing at all, silently.', NULL, NULL, 220);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 3, 'mcq', '`json.dumps({(0, 1): 0.93})` fails, though the dict itself is fine in Python. Why?', NULL, NULL, 'JSON object keys must be strings; json accepts str, int, float, bool or None keys but not tuples', 'What can a key in JSON text be?', 'JSON keys are always strings. json converts int, float, bool and None keys to strings for you, but a tuple raises TypeError (''keys must be str, int, float, bool or None''). Encode composite keys yourself, e.g. ''0,1'', or store a list of records like {''pair'': [0, 1], ''score'': 0.93}.', NULL, NULL, 221);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'JSON object keys must be strings; json accepts str, int, float, bool or None keys but not tuples', 1), (@q, 'B', 'Tuples aren''t hashable', 0), (@q, 'C', 'json can''t serialise floats', 0), (@q, 'D', 'The dict must be sorted first', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 3, 'mcq', 'A feature dict per example is turned into a model input vector. Why use `[feats.get(name, 0.0) for name in FEATURE_ORDER]` instead of `list(feats.values())`?', NULL, NULL, 'The vector position must mean the same feature for every example, and insertion order depends on how each dict was built', 'Column 3 should always be the same feature.', 'Dict order follows insertion, so two sources that build the same features in a different order, or skip a missing one, shift every column. A fixed FEATURE_ORDER list saved with the model, plus a default for missing features, keeps training and serving aligned.', NULL, NULL, 222);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'values() skips features that are 0', 0), (@q, 'B', 'The vector position must mean the same feature for every example, and insertion order depends on how each dict was built', 1), (@q, 'C', 'values() is slower than a list comprehension', 0), (@q, 'D', 'list(feats.values()) returns the keys', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 3, 'mcq', 'Why doesn''t looking up the same long string key over and over re-hash all its characters each time?', NULL, NULL, 'str objects cache their hash after the first hash() call', 'Strings are immutable, so their hash can never change.', 'CPython computes a str''s hash once and stores it in the string object. Later lookups reuse it and only pay for comparing with the stored key, which starts with a pointer check. Hashing still covers every character the first time, so it''s O(len) once per string object.', NULL, NULL, 223);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The dict remembers the last key looked up', 0), (@q, 'B', 'Python hashes only the first 8 characters of a string', 0), (@q, 'C', 'str objects cache their hash after the first hash() call', 1), (@q, 'D', 'dicts store keys sorted, so no hashing is needed', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 4, 'mcq', 'A data pipeline assigns users to train/test with `hash(user_id) % 10 < 8`. Each run puts different users in the test set. Why, and what''s the fix?', NULL, NULL, 'str hashes are randomised per process; use a stable hash such as hashlib.md5(user_id.encode()) and take that modulo 10', 'Run `python -c "print(hash(''a''))"` twice.', 'Since Python 3.3, str and bytes hashes are salted with a random per-process seed (unless PYTHONHASHSEED is set), so the split reshuffles on every run and test users leak into training over time. Small ints hash to themselves, so it isn''t ''every type''. A hashlib digest is stable across processes, machines and versions.', ' run 1: hash(''user_42'') % 10 -> 9  (test)\n run 2: hash(''user_42'') % 10 -> 2  (train)   <- leak\n md5(''user_42'') % 10        -> same every run', NULL, 224);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'str hashes are randomised per process; use a stable hash such as hashlib.md5(user_id.encode()) and take that modulo 10', 1), (@q, 'B', 'hash() is non-deterministic for every type; sort the users first', 0), (@q, 'C', 'The modulo of a negative hash is negative; use abs()', 0), (@q, 'D', 'Dict ordering changes between runs; use OrderedDict', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'mcq', 'Why does CPython randomise str hashes for each process?', NULL, NULL, 'To stop hash-flooding attacks, where crafted keys all collide and make dict inserts O(n) each', 'Think of a web server parsing JSON or form fields from an attacker.', 'With a fixed, known hash, an attacker can post thousands of keys that land in the same probe chain, turning parsing into O(n^2) work and pinning the CPU. A secret per-process seed (SipHash) makes collisions impossible to predict. The changing set order is a side effect, not the goal.', NULL, 'Like rate-limiting a login endpoint: the feature isn''t for normal users, it''s there so one malicious client can''t take the server down.', 225);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'To spread keys more evenly than a fixed hash function could', 0), (@q, 'B', 'To stop hash-flooding attacks, where crafted keys all collide and make dict inserts O(n) each', 1), (@q, 'C', 'To make sets print in a different order for testing', 0), (@q, 'D', 'To stop programs from depending on hash() at all', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'collections'), 4, 'true_false', 'Since Python 3.10, `Counter(a=1, b=0) == Counter(a=1)` is True, because missing items count as zero.', NULL, NULL, 'True', 'Counter equality changed in 3.10 to match multiset maths.', 'In 3.10+, Counter equality treats a missing element as having count 0, so an explicit b=0 doesn''t make the counters differ (before 3.10 it did, like a plain dict). The b=0 entry is still stored and shows up in len() and iteration; use +c to drop zero and negative counts.', NULL, NULL, 226);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'collections'), 4, 'mcq', 'For `d = defaultdict(list)`, `d.get(''x'')` returns None but `d[''x'']` returns []. Why?', 'from collections import defaultdict\n\nd = defaultdict(list)\nprint(d.get("x"), dict(d))\nprint(d["x"], dict(d))', 'python', 'Only d[k] calls __missing__, which runs the default factory; get() never does', 'Which method does dict call when [] doesn''t find a key?', 'dict.__getitem__ calls __missing__ on a miss, and defaultdict''s __missing__ builds the default and inserts it. get(), `in` and pattern matching never call it, so they have no side effects. That''s handy for read-only checks, and a trap if you expect get() to create the list.', NULL, NULL, 227);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Only d[k] calls __missing__, which runs the default factory; get() never does', 1), (@q, 'B', 'defaultdict overrides get() to return None on purpose', 0), (@q, 'C', 'd[''x''] returns a shared empty list stored at creation', 0), (@q, 'D', 'get() checks a separate cache that''s empty', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merging'), 4, 'mcq', '`cfg = ChainMap(cli, defaults)`. What happens on `cfg[''lr''] = 0.5`, and on `del cfg[''bs'']` when ''bs'' exists only in defaults?', NULL, NULL, 'The write goes into cli only; the del raises KeyError, because writes and deletes only touch the first mapping', 'Reads search every layer. Do writes?', 'ChainMap looks keys up through each mapping in order, but writes, updates and deletes only apply to maps[0]. So the defaults stay untouched (good for layered config), and deleting a key that lives only in a lower layer raises KeyError. To change a default, write to cfg.maps[-1] explicitly.', ' read cfg[''bs'']:  cli? no -> defaults? yes -> 32\n cfg[''lr''] = 0.5: write -> cli only\n del cfg[''bs'']:   cli only -> not there -> KeyError', 'Like a copy-on-write overlay filesystem in Docker: reads fall through to the lower layers, writes land only in the top layer.', 228);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The write updates every mapping; the del removes ''bs'' from defaults', 0), (@q, 'B', 'The write goes into cli only; the del raises KeyError, because writes and deletes only touch the first mapping', 1), (@q, 'C', 'Both raise TypeError: ChainMap is read-only', 0), (@q, 'D', 'Both change defaults, the mapping that already held the keys', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 4, 'fill_blank', 'Read every JSON float as an exact Decimal to avoid binary rounding: `json.loads(s, ____=Decimal)`.', NULL, NULL, 'parse_float', 'The hook is named after the kind of number it handles.', 'json.loads calls parse_float with the original digit text, so ''0.1'' becomes Decimal(''0.1'') instead of the nearest binary float. Useful for money and IDs in API payloads; parse_int is the matching hook for integers.', NULL, NULL, 229);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 4, 'mcq', 'A sweep builds `configs = [dict(base) for _ in range(3)]` from `base = {''lr'': 0.1, ''optim'': {''name'': ''adam''}}`, then sets `configs[0][''optim''][''name''] = ''sgd''`. What happens?', NULL, NULL, 'base and all three configs now say ''sgd'': dict() copies only the top level, so they share one inner optim dict', 'How deep does dict(base) copy?', 'dict(base), base.copy() and {**base} are shallow: new outer dicts holding references to the same inner objects. The fix is copy.deepcopy(base) for each config. In sweeps this bug quietly runs every trial with the last config''s settings, so the results table lies.', ' base       -> {''lr'': 0.1, ''optim'': --+\n configs[0] -> {''lr'': 0.1, ''optim'': --+--> {''name'': ''sgd''}\n configs[1] -> {''lr'': 0.1, ''optim'': --+     (one shared dict)', 'Like spreading a JS object `{...base}`: the outer object is new, but nested objects are still the same references.', 230);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'base and all three configs now say ''sgd'': dict() copies only the top level, so they share one inner optim dict', 1), (@q, 'B', 'TypeError: nested dicts can''t be copied with dict()', 0), (@q, 'C', 'Only configs[0] changes, because dict(base) makes a full copy', 0), (@q, 'D', 'base changes but the other configs don''t', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'fill_blank', '`sys.____(s)` returns a single shared copy of the string s, so repeated dict keys can be matched by identity before comparing characters.', NULL, NULL, 'intern', 'The word for keeping one canonical copy of a string.', 'Interned strings are stored once; a lookup with an interned key finds the stored key by pointer comparison straight away. CPython already interns identifiers and attribute names. Interning millions of repeated tokens or column names can also save memory.', NULL, NULL, 231);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'comprehensions'), 4, 'true_false', 'Python 3.12 inlined comprehensions (PEP 709), so a dict comprehension''s loop variable now leaks into the surrounding function.', NULL, NULL, 'False', 'The change was about speed, not scope.', 'PEP 709 removed the hidden function call behind list, dict and set comprehensions, but it keeps their isolation: after `{k: 1 for k in ''ab''}`, k is still undefined outside. Only Python 2 list comprehensions leaked. What did change: tracebacks no longer show a separate comprehension frame, and locals() inside one also lists the enclosing function''s names.', NULL, NULL, 232);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
