INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'logic-ops'), 2, 'code_output', 'What does this print?', 'print(0 or "default", "set" or "default")', 'python', 'default set', '`or` hands back one of its operands.', '`or` returns the first truthy operand (or the last one). 0 is falsy so you get ''default''; ''set'' is truthy so you get ''set''.', ' 0 or "default":     0 falsy -> go on -> "default"\n "set" or "default": "set" truthy -> stop -> "set"', NULL, 27);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'default set', 1), (@q, 'B', 'True True', 0), (@q, 'C', 'False set', 0), (@q, 'D', 'default default', 0);
