INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ternary'), 2, 'code_output', 'What does this print?', 'n = 1\nprint(f"{n} item{"s" if n != 1 else ""}")', 'python', '1 item', 'When n is 1, which string is chosen?', 'n != 1 is False, so the empty string is added: ''1 item''. Python 3.12+ allows the same quote type inside an f-string.', NULL, NULL, 31);
