INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'type-checks'), 1, 'code_output', 'What does this print?', 'print(isinstance(5, int), isinstance("5", int))', 'python', 'True False', 'Quotes make a string, whatever is inside them.', 'isinstance(value, type) asks ''is this value of that type?''. 5 is an int; ''5'' is a str that happens to contain a digit.', NULL, NULL, 81);
