INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'comparisons'), 1, 'fill_blank', 'The comparison operator that means ''not equal to'' is ____.', NULL, NULL, '!=', 'An exclamation mark is involved.', '!= gives True when the two sides differ: 3 != 4 is True. Python has no !== or <> (that one was removed in Python 3).', NULL, NULL, 82);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'type-checks'), 2, 'code_output', 'What does this print?', 'print(isinstance(3.0, (int, float)), type(3.0) == int)', 'python', 'True False', 'isinstance accepts a tuple of types.', 'isinstance(x, (int, float)) is True if x is either type: a handy ''is it a number?'' check. 3.0 is a float, so type(3.0) == int is False.', NULL, NULL, 83);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True True', 0), (@q, 'B', 'TypeError', 0), (@q, 'C', 'False False', 0), (@q, 'D', 'True False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'type-checks'), 2, 'code_output', 'What does this print?', 'value = "42"\nif value.isdigit():\n    value = int(value)\nprint(value + 1)', 'python', '43', 'The string is converted before the maths.', 'isdigit() is True for ''42'', so value becomes the int 42 and 42 + 1 is 43. Without the conversion, ''42'' + 1 would raise TypeError.', NULL, NULL, 84);
