INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False False', 0), (@q, 'B', 'True False', 1), (@q, 'C', 'True True', 0), (@q, 'D', 'False True', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'comparisons'), 2, 'code_output', 'What does this print?', 'print("10" < "9", 10 < 9)', 'python', 'True False', 'Strings compare character by character, not by numeric value.', '''1'' comes before ''9'', so ''10'' < ''9'' is True. That''s why files named epoch_10, epoch_9 sort in the wrong order; compare numbers as ints, or zero-pad the names.', NULL, 'Like a phone book: ''Ab...'' comes before ''B'' no matter how long the name is.', 86);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False False', 0), (@q, 'B', 'True True', 0), (@q, 'C', 'TypeError', 0), (@q, 'D', 'True False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'comparisons'), 2, 'mcq', 'Which checks that `x` is between 0 and 1 inclusive, in idiomatic Python?', NULL, NULL, '0 <= x <= 1', 'Python lets you chain comparisons like maths.', '0 <= x <= 1 means 0 <= x and x <= 1. range(0, 1) only contains the int 0, and `or` would accept every number.', NULL, NULL, 87);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'x in range(0, 1)', 0), (@q, 'B', 'x >= 0 or x <= 1', 0), (@q, 'C', '0 <= x and <= 1', 0), (@q, 'D', '0 <= x <= 1', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ternary'), 2, 'code_output', 'What does this print?', 'x = -4\nprint(x if x >= 0 else -x)', 'python', '4', 'Which branch runs for a negative x?', 'x >= 0 is False, so the expression gives -x, which is 4. That''s absolute value written as a conditional expression (abs(x) does the same).', NULL, NULL, 88);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '-4', 0), (@q, 'B', '4', 1), (@q, 'C', 'True', 0), (@q, 'D', 'SyntaxError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'match-case'), 2, 'code_output', 'What does this print?', 'def run(cmd):\n    match cmd:\n        case "start":\n            return "go"\n        case "stop":\n            return "halt"\n\nprint(run("stop"), run("pause"))', 'python', 'halt None', 'What happens when no case matches?', 'If no case matches, match does nothing (no error), so the function falls off the end and returns None. Add `case _:` when you need a default.', NULL, NULL, 89);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'go None', 0), (@q, 'B', 'halt halt', 0), (@q, 'C', 'halt MatchError', 0), (@q, 'D', 'halt None', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'match-case'), 2, 'true_false', 'In match/case, if two cases both match, both of their blocks run, top to bottom.', NULL, NULL, 'False', 'Think switch without fall-through.', 'Only the first matching case runs; there is no fall-through and no break. Put the most specific cases first.', NULL, NULL, 90);
