INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'any-all'), 2, 'code_output', 'What does this print?', 'scores = [55, 72, 40]\nprint(any(s < 50 for s in scores), sum(s >= 50 for s in scores))', 'python', 'True 2', 'Booleans add up as 1s and 0s.', '40 < 50, so any() is True. Summing the boolean generator counts the True values: 55 and 72 pass, giving 2.', NULL, NULL, 91);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True 1', 0), (@q, 'B', 'True [55, 72]', 0), (@q, 'C', 'False 2', 0), (@q, 'D', 'True 2', 1);
