INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'logic-ops'), 3, 'mcq', 'Python has no `??` operator. Which expression uses `timeout` unless it is None, keeping a real value of 0?', NULL, NULL, '30 if timeout is None else timeout', 'Only None should trigger the fallback.', '`or` and `if timeout` both treat 0 as missing. The explicit `is None` test is Python''s version of JS/C# `timeout ?? 30`.', NULL, NULL, 106);
