INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'enumerate-zip'), 1, 'code_output', 'What does this print?', 'names = ["Ana", "Bo"]\nages = [30, 25]\nfor n, a in zip(names, ages):\n    print(n, a)', 'python', 'Ana 30\nBo 25', 'zip pairs items at the same position.', 'zip walks both lists side by side: ("Ana", 30), then ("Bo", 25).', NULL, 'A zipper: tooth 1 from the left meets tooth 1 from the right.', 19);
