INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope-perf'), 1, 'code_output', 'What does this print?', 'for i in range(3):\n    pass\nprint(i)', 'python', '2', 'Python doesn''t delete the loop variable when the loop ends.', 'The loop variable keeps its last value, 2. Unlike `let` in a JS for loop, it is not block-scoped.', NULL, NULL, 21);
