INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'while'), 2, 'code_output', 'What does this print?', 'queue = [3, 1, 2]\nwhile queue:\n    print(queue.pop())', 'python', '2\n1\n3', 'An empty list is falsy; pop() takes from the end.', 'pop() removes the LAST item each time: 2, 1, 3. When the list is empty, `while queue` is False.', NULL, NULL, 30);
