INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'break-continue'), 2, 'code_output', 'What does this print?', 'total = 0\nfor n in range(1, 8):\n    if n % 2 == 0:\n        continue\n    if n > 5:\n        break\n    total += n\nprint(total)', 'python', '9', 'Even numbers are skipped; the loop ends at the first odd number above 5.', 'Odd values reached: 1, 3, 5 are added (total 9). At 7, n > 5 triggers break before adding.', NULL, NULL, 31);
