INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iterators'), 2, 'code_output', 'What does this print?', 'squares = map(lambda x: x * x, [1, 2, 3])\nprint(sum(squares))\nprint(sum(squares))', 'python', '14\n0', 'map gives back an iterator, not a list.', 'The first sum uses up the iterator. The second sees nothing and returns 0. Wrap in list() if you need it twice.', NULL, NULL, 39);
