INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generators'), 2, 'code_output', 'What does this print?', 'def countdown(n):\n    while n > 0:\n        yield n\n        n -= 1\n\nprint(list(countdown(3)))', 'python', '[3, 2, 1]', 'yield hands out one value and pauses.', 'countdown is a generator function. list() keeps asking for values: 3, 2, 1, then the function ends.', NULL, NULL, 40);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[3, 2, 1, 0]', 0), (@q, 'B', 'None', 0), (@q, 'C', '3', 0), (@q, 'D', '[3, 2, 1]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generators'), 2, 'mcq', 'What does calling a function that contains `yield` return?', NULL, NULL, 'A generator object; the body hasn''t run yet', 'Nothing inside runs until you ask for a value.', 'Calling a generator function only creates a generator. Code runs when next() (or a for loop) asks for a value.', NULL, NULL, 41);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The first yielded value', 0), (@q, 'B', 'A list of all yielded values', 0), (@q, 'C', 'None', 0), (@q, 'D', 'A generator object; the body hasn''t run yet', 1);
