INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'itertools'), 2, 'code_output', 'What does this print?', 'from itertools import count, islice\nprint(list(islice(count(10, 5), 3)))', 'python', '[10, 15, 20]', 'count is infinite; islice takes just the first few.', 'count(10, 5) yields 10, 15, 20, ... forever. islice(..., 3) stops after three items.', NULL, NULL, 43);
