INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope-perf'), 2, 'code_output', 'What does this print?', 'for x in []:\n    pass\nprint(x)', 'python', 'NameError', 'Did the loop ever assign x?', 'An empty loop never binds x, so x doesn''t exist (assuming no earlier x). The variable only leaks when the loop ran at least once.', NULL, NULL, 44);
