INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'range'), 3, 'code_output', 'What does this print?', 'r = range(0, 10, 2)\nprint(r[-1], 7 in r, list(r) == list(r))', 'python', '8 False True', 'range is a sequence: indexable and re-iterable.', 'The last element is 8; 7 isn''t on the even grid; range can be looped any number of times (unlike an iterator).', NULL, NULL, 46);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '8 False True', 1), (@q, 'B', '8 True False', 0), (@q, 'C', '10 False True', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'range'), 3, 'true_false', '`10**12 in range(10**15)` takes about as long as `5 in range(10)`.', NULL, NULL, 'True', 'Does range need to walk its values to answer `in` for an int?', 'range checks integer membership with arithmetic (start, stop, step), so it''s O(1) and builds no list.', NULL, NULL, 47);
