INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'mutating'), 3, 'code_output', 'What does this print?', 'nums = [1, 2, 2, 3]\nfor n in nums[:]:\n    if n == 2:\n        nums.remove(n)\nprint(nums)', 'python', '[1, 3]', 'nums[:] is a copy.', 'Looping over a copy means removals don''t disturb the iteration. Even simpler: nums = [n for n in nums if n != 2].', NULL, NULL, 57);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 3]', 1), (@q, 'B', 'RuntimeError', 0), (@q, 'C', '[1, 2, 3]', 0), (@q, 'D', '[1, 2, 2, 3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'mutating'), 3, 'code_output', 'What does this print?', 'd = {"a": 1, "b": 2}\nfor k in d:\n    d[k + "!"] = 0\nprint(d)', 'python', 'RuntimeError', 'Dicts are stricter than lists about this.', 'Adding keys while iterating raises ''dictionary changed size during iteration''. Loop over list(d) instead.', NULL, NULL, 58);
