INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iterators'), 3, 'code_output', 'What does this print?', 'g = (n for n in range(10))\nprint(5 in g)\nprint(list(g))', 'python', 'True\n[6, 7, 8, 9]', '`in` on an iterator has to pull items to look at them.', 'Checking 5 in g consumes 0..5. Only 6..9 are left.', NULL, NULL, 60);
