INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 1, 'code_output', 'What does this print?', 'x = 10\n\ndef show():\n    x = 99\n\nshow()\nprint(x)', 'python', '10', 'The x inside the function is a new, local name.', 'Assigning inside a function creates a local variable. The global x is untouched.', ' global:  x = 10\n show():  x = 99   (local, gone when show returns)', NULL, 15);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'UnboundLocalError', 0), (@q, 'B', '99', 0), (@q, 'C', '10', 1), (@q, 'D', 'None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 1, 'code_output', 'What does this print?', 'rate = 3\n\ndef cost(n):\n    return n * rate\n\nprint(cost(2))', 'python', '6', 'Can a function read a variable defined outside it?', 'Reading a global is fine: rate isn''t found locally, so Python looks in the module (global) scope.', NULL, NULL, 16);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '2', 0), (@q, 'B', 'None', 0), (@q, 'C', '6', 1), (@q, 'D', 'NameError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'first-class'), 1, 'code_output', 'What does this print?', 'def shout(s):\n    return s.upper()\n\nyell = shout\nprint(yell("hi"))', 'python', 'HI', 'No parentheses after shout means you''re not calling it.', 'Functions are values. yell = shout makes another name for the same function.', NULL, 'Like `const yell = shout;` in JavaScript.', 17);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'shout', 0), (@q, 'B', 'HI', 1), (@q, 'C', 'TypeError', 0), (@q, 'D', 'hi', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'first-class'), 1, 'code_output', 'What does this print?', 'nums = [3, 1, 2]\nprint(sorted(nums, key=lambda n: -n))', 'python', '[3, 2, 1]', 'key= says what to sort BY; the items themselves are unchanged.', 'Sorting by -n puts the largest n first. The returned items are the originals, not the keys.', NULL, NULL, 18);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[-3, -2, -1]', 0), (@q, 'B', '[-1, -2, -3]', 0), (@q, 'C', '[3, 2, 1]', 1), (@q, 'D', '[1, 2, 3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hints-docs'), 1, 'mcq', 'What is a docstring?', NULL, NULL, 'A string literal on the first line of a function body that describes what it does', 'It''s what help(func) shows.', 'A triple-quoted string right after the def line becomes func.__doc__ and appears in help() and IDE tooltips.', NULL, 'Like a JSDoc / Javadoc comment, but stored on the function.', 19);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A comment that starts with #', 0), (@q, 'B', 'A string that Python runs as code', 0), (@q, 'C', 'A string literal on the first line of a function body that describes what it does', 1), (@q, 'D', 'A required type declaration', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'recursion'), 1, 'code_output', 'What does this print?', 'def fact(n):\n    if n == 1:\n        return 1\n    return n * fact(n - 1)\n\nprint(fact(4))', 'python', '24', 'fact(4) = 4 * fact(3) = ...', '4 * 3 * 2 * 1 = 24. `if n == 1` is the base case that stops the recursion.', NULL, NULL, 20);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '10', 0), (@q, 'B', '24', 1), (@q, 'C', '4', 0), (@q, 'D', 'RecursionError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'recursion'), 1, 'mcq', 'In a recursive function, what is the ''base case''?', NULL, NULL, 'The condition where the function returns without calling itself again', 'Without it, when would the calls stop?', 'The base case ends the chain of self-calls. Without one you get infinite recursion and a RecursionError.', NULL, NULL, 21);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The default argument', 0), (@q, 'B', 'The condition where the function returns without calling itself again', 1), (@q, 'C', 'The largest input it can handle', 0), (@q, 'D', 'The first line of the function', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'def-return'), 1, 'true_false', '`print(x)` inside a function and `return x` do the same thing.', NULL, NULL, 'False', 'Can the caller store what was printed?', 'print shows text on screen and the function still returns None. return hands the value back so the caller can use it.', NULL, NULL, 22);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'def-return'), 2, 'code_output', 'What does this print?', 'def stats(nums):\n    return min(nums), max(nums)\n\nresult = stats([4, 1, 9])\nprint(result, type(result).__name__)', 'python', '(1, 9) tuple', 'The comma makes the return value a single object.', '`return a, b` returns one tuple. You can unpack it: lo, hi = stats(...).', NULL, NULL, 23);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 9] list', 0), (@q, 'B', '1 9 tuple', 0), (@q, 'C', '(1, 9) tuple', 1), (@q, 'D', '(1, 9) list', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'def-return'), 2, 'code_output', 'What does this print?', 'def f():\n    return\n\nprint(f())', 'python', 'None', 'A bare return still returns something.', '`return` with no value returns None, the same as falling off the end of the function.', NULL, NULL, 24);
