INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'args-kwargs'), 2, 'code_output', 'What does this print?', 'def info(**details):\n    for k, v in details.items():\n        print(k, v)\n\ninfo(name="Ana", age=30)', 'python', 'name Ana\nage 30', '**details collects keyword arguments.', '**details packs keyword arguments into a dict {''name'': ''Ana'', ''age'': 30}.', NULL, NULL, 27);
