INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'param-kinds'), 2, 'code_output', 'What does this print?', 'def connect(host, *, port=80):\n    return f"{host}:{port}"\n\nprint(connect("db", 5432))', 'python', 'TypeError', 'What does a bare * in the parameter list mean?', 'Everything after * is keyword-only. You must write connect("db", port=5432).', NULL, NULL, 30);
