INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'first-class'), 3, 'code_output', 'What does this print?', 'print(list(filter(None, [0, 1, "", "x", None, [], [3]])))', 'python', '[1, ''x'', [3]]', 'filter(None, ...) uses each item''s own truthiness.', 'With None as the function, filter keeps truthy items. 0, '''', None and [] are falsy.', NULL, NULL, 54);
