INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 1, 'code_output', 'What does this print?', 'def f():\n    y = 1\n\nf()\nprint(y)', 'python', 'NameError', 'Where does y live?', 'y is local to f and disappears when f returns. The code outside has no name y, so it raises NameError. Return the value if the caller needs it.', NULL, 'Like a variable declared inside a JS function: gone once the function returns.', 80);
