INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'recursion'), 1, 'code_output', 'What does this print?', 'def total(n):\n    if n == 0:\n        return 0\n    return n + total(n - 1)\n\nprint(total(3))', 'python', '6', 'total(3) = 3 + total(2) = ...', '3 + 2 + 1 + 0 = 6. Each call waits for the smaller one to finish, and n == 0 stops the chain.', ' total(3) = 3 + total(2)\n               2 + total(1)\n                   1 + total(0)\n                       0          <- base case', NULL, 81);
