INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'first-class'), 1, 'code_output', 'What does this print?', 'nums = [1, 2, 3]\nprint(list(map(lambda n: n * 10, nums)))', 'python', '[10, 20, 30]', 'map applies the function to every item.', 'map calls the lambda on 1, 2 and 3, and list() collects the results. A list comprehension [n * 10 for n in nums] does the same thing.', NULL, NULL, 82);
