INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'args-kwargs'), 2, 'code_output', 'What does this print?', 'config = {"lr": 0.1, "epochs": 3}\n\ndef train(lr, epochs):\n    return f"{epochs} epochs at {lr}"\n\nprint(train(**config))', 'python', '3 epochs at 0.1', '** spreads a dict into keyword arguments.', 'train(**config) is train(lr=0.1, epochs=3). It''s how hyperparameter dicts loaded from YAML/JSON are passed to model or trainer constructors.', NULL, NULL, 92);
