INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'closures'), 2, 'fill_blank', 'What does this print? Type the exact output.', 'def make_counter():\n    n = 0\n    def inc():\n        nonlocal n\n        n += 1\n        return n\n    return inc\n\nc = make_counter()\nc()\nc()\nprint(c())', 'python', '3', 'nonlocal lets inc update n in the enclosing function.', 'Each call bumps the same captured n: 1, 2, 3. The closure keeps private state between calls, like a tiny object with one field.', NULL, 'Like a private field in a class with a single increment method.', 99);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'first-class'), 2, 'code_output', 'What does this print?', 'words = ["b", "a", "C"]\nprint(sorted(words), sorted(words, key=str.lower))', 'python', '[''C'', ''a'', ''b''] [''a'', ''b'', ''C'']', 'Upper-case letters come before lower-case ones in plain string order.', 'Default string order compares character codes, and ''C'' (67) is before ''a'' (97). key=str.lower sorts case-insensitively but returns the original strings.', NULL, NULL, 100);
