INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'list-comp'), 1, 'mcq', 'What does a list comprehension like `[f(x) for x in data]` give you?', NULL, NULL, 'A brand-new list with f applied to each item', 'Is the original touched?', 'A comprehension always builds a new list. `data` is left as it was.', NULL, 'data.map(f) in JavaScript also returns a new array.', 7);
