INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filters'), 1, 'code_output', 'What does this print?', 'print([w for w in ["cat", "dog", "cow"] if w.startswith("c")])', 'python', '[''cat'', ''cow'']', 'The if at the end decides what''s kept.', 'Only words starting with ''c'' pass the filter. The kept items are the words themselves, not True/False.', NULL, NULL, 11);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''cat'', ''dog'', ''cow'']', 0), (@q, 'B', '[''cat'', ''cow'']', 1), (@q, 'C', '[''dog'']', 0), (@q, 'D', '[True, False, True]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filters'), 1, 'true_false', 'A comprehension with an `if` at the end can return a shorter list than its input.', NULL, NULL, 'True', 'What happens to items where the condition is False?', 'The trailing if is a filter: items that fail it are dropped.', NULL, NULL, 12);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filters'), 1, 'mcq', 'In `[x * 2 for x in nums if x > 0]`, which part decides whether an item is kept?', NULL, NULL, 'if x > 0', 'One part transforms, one part loops, one part filters.', 'x * 2 transforms, `for x in nums` loops, `if x > 0` filters.', ' [ x * 2    for x in nums    if x > 0 ]\n   ^make    ^loop            ^keep?', NULL, 13);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'for x in nums', 0), (@q, 'B', 'The square brackets', 0), (@q, 'C', 'if x > 0', 1), (@q, 'D', 'x * 2', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dict-set'), 1, 'code_output', 'What does this print?', 'print({x: x * x for x in range(3)})', 'python', '{0: 0, 1: 1, 2: 4}', 'key: value inside curly braces.', 'A dict comprehension: each x becomes a key mapped to its square.', NULL, NULL, 14);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0, 1, 4]', 0), (@q, 'B', '{0, 1, 4}', 0), (@q, 'C', '{0: 0, 1: 1, 2: 4}', 1), (@q, 'D', '{1: 1, 2: 4, 3: 9}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dict-set'), 1, 'code_output', 'What does this print?', 'print(sorted({n % 3 for n in range(10)}))', 'python', '[0, 1, 2]', 'Curly braces without a colon make a set. Sets drop duplicates.', 'n % 3 only gives 0, 1 or 2; the set keeps one of each. sorted() turns it into a list.', NULL, NULL, 15);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2, 3]', 0), (@q, 'B', '[0, 1, 2, 0, 1, 2, 0, 1, 2, 0]', 0), (@q, 'C', '[0, 1, 2]', 1), (@q, 'D', '[3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dict-set'), 1, 'mcq', 'Which one is a SET comprehension?', NULL, NULL, '{w.lower() for w in words}', 'Look for curly braces and no colon.', '{...} without key: value is a set. With a colon it''s a dict; [] is a list; () is a generator.', NULL, NULL, 16);
