INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genexp'), 1, 'mcq', 'What does `(x * 2 for x in nums)` create?', NULL, NULL, 'A generator that produces values one at a time when asked', 'There''s no ''tuple comprehension'' in Python.', 'Round brackets make a generator expression: lazy, nothing is computed until you loop over it.', NULL, NULL, 17);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A generator that produces values one at a time when asked', 1), (@q, 'B', 'A list', 0), (@q, 'C', 'A tuple', 0), (@q, 'D', 'A syntax error', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genexp'), 1, 'code_output', 'What does this print?', 'print(sum(x for x in [1, 2, 3]))', 'python', '6', 'sum can consume a generator directly.', 'The generator produces 1, 2, 3 and sum adds them. No list is built.', NULL, NULL, 18);
