INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'list-comp'), 1, 'code_output', 'What does this print?', 'print([k for k in {"a": 1, "b": 2}])', 'python', '[''a'', ''b'']', 'Looping over a dict gives keys.', 'Same rule as a for loop: iterating a dict yields its keys. Use .items() for pairs.', NULL, NULL, 19);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''a'', ''b'']', 1), (@q, 'B', '[''a'', 1, ''b'', 2]', 0), (@q, 'C', '[(''a'', 1), (''b'', 2)]', 0), (@q, 'D', '[1, 2]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'list-comp'), 1, 'true_false', '`[s * 3 for s in words]` and a for-loop that appends `s * 3` to an empty list produce the same result.', 'words = ["a", "b"]\nres = []\nfor s in words:\n    res.append(s * 3)\nassert res == [s * 3 for s in words]', 'python', 'True', 'A comprehension is shorthand for which pattern?', 'A list comprehension is the ''empty list + loop + append'' pattern written in one expression.', NULL, NULL, 20);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conditional-expr'), 2, 'code_output', 'What does this print?', 'print(["even" if n % 2 == 0 else "odd" for n in range(3)])', 'python', '[''even'', ''odd'', ''even'']', 'if-else in front transforms every item; it doesn''t drop any.', 'Each n becomes ''even'' or ''odd'', so the result has the same length as the input.', NULL, NULL, 21);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''even'', ''even'']', 0), (@q, 'B', '[''even'', ''odd'', ''even'']', 1), (@q, 'C', 'SyntaxError', 0), (@q, 'D', '[''odd'', ''even'', ''odd'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conditional-expr'), 2, 'mcq', 'You want to replace negative numbers with 0 and keep everything else. Which works?', NULL, NULL, '[x if x > 0 else 0 for x in xs]', 'You want to keep every item, so it''s a transform, not a filter.', 'The if-else (a conditional expression) goes before `for`. The trailing-if version drops items; the else-at-the-end version is a SyntaxError.', NULL, NULL, 22);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[x for x in xs if x > 0]', 0), (@q, 'B', '[x if x > 0 else 0 for x in xs]', 1), (@q, 'C', '[x for x in xs if x > 0 else 0]', 0), (@q, 'D', '[if x > 0: x else 0 for x in xs]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conditional-expr'), 2, 'code_output', 'What does this print?', 'xs = [3, -1, 4]\nprint([x for x in xs if x > 0], [x if x > 0 else 0 for x in xs])', 'python', '[3, 4] [3, 0, 4]', 'One filters, one transforms.', 'Trailing if drops -1 (length 2). The if-else in front keeps every item and maps -1 to 0 (length 3).', NULL, NULL, 23);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[3, 0, 4] [3, 0, 4]', 0), (@q, 'B', '[3, 0, 4] [3, 4]', 0), (@q, 'C', '[3, 4] [3, 4]', 0), (@q, 'D', '[3, 4] [3, 0, 4]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filters'), 2, 'code_output', 'What does this print?', 'print([x for x in range(20) if x % 2 == 0 if x % 3 == 0])', 'python', '[0, 6, 12, 18]', 'Two ifs in a row both have to pass.', 'Chained ifs act like `and`: divisible by both 2 and 3, i.e. multiples of 6 (0 included).', NULL, NULL, 24);
