INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filters'), 2, 'code_output', 'What does this print?', 'print([x for x in range(10) if 2 < x < 6])', 'python', '[3, 4, 5]', 'Python allows chained comparisons.', '2 < x < 6 means 2 < x and x < 6, so 3, 4, 5.', NULL, NULL, 25);
