INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dict-set'), 2, 'code_output', 'What does this print?', 'd = {"a": 1, "b": 2}\nprint({v: k for k, v in d.items()})', 'python', '{1: ''a'', 2: ''b''}', 'Swap the roles of key and value.', 'This inverts the dict. Handy for label maps: id -> name from name -> id.', NULL, NULL, 26);
