INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dict-set'), 2, 'code_output', 'What does this print?', 'print(type({}).__name__, type({1}).__name__)', 'python', 'dict set', 'Empty curly braces have only one meaning.', '{} is an empty dict. An empty set must be written set(). {1} is a set because it has items and no colon.', NULL, NULL, 28);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'dict dict', 0), (@q, 'B', 'dict set', 1), (@q, 'C', 'set dict', 0), (@q, 'D', 'set set', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dict-set'), 2, 'code_output', 'What does this print?', 'print({k: v for k, v in zip("ab", [1, 2])})', 'python', '{''a'': 1, ''b'': 2}', 'zip makes (key, value) pairs.', 'zip pairs ''a'' with 1 and ''b'' with 2; the comprehension turns pairs into dict entries. dict(zip(...)) does the same.', NULL, NULL, 29);
