INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genexp'), 2, 'code_output', 'What does this print?', 'g = (x * 2 for x in [1, 2])\nprint(list(g), list(g))', 'python', '[2, 4] []', 'A generator can be walked through only once.', 'The first list() exhausts the generator. A second pass gets nothing. Use a list if you need it twice.', NULL, NULL, 31);
