INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conditional-expr'), 3, 'code_output', 'What does this print?', 'xs = [-1, -2, 3]\nprint([x if x > 0 else 0 for x in xs if x != -1])', 'python', '[0, 3]', 'Filter first, then transform what''s left.', 'The trailing if removes -1. The front if-else maps -2 to 0 and keeps 3.', NULL, NULL, 38);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[3]', 0), (@q, 'B', '[0, 3]', 1), (@q, 'C', '[0, 0, 3]', 0), (@q, 'D', 'SyntaxError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conditional-expr'), 3, 'code_output', 'What does this print?', 'print([x for x in range(3) if x > 0 else 0])', 'python', 'SyntaxError', 'A filter can''t have an else.', 'The trailing if is a filter clause, not an expression, so `else` there is invalid syntax. Move it to the front: [x if x > 0 else 0 for x in ...].', NULL, NULL, 39);
