INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genexp'), 4, 'code_output', 'What does this print?', 'print(sum(x for x in range(3), 10))', 'python', 'SyntaxError', 'The bracket-free form only works in one situation.', 'A generator expression can skip its own parentheses only when it is the sole argument. With a second argument write sum((x for x in range(3)), 10).', NULL, NULL, 63);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'SyntaxError', 1), (@q, 'B', '13', 0), (@q, 'C', '3', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'readability-perf'), 4, 'code_output', 'What does this print?', 'import numpy as np\na = np.arange(3)\nr = [x * 2 for x in a]\nprint(type(r).__name__, type(r[0]).__name__)', 'python', 'list int64', 'A comprehension always builds a Python list.', 'Iterating a NumPy array yields NumPy scalars one by one, so you get a list of np.int64 and lose all vectorisation. Write a * 2 instead.', NULL, NULL, 64);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'list int', 0), (@q, 'B', 'ndarray int', 0), (@q, 'C', 'ndarray int64', 0), (@q, 'D', 'list int64', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'readability-perf'), 4, 'mcq', 'A teammate replaced `np.sqrt(arr)` (10 million floats) with `[math.sqrt(x) for x in arr]` because ''comprehensions are fast''. What''s the effect?', NULL, NULL, 'Much slower (often 10x+) and returns a list of Python floats instead of an array', 'A comprehension is still a Python-level loop.', 'Comprehensions beat append-loops, but they still execute interpreter code per element. np.sqrt runs one C loop over the buffer.', NULL, NULL, 65);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Faster, because comprehensions skip NumPy overhead', 0), (@q, 'B', 'Much slower (often 10x+) and returns a list of Python floats instead of an array', 1), (@q, 'C', 'It raises TypeError because math.sqrt can''t take NumPy scalars', 0), (@q, 'D', 'About the same speed, same result type', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'grid-aliasing'), 1, 'code_output', 'What does this print?', 'print([0] * 3, [[0] * 2 for _ in range(2)])', 'python', '[0, 0, 0] [[0, 0], [0, 0]]', '* repeats a list''s items; the comprehension builds one row per pass.', '[0] * 3 repeats the item three times. The comprehension builds a fresh [0, 0] row on each of its 2 passes, giving a 2x2 grid of zeros.', NULL, NULL, 66);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0, 0, 0] [[0, 0, 0, 0]]', 0), (@q, 'B', '[0] [[0], [0]]', 0), (@q, 'C', '[0, 0, 0] [[0, 0], [0, 0]]', 1), (@q, 'D', '0 [[0, 0]]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 1, 'code_output', 'What does this print?', 'labels = ["cat", "dog", "cat"]\nids = {"cat": 0, "dog": 1}\nprint([ids[l] for l in labels])', 'python', '[0, 1, 0]', 'Look each label up in the dict.', 'Models need numbers, not words, so text labels are mapped to integer ids like this before training.', ' "cat" -> 0\n "dog" -> 1\n "cat" -> 0   => [0, 1, 0]', 'Like mapping status strings to enum codes before saving them in a database.', 67);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'KeyError', 0), (@q, 'B', '[0, 1, 0]', 1), (@q, 'C', '[0, 1]', 0), (@q, 'D', '[''cat'', ''dog'', ''cat'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 1, 'code_output', 'What does this print?', 'vocab = ["hi", "ai"]\nprint({w: i for i, w in enumerate(vocab)})', 'python', '{''hi'': 0, ''ai'': 1}', 'enumerate gives (index, word); the dict puts the word first.', 'This is the classic word-to-index vocabulary that every tokenizer builds. The key is the word and the value is its position.', ' enumerate(vocab): (0, ''hi'')  (1, ''ai'')\n {w: i ...}:       ''hi'' -> 0  ''ai'' -> 1', NULL, 68);
