INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'list-comp'), 1, 'fill_blank', 'What does this print? Type the exact output.', 'print([str(n) for n in [1, 2]])', 'python', '[''1'', ''2'']', 'str() turns each number into text.', 'The result is a list of strings; the quotes in the output show that. '',''.join(...) would then glue them into one string.', NULL, NULL, 69);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filters'), 1, 'true_false', '`[x for x in nums if x > 100]` can give back an empty list.', NULL, NULL, 'True', 'What if no item passes the test?', 'If nothing passes the filter, the result is []. That''s not an error, but code that then does result[0] will crash, so check it.', NULL, NULL, 70);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dict-set'), 1, 'fill_blank', 'What does this print? Type the exact output.', 'print({c for c in "hello"} == {"h", "e", "l", "o"})', 'python', 'True', 'A set keeps only one copy of each value.', 'The two l''s collapse into one, so the set has 4 letters and equals the literal set. Set equality ignores order.', NULL, NULL, 71);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filters'), 1, 'fill_blank', 'Keep only the positive numbers: `[x for x in nums ____ x > 0]`', NULL, NULL, 'if', 'Same keyword you''d use for a condition anywhere else.', 'A trailing `if` filters: only items where the condition is True make it into the new list.', NULL, NULL, 72);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filters'), 1, 'true_false', 'This code prints `[False, True, False, True]`.', 'print([n for n in [5, 12, 7, 20] if n >= 10])', 'python', 'False', 'Which numbers are at least 10?', 'Only 12 and 20 pass. The kept items are the numbers themselves, in their original order.', NULL, NULL, 73);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 1, 'mcq', 'What does `clean = [w.lower() for w in tokens]` do?', NULL, NULL, 'Makes a new list with every token in lower case; tokens is unchanged', 'Comprehensions always build something new.', 'Each token is lower-cased and collected into a new list. Normalising case like this is one of the first steps in many text pipelines.', NULL, NULL, 74);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Lower-cases tokens in place', 0), (@q, 'B', 'Returns one lower-cased string', 0), (@q, 'C', 'Makes a new list with every token in lower case; tokens is unchanged', 1), (@q, 'D', 'Removes tokens that are already lower case', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'grid-aliasing'), 2, 'mcq', 'Why does setting grid[0][0] also change grid[1][0]?', 'grid = [[0] * 2] * 2\ngrid[0][0] = 1\nprint(grid)', 'python', '`* 2` on the outer list repeats a reference to the same row, so both slots are one list', '* copies references, not the row itself.', '[[0] * 2] * 2 puts the SAME row object in the list twice, so changing one ''row'' changes both. Build grids with a comprehension instead.', ' grid[0] --+\n           +--> [0, 0]   (one row object)\n grid[1] --+', 'Two shortcuts on your desktop pointing to the same file: edit through one, and both show the change.', 75);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Python copies the change to every row to keep the grid square', 0), (@q, 'B', 'Assigning to grid[0][0] broadcasts down the column, like NumPy', 0), (@q, 'C', 'All integers in a list are shared, so changing one changes them all', 0), (@q, 'D', '`* 2` on the outer list repeats a reference to the same row, so both slots are one list', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'grid-aliasing'), 2, 'true_false', 'This code prints `[[1, 0], [0, 0]]`.', 'grid = [[0] * 2 for _ in range(2)]\ngrid[0][0] = 1\nprint(grid)', 'python', 'True', 'The comprehension runs [0] * 2 again on each pass.', 'Each pass creates a new row, so the rows are independent. This is the correct way to build a list-of-lists grid in plain Python.', ' grid[0] --> [1, 0]   (row object A)\n grid[1] --> [0, 0]   (row object B, built separately)', NULL, 76);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 2, 'code_output', 'What does this print?', 'w2i = {"<pad>": 0, "hi": 1}\ni2w = {i: w for w, i in w2i.items()}\nprint([i2w[i] for i in [1, 0, 1]])', 'python', '[''hi'', ''<pad>'', ''hi'']', 'First invert the vocab, then decode the ids.', 'Tokenizers keep both directions: word -> id to encode text, and id -> word to decode the model''s output back into text.', ' w2i: ''<pad>'' -> 0   ''hi'' -> 1     (encode)\n i2w:  0 -> ''<pad>''   1 -> ''hi''    (decode)', NULL, 77);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''hi'', ''<pad>'', ''hi'']', 1), (@q, 'B', 'KeyError', 0), (@q, 'C', '[''<pad>'', ''hi'', ''<pad>'']', 0), (@q, 'D', '[1, 0, 1]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 2, 'code_output', 'What does this print?', 'print([[1 if j == y else 0 for j in range(3)] for y in [2, 0]])', 'python', '[[0, 0, 1], [1, 0, 0]]', 'One row per label; a 1 goes in the label''s column.', 'This is one-hot encoding: label 2 becomes [0, 0, 1]. In real code np.eye(n)[labels] or torch.nn.functional.one_hot does it without a Python loop.', ' label 2 -> [0, 0, 1]\n label 0 -> [1, 0, 0]\n column:     0  1  2', NULL, 78);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[[0, 1, 0], [1, 0, 0]]', 0), (@q, 'B', '[[1, 0, 0], [0, 0, 1]]', 0), (@q, 'C', '[2, 0]', 0), (@q, 'D', '[[0, 0, 1], [1, 0, 0]]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 2, 'code_output', 'What does this print?', 'tokens = ["Hi", "", "AI", " "]\nprint([t.lower() for t in tokens if t.strip()])', 'python', '[''hi'', ''ai'']', 'An empty string is falsy, and so is a stripped space.', 't.strip() is '''' for blank tokens, so the filter drops them, and the expression lower-cases the rest. Filter and clean in one pass.', NULL, 'Like trimming and lower-casing emails before checking them for duplicates.', 79);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''hi'', '''', ''ai'', '' '']', 0), (@q, 'B', '[''hi'', ''ai'']', 1), (@q, 'C', '[''hi'', ''ai'', '' '']', 0), (@q, 'D', '[''Hi'', ''AI'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'list-comp'), 2, 'code_output', 'What does this print?', 'print([f"{i}:{c}" for i, c in enumerate("ab")])', 'python', '[''0:a'', ''1:b'']', 'enumerate gives (index, item) pairs, unpacked into i and c.', 'The loop target of a comprehension can unpack, just like a for loop. f-strings make the formatting readable.', NULL, NULL, 80);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''0:a'', ''1:b'']', 1), (@q, 'B', '[''0:a1:b'']', 0), (@q, 'C', '[''a:0'', ''b:1'']', 0), (@q, 'D', '[''1:a'', ''2:b'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'list-comp'), 2, 'code_output', 'What does this print?', 'print([a * b for a, b in zip([1, 2, 3], [4, 5, 6])])', 'python', '[4, 10, 18]', 'zip pairs items at the same position.', 'Element-wise products: 1*4, 2*5, 3*6. Wrapping it in sum() gives the dot product (32), the core operation behind similarity scores.', ' a: 1   2   3\n b: 4   5   6\n *: 4  10  18   -> sum = 32 (dot product)', NULL, 81);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[4, 10, 18]', 1), (@q, 'B', '[5, 7, 9]', 0), (@q, 'C', '[4, 5, 6, 8, 10, 12]', 0), (@q, 'D', '32', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filters'), 2, 'code_output', 'What does this print?', 'words = ["apple", "Bob", "cat"]\nprint([w for w in words if w[0].isupper() or len(w) == 3])', 'python', '[''Bob'', ''cat'']', 'Either condition is enough to keep a word.', '''Bob'' passes both tests, ''cat'' passes the length test, and ''apple'' fails both. Use `or`/`and` inside one if for complex filters.', NULL, NULL, 82);
