INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dict-set'), 2, 'true_false', 'This code prints `[''ai'', ''ml'']`.', 'print(sorted({w.lower() for w in ["AI", "ai", "Ml"]}))', 'python', 'True', 'Lower-case first, then the set removes duplicates.', '''AI'' and ''ai'' both become ''ai'', so the set keeps one. Sorting makes the order predictable, since sets have no fixed order.', NULL, NULL, 83);
