INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'try-except'), 1, 'true_false', 'If line 2 of a try block raises an error, lines 3 and 4 of that try block still run before the except block.', NULL, NULL, 'False', 'Think of an exception as an emergency exit.', 'The moment a line raises, Python jumps straight to the matching except. The rest of the try block is skipped.', NULL, NULL, 16);
