INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'assert-warnings'), 2, 'true_false', '`assert` is a good way to validate user input in a production web API.', NULL, NULL, 'False', 'Asserts can be switched off.', 'Running Python with -O removes every assert statement. Validate input with if + raise ValueError so the check can''t disappear.', NULL, NULL, 45);
