INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'supervised'), 1, 'fill_blank', 'Classification with exactly two possible classes (like spam / not spam) is called ____ classification.', NULL, NULL, 'binary', 'Two = bi-.', 'Binary = two classes. More than two (one per example) is multiclass.', NULL, NULL, 22);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'supervised'), 2, 'code_output', 'What does this print?', 'from sklearn.utils.multiclass import type_of_target\nprint(type_of_target([0, 1, 1, 0]))\nprint(type_of_target([0, 1, 2, 1]))\nprint(type_of_target([1.5, 2.25, 3.0]))', 'python', 'binary\nmulticlass\ncontinuous', 'sklearn looks at the label values to guess the task.', 'Two distinct values = binary, more distinct integers = multiclass, non-integer floats = continuous (regression).', NULL, NULL, 23);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'binary\nmulticlass\ncontinuous', 1), (@q, 'B', 'binary\nbinary\ncontinuous', 0), (@q, 'C', 'binary\nmulticlass\nmulticlass', 0), (@q, 'D', 'multiclass\nmulticlass\nmulticlass', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'supervised'), 2, 'code_output', 'What does this print?', 'from sklearn.utils.multiclass import type_of_target\nprint(type_of_target([[1, 0, 1], [0, 1, 1], [1, 0, 0]]))', 'python', 'multilabel-indicator', 'Each row can have several 1s.', 'A 0/1 matrix where each row can have more than one 1 is a multilabel target (''multilabel-indicator'').', NULL, NULL, 24);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'binary', 0), (@q, 'B', 'multiclass', 0), (@q, 'C', 'multilabel-indicator', 1), (@q, 'D', 'multiclass-multioutput', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'supervised'), 2, 'mcq', 'A movie can be tagged ''action'', ''comedy'' and ''romance'' at the same time. Predicting its tags is:', NULL, NULL, 'Multilabel classification', 'How many labels can one movie have?', 'Several labels can be on at once = multilabel. Multiclass means exactly one class per example.', '            action comedy romance\n multiclass:   0      1      0     (exactly one 1)\n multilabel:   1      1      0     (any number of 1s)', NULL, 25);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Binary classification', 0), (@q, 'B', 'Multiclass classification', 0), (@q, 'C', 'Multilabel classification', 1), (@q, 'D', 'Regression', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'supervised'), 2, 'code_output', 'What does this print?', 'from sklearn.preprocessing import MultiLabelBinarizer\nmlb = MultiLabelBinarizer()\nY = mlb.fit_transform([["action", "comedy"], ["drama"], ["action"]])\nprint(Y.shape, list(mlb.classes_))', 'python', '(3, 3) [''action'', ''comedy'', ''drama'']', 'One row per movie, one column per distinct tag.', '3 movies x 3 distinct tags (sorted alphabetically). Each row has a 1 for every tag the movie has.', NULL, NULL, 26);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(3, 1) [''action'']', 0), (@q, 'B', '(3, 2) [''action'', ''comedy'']', 0), (@q, 'C', '(4, 3) [''action'', ''comedy'', ''drama'']', 0), (@q, 'D', '(3, 3) [''action'', ''comedy'', ''drama'']', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unsupervised'), 2, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.decomposition import PCA\nrng = np.random.default_rng(0)\nX = rng.normal(size=(100, 10))\nZ = PCA(n_components=2).fit_transform(X)\nprint(Z.shape)', 'python', '(100, 2)', 'Rows stay, columns are compressed.', 'PCA keeps every row and squeezes the 10 features down to 2 new ones: shape (100, 2).', NULL, NULL, 27);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(100, 2)', 1), (@q, 'B', '(100, 10)', 0), (@q, 'C', '(10, 2)', 0), (@q, 'D', '(2, 10)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unsupervised'), 2, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.cluster import KMeans\nX = np.array([[1, 1], [1, 2], [2, 1], [10, 10], [10, 11], [11, 10]])\nkm = KMeans(n_clusters=2, n_init=10, random_state=0).fit(X)\nprint(sorted(np.bincount(km.labels_).tolist()))', 'python', '[3, 3]', 'Look at where the points sit.', 'Two tight groups of 3 points each, far apart. KMeans finds both; the sizes are 3 and 3.', NULL, NULL, 28);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[3, 3]', 1), (@q, 'B', '[6]', 0), (@q, 'C', '[2, 4]', 0), (@q, 'D', '[1, 5]', 0);
