INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'semi-self'), 2, 'code_output', 'What does this print?', 'tokens = "the cat sat on the mat".split()\npairs = list(zip(tokens[:-1], tokens[1:]))\nprint(len(pairs), pairs[0])', 'python', '5 (''the'', ''cat'')', 'Each word is paired with the word that follows it.', '6 tokens give 5 (input, next-word) pairs. This is exactly how next-token training data is made: the text labels itself.', NULL, NULL, 30);
