INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'semi-self'), 2, 'mcq', 'A company has 1,000 labelled support tickets and 500,000 unlabelled ones. Using both together to train a classifier is called:', NULL, NULL, 'Semi-supervised learning', 'A small labelled set plus a large unlabelled set.', 'Semi-supervised learning uses a few labels plus lots of unlabelled data (e.g. pseudo-labelling, label propagation).', NULL, NULL, 31);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Online learning', 0), (@q, 'B', 'Reinforcement learning', 0), (@q, 'C', 'Semi-supervised learning', 1), (@q, 'D', 'Unsupervised learning', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rl'), 2, 'mcq', 'In RL, ''exploration vs exploitation'' means choosing between:', NULL, NULL, 'Trying actions you''re unsure about to learn more, vs using the action you currently think is best', 'Your favourite restaurant vs a new one.', 'Exploitation earns reward now; exploration gathers information that may earn more later. Good agents balance both.', NULL, 'Always ordering your usual dish vs occasionally trying something new on the menu.', 32);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Using a GPU vs a CPU', 0), (@q, 'B', 'Training vs testing', 0), (@q, 'C', 'Trying actions you''re unsure about to learn more, vs using the action you currently think is best', 1), (@q, 'D', 'Big vs small rewards', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rl'), 2, 'true_false', 'An RL agent that always picks the action with the highest estimated value (never exploring) is guaranteed to find the best policy.', NULL, NULL, 'False', 'What if its first estimates are wrong?', 'Pure exploitation can lock onto a mediocre action early and never try the one that is actually better.', NULL, NULL, 33);
