INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scaling'), 1, 'mcq', 'Why do we often scale features (e.g. bring ''salary'' and ''age'' to similar ranges)?', NULL, NULL, 'So a feature with big numbers doesn''t dominate models that use distances or gradients', 'Salary ~ 1,000,000 vs age ~ 30.', 'Without scaling, salary''s huge numbers swamp age in distance calculations (kNN) and slow gradient-based training.', NULL, NULL, 12);
