INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'features-labels'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"rooms": [2, 3, 4], "area": [800, 1200, 1500], "price": [50, 75, 95]})\nX = df.drop(columns="price")\ny = df["price"]\nprint(X.shape, y.shape)', 'python', '(3, 2) (3,)', 'drop removes the label column from the features.', 'X keeps 3 rows and the 2 feature columns; y is a single column (a Series), shape (3,).', NULL, NULL, 20);
