INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ratios'), 2, 'mcq', 'You have 10 million labelled rows. Why might a 98 / 1 / 1 split be perfectly sensible?', NULL, NULL, '1% is still 100,000 rows, plenty for a stable score', 'What matters for a reliable score: the percentage or the count?', 'The noise in a measured accuracy depends on the number of test examples, not the percentage. With huge data, a small fraction is already a large count.', NULL, NULL, 15);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Validation is not needed for large data', 0), (@q, 'B', '1% is still 100,000 rows, plenty for a stable score', 1), (@q, 'C', 'Big datasets must always use 98/1/1', 0), (@q, 'D', 'Test sets above 1% cause overfitting', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ratios'), 3, 'mcq', 'A test set has 100 examples and the model scores 90% accuracy. Roughly how uncertain is that number (one standard error)?', NULL, NULL, 'About +/- 3 percentage points', 'Standard error of a proportion is sqrt(p(1-p)/n).', 'sqrt(0.9 x 0.1 / 100) = 0.03. Two models 2 points apart on 100 test examples are not reliably different.', NULL, NULL, 16);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'About +/- 0.1 points', 0), (@q, 'B', 'Zero: accuracy is exact', 0), (@q, 'C', 'About +/- 3 percentage points', 1), (@q, 'D', 'About +/- 30 points', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ratios'), 3, 'code_output', 'What does this print?', 'import math\np, n = 0.9, 1000\nse = math.sqrt(p * (1 - p) / n)\nprint(round(se * 100, 1))', 'python', '0.9', 'Ten times more test rows shrinks the error by sqrt(10), not by 10.', 'sqrt(0.09/1000) = 0.0095, about 0.9 points. Going from 100 to 1000 test rows cut the error from 3.0 to about 0.9.', NULL, NULL, 17);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0.9', 1), (@q, 'B', '3.0', 0), (@q, 'C', '9.0', 0), (@q, 'D', '0.3', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ratios'), 2, 'true_false', 'With a very small dataset (say 150 rows), a single 80/20 split gives a reliable estimate of model quality.', NULL, NULL, 'False', 'How many rows land in that 20%?', 'Only 30 test rows: the score swings a lot depending on which rows land there. Use k-fold cross-validation instead.', NULL, NULL, 18);
