INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tts'), 1, 'mcq', 'What does random_state=42 do in train_test_split?', NULL, NULL, 'Fixes the shuffle so you get the same split every run', 'Think of it as a seed.', 'random_state seeds the shuffle. Same seed, same data, same split: results are reproducible.', NULL, 'Like pinning a dependency version so every build is the same.', 19);
