INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tts'), 1, 'code_output', 'What does this print?', 'from sklearn.model_selection import train_test_split\nX = list(range(10))\na, _ = train_test_split(X, test_size=0.3, random_state=1)\nb, _ = train_test_split(X, test_size=0.3, random_state=1)\nprint(a == b)', 'python', 'True', 'Same seed, same input.', 'The same random_state on the same data gives the identical split, so the training lists are equal.', NULL, NULL, 20);
