INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tts'), 2, 'code_output', 'What does this print?', 'from sklearn.model_selection import train_test_split\nX = list(range(10))\na, b = train_test_split(X, test_size=0.3, shuffle=False)\nprint(b)', 'python', '[7, 8, 9]', 'No shuffling means the order is kept.', 'With shuffle=False the last 30% of rows (in original order) become the test set.', NULL, NULL, 21);
