INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tts'), 2, 'mcq', 'You need train/val/test from one array with train_test_split. What is the usual way?', NULL, NULL, 'Call it twice: first split off test, then split the remainder into train and val', 'train_test_split only ever makes two pieces per array.', 'There is no val_size argument. Split off test first, then split the rest. Remember the second test_size is a fraction of the remainder.', NULL, NULL, 27);
