INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tts'), 2, 'code_output', 'What does this print?', 'from sklearn.model_selection import train_test_split\nX = list(range(100))\nrest, test = train_test_split(X, test_size=0.2, random_state=0)\ntrain, val = train_test_split(rest, test_size=0.25, random_state=0)\nprint(len(train), len(val), len(test))', 'python', '60 20 20', 'The second split works on the 80 rows that are left.', '20 rows go to test; 25% of the remaining 80 is 20 for val; 60 are left for training.', NULL, NULL, 28);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '75 5 20', 0), (@q, 'B', '60 25 15', 0), (@q, 'C', '55 25 20', 0), (@q, 'D', '60 20 20', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tts'), 3, 'mcq', 'Your regression target is house price and you want price levels balanced across train and test. stratify=y with float prices fails. What do you do?', NULL, NULL, 'Bin the target into quantiles (e.g. pd.qcut) and stratify on the bins', 'Stratify needs a small number of categories.', 'Stratification needs discrete classes. Quantile bins give a handful of groups with enough members each. Rounded floats still leave most values unique.', NULL, NULL, 29);
