INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 2, 'code_output', 'What does this print?', 'import numpy as np\nprint(np.full((2, 2), 7))', 'python', '[[7 7]\n [7 7]]', 'np.full takes its dtype from the fill value.', 'np.full(shape, value) fills the shape with value. 7 is an int, so the array is int.', NULL, NULL, 16);
