INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing'), 1, 'mcq', 'In a 2D array `a`, what does `a[1, 2]` select?', NULL, NULL, 'The element in row 1, column 2', 'The first number is always the row (axis 0).', 'a[row, col]. With 0-based indexing, a[1, 2] is the second row, third column.', '         col0 col1 col2\nrow0  [[  0    1    2 ]\nrow1   [  3    4   (5)]]   a[1, 2] = 5', NULL, 51);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Columns 1 to 2', 0), (@q, 'B', 'The element in row 2, column 1', 0), (@q, 'C', 'Rows 1 and 2', 0), (@q, 'D', 'The element in row 1, column 2', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing'), 2, 'code_output', 'What does this print?', 'import numpy as np\na = np.arange(12).reshape(3, 4)\nprint(a[:, 1])', 'python', '[1 5 9]', ''':'' means ''all rows''.', 'a[:, 1] takes column 1 from every row. The result is 1D.', '[[ 0  1  2  3]\n [ 4  5  6  7]      a[:, 1] -> [1 5 9]\n [ 8  9 10 11]]\n     ^', NULL, 52);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[[1]\n [5]\n [9]]', 0), (@q, 'B', '[1 2 3]', 0), (@q, 'C', '[4 5 6 7]', 0), (@q, 'D', '[1 5 9]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing'), 2, 'mcq', 'What shapes do an integer index and a length-1 slice produce?', 'import numpy as np\na = np.arange(12).reshape(3, 4)\nprint(a[:, 1].shape, a[:, 1:2].shape)', 'python', '(3,) (3, 1)', 'An integer index removes an axis; a slice keeps it.', 'a[:, 1] drops the column axis (1D). a[:, 1:2] is a slice of length 1, so the axis stays: a column vector.', NULL, NULL, 53);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(3,) (3,)', 0), (@q, 'B', '(1, 3) (3, 1)', 0), (@q, 'C', '(3,) (3, 1)', 1), (@q, 'D', '(3, 1) (3, 1)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing'), 2, 'code_output', 'What does this print?', 'import numpy as np\na = np.arange(6)\nprint(a[::-1])\nprint(a[::2])', 'python', '[5 4 3 2 1 0]\n[0 2 4]', 'The third slice number is the step.', 'A step of -1 walks backwards over everything; a step of 2 takes every second element from 0.', NULL, NULL, 54);
