INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing'), 2, 'true_false', 'For a NumPy 2D array, `a[0][1]` and `a[0, 1]` give the same element.', NULL, NULL, 'True', 'a[0] is itself an array.', 'Both give the same value. a[0, 1] is preferred: it is one indexing operation instead of two and it is the only form that works with slices like a[:, 1].', NULL, NULL, 55);
