INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'masks-fancy'), 1, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([3, 8, 1, 9])\nprint(a > 4)', 'python', '[False  True False  True]', 'Comparison on an array is done element by element.', 'a > 4 gives a boolean array of the same shape: a ''mask''. (NumPy pads False/True to line up.)', NULL, NULL, 60);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', '[False  True False  True]', 1), (@q, 'C', '[0 1 0 1]', 0), (@q, 'D', '[8 9]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'masks-fancy'), 1, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([3, 8, 1, 9])\nprint(a[a > 4])', 'python', '[8 9]', 'A mask inside [] keeps the True positions.', 'a[mask] keeps only the elements where the mask is True. This is how you filter rows in ML code.', NULL, 'Like SQL: SELECT value FROM a WHERE value > 4.', 61);
