INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'masks-fancy'), 2, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([3, 8, 1, 9])\nprint(a[(a > 2) & (a < 9)])', 'python', '[3 8]', '& is element-wise AND.', 'Use & (and), | (or), ~ (not) on masks, with brackets around each comparison because & binds tighter than >.', NULL, NULL, 62);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[3 8]', 1), (@q, 'B', 'ValueError', 0), (@q, 'C', '[3 8 9]', 0), (@q, 'D', '[8]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'masks-fancy'), 2, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([3, 8, 1, 9])\nprint(a[(a > 2) and (a < 9)])', 'python', 'ValueError', 'Python''s `and` wants ONE True/False.', '`and` calls bool() on the whole array, which is ambiguous for more than one element: ValueError ''The truth value of an array ... is ambiguous''. Use & instead.', NULL, NULL, 63);
