INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'masks-fancy'), 2, 'mcq', 'Which elements does the index list pick?', 'import numpy as np\na = np.array([3, 8, 1, 9])\nprint(a[[0, 2, 0]])', 'python', '[3 1 3]', 'A list of indexes picks those positions, repeats allowed.', 'Fancy indexing with a list returns the elements at those positions, in that order, repeats included.', NULL, NULL, 64);
