INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'masks-fancy'), 2, 'fill_blank', 'Complete to count how many values are above 4: `(a > 4).____()`', NULL, NULL, 'sum', 'True counts as 1.', '(a > 4).sum() adds up the booleans, so it counts the Trues. np.count_nonzero(a > 4) does the same.', NULL, NULL, 66);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'masks-fancy'), 3, 'code_output', 'What does this print?', 'import numpy as np\na = np.arange(9).reshape(3, 3)\nprint(a[[0, 2], [1, 2]])', 'python', '[1 8]', 'Two index lists are paired up element by element.', 'a[[0, 2], [1, 2]] picks (0, 1) and (2, 2): values 1 and 8. To get the 2x2 sub-grid use a[np.ix_([0, 2], [1, 2])].', '[[0 (1) 2]       pairs: (0,1) -> 1\n [3  4  5]              (2,2) -> 8\n [6  7 (8)]]', NULL, 67);
