INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshaping'), 1, 'mcq', 'Which reshape of a 12-element array is NOT allowed?', NULL, NULL, '(5, 2)', 'Multiply the numbers in each shape.', 'reshape cannot add or drop elements: the product of the new shape must equal 12. 5 x 2 = 10.', NULL, NULL, 85);
