INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshaping'), 2, 'mcq', 'What shape does reshape(3, -1) give for 12 elements?', 'import numpy as np\na = np.arange(12)\nprint(a.reshape(3, -1).shape)', 'python', '(3, 4)', '-1 means ''work this one out for me''.', 'With 12 elements and 3 rows, the -1 becomes 12 / 3 = 4.', NULL, NULL, 86);
