INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshaping'), 2, 'mcq', 'What shape is the transpose?', 'import numpy as np\na = np.zeros((2, 5))\nprint(a.T.shape)', 'python', '(5, 2)', '.T swaps rows and columns.', 'The transpose of a 2x5 matrix is 5x2.', NULL, NULL, 88);
