INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshaping'), 2, 'mcq', 'What shape is left after squeeze?', 'import numpy as np\na = np.zeros((1, 3, 1))\nprint(np.squeeze(a).shape)', 'python', '(3,)', 'squeeze removes every axis of length 1.', 'Both length-1 axes go, leaving (3,). Pass axis= to remove only one of them.', NULL, NULL, 90);
