INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshaping'), 3, 'code_output', 'What does this print?', 'import numpy as np\na = np.arange(12)\nprint(a.reshape(-1, -1))', 'python', 'ValueError', 'How many unknowns can NumPy solve for?', 'Only one dimension may be -1. With two unknowns the shape is ambiguous, so ValueError.', NULL, NULL, 94);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', 'ValueError', 1), (@q, 'C', '[[ 0  1  2 ...]]', 0), (@q, 'D', '(12, 1)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshaping'), 3, 'mcq', 'A batch of images has shape `(32, 28, 28)`. Which call flattens each image into a row for a linear model?', NULL, NULL, 'X.reshape(32, -1)  -> (32, 784)', 'Keep the batch axis, merge the rest.', 'reshape(32, -1) keeps one row per image and merges 28 x 28 = 784 pixels. reshape(-1, 32) has the right numbers but mixes pixels from different images in each column.', '(32, 28, 28)\n  |    \\___/\nbatch   pixels: 28 * 28 = 784\nreshape(32, -1) -> (32, 784)   one row per image', NULL, 95);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'X.reshape(-1, 32)  -> (784, 32)', 0), (@q, 'B', 'X.reshape(32, -1)  -> (32, 784)', 1), (@q, 'C', 'X.flatten()  -> (25088,)', 0), (@q, 'D', 'X.reshape(-1)  -> (25088,)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshaping'), 4, 'code_output', 'What does this print?', 'import numpy as np\na = np.arange(6)\nprint(a.reshape(2, 3, order="F"))', 'python', '[[0 2 4]\n [1 3 5]]', 'F (Fortran) order fills down the columns first.', 'order=''F'' makes the FIRST index change fastest, so values fill column by column: 0 1 go in column 0, 2 3 in column 1...', NULL, NULL, 96);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[[0 3]\n [1 4]\n [2 5]]', 0), (@q, 'B', '[[5 4 3]\n [2 1 0]]', 0), (@q, 'C', '[[0 2 4]\n [1 3 5]]', 1), (@q, 'D', '[[0 1 2]\n [3 4 5]]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshaping'), 4, 'code_output', 'What does this print?', 'import numpy as np\na = np.arange(6).reshape(2, 3)\nb = a.T\nb.shape = (6,)\nprint(b)', 'python', 'AttributeError', 'Setting .shape must never copy.', 'Assigning to .shape changes the shape in place, which is only possible without a copy. a.T cannot be flattened as a view, so NumPy raises AttributeError (''Incompatible shape for in-place modification''). reshape would quietly copy instead.', NULL, NULL, 97);
