INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stack-split'), 1, 'code_output', 'What does this print?', 'import numpy as np\nprint(np.concatenate([np.array([1, 2]), np.array([3, 4])]))', 'python', '[1 2 3 4]', 'concatenate joins along an EXISTING axis.', 'Two 1D arrays joined along axis 0 give one longer 1D array.', NULL, NULL, 98);
