INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stack-split'), 2, 'mcq', 'What shapes do vstack and hstack give for two 1D arrays?', 'import numpy as np\na = np.array([1, 2, 3])\nb = np.array([4, 5, 6])\nprint(np.vstack([a, b]).shape, np.hstack([a, b]).shape)', 'python', '(2, 3) (6,)', 'v = vertical (pile up), h = horizontal (side by side).', 'vstack treats each 1D array as a row and piles them: (2, 3). hstack on 1D arrays just joins them: (6,).', 'vstack:  [1 2 3]       hstack: [1 2 3 4 5 6]\n         [4 5 6]', NULL, 99);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(2, 3) (2, 3)', 0), (@q, 'B', '(3, 2) (6,)', 0), (@q, 'C', '(2, 3) (6,)', 1), (@q, 'D', '(6,) (2, 3)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stack-split'), 2, 'mcq', 'What shapes does np.stack give with axis=0 and axis=1?', 'import numpy as np\na = np.array([1, 2, 3])\nb = np.array([4, 5, 6])\nprint(np.stack([a, b]).shape, np.stack([a, b], axis=1).shape)', 'python', '(2, 3) (3, 2)', 'stack creates a NEW axis at the given position.', 'stack adds an axis: axis=0 puts the arrays as rows (2, 3), axis=1 puts them as columns (3, 2).', 'a = [1 2 3]   b = [4 5 6]\naxis=0: [[1 2 3]      axis=1: [[1 4]\n         [4 5 6]]              [2 5]\n         (2, 3)                [3 6]]  (3, 2)', NULL, 100);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(3, 2) (2, 3)', 0), (@q, 'B', '(2, 3) (2, 3)', 0), (@q, 'C', '(2, 3) (3, 2)', 1), (@q, 'D', '(6,) (3, 2)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stack-split'), 2, 'mcq', 'What shapes do the two concatenations give?', 'import numpy as np\na = np.zeros((2, 3))\nb = np.ones((2, 3))\nprint(np.concatenate([a, b], axis=1).shape, np.concatenate([a, b]).shape)', 'python', '(2, 6) (4, 3)', 'The default axis is 0.', 'axis=1 joins side by side (more columns): (2, 6). The default axis=0 stacks rows: (4, 3).', NULL, NULL, 101);
