INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stack-split'), 3, 'code_output', 'What does this print?', 'import numpy as np\na = np.zeros((2, 3))\nb = np.zeros((3, 3))\nprint(np.concatenate([a, b], axis=1).shape)', 'python', 'ValueError', 'All axes except the join axis must match.', 'Joining along axis 1 requires the same number of rows (2 vs 3), so ValueError. Along axis 0 it would work: (5, 3).', NULL, NULL, 102);
