INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 3, 'mcq', 'A sensor column has 40% missing values. Which first step is most sensible before training a model?', NULL, NULL, 'Check WHY values are missing (and add a ''was_missing'' flag if missingness may carry information) before choosing to drop or impute', 'Missingness itself can be a signal.', 'Dropping 40% of rows loses data and may bias it; filling with 0 invents values. Understand the cause, consider a missing-indicator column, and impute using training-set statistics only. Many scikit-learn models reject NaN.', NULL, NULL, 15);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Check WHY values are missing (and add a ''was_missing'' flag if missingness may carry information) before choosing to drop or impute', 1), (@q, 'B', 'Always drop every row with a missing value', 0), (@q, 'C', 'Ignore it: models handle NaN automatically', 0), (@q, 'D', 'Always replace missing values with 0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 3, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\ns = pd.Series([1, np.nan, 3], dtype="float64")\nprint(s.isna().sum(), (s.astype("Int64")).isna().sum(), s.astype("Int64").dtype)', 'python', '1 1 Int64', 'The nullable Int64 type has its own missing marker.', 'astype(''Int64'') converts NaN to pd.NA and keeps it missing. astype(''int64'') on the same Series would raise IntCastingNaNError.', NULL, NULL, 16);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1 0 Int64', 0), (@q, 'B', '1 1 Int64', 1), (@q, 'C', '1 1 int64', 0), (@q, 'D', 'IntCastingNaNError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 4, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\ns = pd.Series([1, np.nan, 3])\nprint(s.astype("int64"))', 'python', 'IntCastingNaNError', 'Where would the NaN go in a plain int64 array?', 'A NumPy int64 array has no way to store NaN, so pandas raises IntCastingNaNError (''Cannot convert non-finite values (NA or inf) to integer''). Fill first, or use ''Int64''.', NULL, NULL, 17);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'IntCastingNaNError', 1), (@q, 'B', 'TypeError', 0), (@q, 'C', 'ValueError', 0), (@q, 'D', '0    1\n1    0\n2    3\ndtype: int64', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'duplicates'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"id": [1, 1, 2], "v": ["a", "a", "b"]})\nprint(df.duplicated().tolist(), len(df.drop_duplicates()))', 'python', '[False, True, False] 2', 'By default the FIRST occurrence is not counted as a duplicate.', 'duplicated() marks repeats after the first (keep=''first''). drop_duplicates removes them, leaving 2 rows.', NULL, 'SQL: SELECT DISTINCT * FROM df.', 18);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[False, True, False] 3', 0), (@q, 'B', '[True, True, False] 2', 0), (@q, 'C', '[False, False, False] 3', 0), (@q, 'D', '[False, True, False] 2', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'duplicates'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series(["cat", "dog", "cat", "cat"])\nprint(s.value_counts().to_dict())', 'python', '{''cat'': 3, ''dog'': 1}', 'value_counts counts each distinct value, most frequent first.', 'cat appears 3 times, dog once. The result is sorted by count, descending.', NULL, 'SQL: SELECT v, COUNT(*) FROM t GROUP BY v ORDER BY 2 DESC.', 19);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[3, 1]', 0), (@q, 'B', '{''cat'': 1, ''dog'': 1}', 0), (@q, 'C', '{''dog'': 1, ''cat'': 3}', 0), (@q, 'D', '{''cat'': 3, ''dog'': 1}', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'duplicates'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series(["cat", "dog", "cat", "cat"])\nprint(s.value_counts(normalize=True).tolist(), s.nunique())', 'python', '[0.75, 0.25] 2', 'normalize turns counts into fractions.', 'normalize=True divides by the total (3/4, 1/4). nunique counts distinct values: 2. Handy for checking class balance.', NULL, NULL, 20);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0.75, 0.25] 4', 0), (@q, 'B', '[0.5, 0.5] 2', 0), (@q, 'C', '[3, 1] 2', 0), (@q, 'D', '[0.75, 0.25] 2', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'duplicates'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series(["a", "b", "a", None])\nprint(s.value_counts().sum(), s.value_counts(dropna=False).sum())', 'python', '3 4', 'value_counts hides missing values unless asked.', 'dropna=True is the default, so None isn''t counted (3). dropna=False adds a row for the missing value (4).', NULL, NULL, 21);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '3 3', 0), (@q, 'B', '4 3', 0), (@q, 'C', '3 4', 1), (@q, 'D', '4 4', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'duplicates'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"email": ["a@x", "b@x", "a@x"], "ts": [1, 2, 3]})\nprint(df.drop_duplicates(subset="email", keep="last")["ts"].tolist())', 'python', '[2, 3]', 'subset picks which columns define ''same''; keep picks which copy survives.', 'Rows are duplicates if email matches. keep=''last'' keeps the later a@x (ts 3); b@x is unique. Survivors keep their original order: ts 2, then 3.', NULL, NULL, 22);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2]', 0), (@q, 'B', '[2, 3]', 1), (@q, 'C', '[3]', 0), (@q, 'D', '[1, 2, 3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'duplicates'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"id": [1, 1, 2]})\nprint(df.duplicated(keep=False).tolist())', 'python', '[True, True, False]', 'keep=False means no copy is treated as the original.', 'keep=False marks every row that has a twin, useful for inspecting ALL conflicting records.', NULL, NULL, 23);
