INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'duplicates'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series(["Pune", "pune ", "PUNE"])\nprint(s.nunique(), s.str.strip().str.lower().nunique())', 'python', '3 1', 'Exact string matching is case- and space-sensitive.', 'The three strings differ by case and a trailing space, so they count as 3 distinct values. Normalising with strip + lower makes them one.', NULL, NULL, 25);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '2 1', 0), (@q, 'B', '1 1', 0), (@q, 'C', '3 1', 1), (@q, 'D', '3 3', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'duplicates'), 3, 'mcq', 'Why can duplicate rows between your train and test sets make a model look better than it is?', NULL, NULL, 'The model is tested on rows it has already memorised, so test accuracy overstates real-world accuracy', 'Think of exam questions you''ve already seen the answers to.', 'If the same record sits in both sets, the test is no longer ''unseen data''. Deduplicate (or split by entity, e.g. user_id) before splitting.', NULL, NULL, 26);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Duplicates make training slower but don''t affect scores', 0), (@q, 'B', 'Duplicates only matter for regression, not classification', 0), (@q, 'C', 'Duplicates are automatically removed by scikit-learn', 0), (@q, 'D', 'The model is tested on rows it has already memorised, so test accuracy overstates real-world accuracy', 1);
