INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'types'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series(["$1,200", "$350"])\nprint(s.str.replace("[$,]", "", regex=True).astype(int).tolist())', 'python', '[1200, 350]', 'Remove the characters that aren''t digits first.', 'The regex [$,] removes dollar signs and commas, leaving ''1200'' and ''350'', which astype(int) converts.', NULL, NULL, 31);
