INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'strings'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([" a", "b "])\nprint((s == "a").sum(), (s.str.strip() == "a").sum())', 'python', '0 1', 'Invisible whitespace breaks equality.', ''' a'' is not equal to ''a''. Stray spaces from CSVs and forms are the #1 reason filters or merges silently miss rows.', NULL, NULL, 49);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '2 1', 0), (@q, 'B', '1 1', 0), (@q, 'C', '0 0', 0), (@q, 'D', '0 1', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'strings'), 4, 'mcq', 'Why is `s.str.lower()` not truly vectorised the way `s * 2` is for numbers?', NULL, NULL, 'For object dtype, it still loops over Python str objects in Python; there is no fixed-width C array of strings', 'How are strings stored in an object column?', 'An object column holds pointers to Python strings, so .str methods are a convenient Python-level loop (they handle NaN for you). The pyarrow-backed ''string[pyarrow]'' dtype can run many string ops in compiled code.', NULL, NULL, 50);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Because lower() has to sort the strings first', 0), (@q, 'B', 'It is exactly as fast as numeric operations', 0), (@q, 'C', 'Because .str methods run on the GPU', 0), (@q, 'D', 'For object dtype, it still loops over Python str objects in Python; there is no fixed-width C array of strings', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby'), 1, 'mcq', 'What does `df.groupby(''city'')[''sales''].sum()` do?', NULL, NULL, 'Splits rows by city, sums sales within each city, and returns one total per city', 'Split, apply, combine.', 'groupby splits rows into one group per city, applies sum to each group''s sales, and combines the results into a Series indexed by city.', 'split          apply         combine\nPune  5 \\\nPune  7 / ->  sum = 12  \\\nGoa   3   ->  sum =  3  +->  Goa 3, Pune 12', 'SQL: SELECT city, SUM(sales) FROM df GROUP BY city.', 51);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Splits rows by city, sums sales within each city, and returns one total per city', 1), (@q, 'B', 'Adds a running total of sales to each row', 0), (@q, 'C', 'Returns the total of all sales in the table', 0), (@q, 'D', 'Sorts the DataFrame by city and then by sales', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"city": ["Pune", "Goa", "Pune"], "sales": [5, 3, 7]})\nprint(df.groupby("city")["sales"].sum().to_dict())', 'python', '{''Goa'': 3, ''Pune'': 12}', 'Group keys come back sorted.', 'Pune 5 + 7 = 12, Goa 3. groupby sorts keys by default (sort=True), so Goa comes first.', NULL, NULL, 52);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '15', 0), (@q, 'B', '{''Pune'': 12, ''Goa'': 3}', 0), (@q, 'C', '{''Goa'': 3, ''Pune'': 12}', 1), (@q, 'D', '{''Pune'': 5, ''Goa'': 3}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"city": ["Pune", "Goa", "Pune"], "sales": [5, 3, 7]})\nr = df.groupby("city")["sales"].mean()\nprint(type(r).__name__, r.index.name)', 'python', 'Series city', 'One column selected, one value per group.', 'Selecting a single column before aggregating gives a Series, indexed by the group key, whose index name is ''city''.', NULL, NULL, 53);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'DataFrame None', 0), (@q, 'B', 'Series city', 1), (@q, 'C', 'DataFrame city', 0), (@q, 'D', 'Series None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"city": ["Pune", "Goa", "Pune"], "sales": [5, 3, 7]})\nr = df.groupby("city", as_index=False)["sales"].sum()\nprint(r.columns.tolist(), r.shape)', 'python', '[''city'', ''sales''] (2, 2)', 'as_index=False keeps the key as a normal column.', 'With as_index=False the result is a DataFrame with city as a column (like SQL output), not as the index. Same as .sum().reset_index().', NULL, NULL, 54);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''sales''] (2,)', 0), (@q, 'B', '[''city'', ''sales''] (2, 2)', 1), (@q, 'C', '[''city'', ''sales''] (3, 2)', 0), (@q, 'D', '[''sales''] (2, 1)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"city": ["Pune", "Goa", "Pune"], "sales": [5, 3, 7]})\nr = df.groupby("city")["sales"].agg(["sum", "mean", "max"])\nprint(r.loc["Pune"].tolist())', 'python', '[12.0, 6.0, 7.0]', 'A row of a DataFrame is a Series with one dtype.', 'agg with a list gives one column per function. The Pune row holds 12, 6.0 and 7; since the mean is a float, the row Series is float64.', NULL, NULL, 55);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'KeyError', 0), (@q, 'B', '[12, 6, 7]', 0), (@q, 'C', '[12.0, 6.0, 7.0]', 1), (@q, 'D', '[5, 7, 12]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"city": ["Pune", "Goa", "Pune"], "sales": [5, 3, 7], "qty": [1, 2, 3]})\nr = df.groupby("city").agg(total=("sales", "sum"), orders=("qty", "count"))\nprint(r.columns.tolist(), r.loc["Pune", "total"])', 'python', '[''total'', ''orders''] 12', 'Named aggregation: new_name=(column, function).', 'Named aggregation gives flat, readable column names (like SQL''s SUM(sales) AS total) instead of a MultiIndex.', NULL, NULL, 56);
