INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"g": ["a", "a", "b"], "v": [1, 5, 3]})\nprint(df.groupby("g")["v"].agg(lambda s: s.max() - s.min()).to_dict())', 'python', '{''a'': 4, ''b'': 0}', 'agg can take any function that reduces a Series to one value.', 'The custom function computes the range per group: a 5-1 = 4, b 3-3 = 0.', NULL, NULL, 62);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '{''a'': 5, ''b'': 3}', 0), (@q, 'C', '{''a'': 1, ''b'': 3}', 0), (@q, 'D', '{''a'': 4, ''b'': 0}', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"g": ["a", "a", "b"], "v": [1, 5, 3]})\nprint(df.groupby("g").filter(lambda grp: grp["v"].sum() > 4)["v"].tolist())', 'python', '[1, 5]', 'filter keeps or drops whole groups.', 'Group a sums to 6 (> 4) and is kept with all its rows; group b sums to 3 and is dropped.', NULL, 'SQL: HAVING SUM(v) > 4, but returning the original rows.', 63);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[3]', 0), (@q, 'B', '[6]', 0), (@q, 'C', '[1, 5, 3]', 0), (@q, 'D', '[1, 5]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby-advanced'), 2, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\ndf = pd.DataFrame({"g": ["a", "a", "b"], "v": [1, np.nan, 3]})\nprint(df.groupby("g").size().to_dict(), df.groupby("g")["v"].count().to_dict())', 'python', '{''a'': 2, ''b'': 1} {''a'': 1, ''b'': 1}', 'One counts rows, the other counts non-missing values.', 'size() counts rows in each group (COUNT(*)); count() counts non-NaN values in the column (COUNT(v)). Group a has 2 rows but only 1 non-missing v.', 'g   v       size()  count()\na   1   \\\na   NaN /    2        1\nb   3        1        1', 'SQL: COUNT(*) vs COUNT(v).', 64);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{''a'': 2, ''b'': 1} {''a'': 2, ''b'': 1}', 0), (@q, 'B', '{''a'': 2, ''b'': 1} {''a'': 1, ''b'': 1}', 1), (@q, 'C', '{''a'': 1, ''b'': 1} {''a'': 2, ''b'': 1}', 0), (@q, 'D', '{''a'': 1, ''b'': 1} {''a'': 1, ''b'': 1}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby-advanced'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"g": ["a", "a", "b"], "v": [1, 3, 5]})\nprint(df.groupby("g")["v"].transform("mean").tolist(), df.groupby("g")["v"].agg("mean").tolist())', 'python', '[2.0, 2.0, 5.0] [2.0, 5.0]', 'One returns a value per group, the other a value per original row.', 'agg reduces each group to one row (2 results). transform broadcasts the group''s result back onto every original row (3 results), aligned with df.', 'g  v     agg(''mean'')   transform(''mean'')\na  1  \\                     2.0\na  3  /  a -> 2.0           2.0\nb  5     b -> 5.0           5.0', NULL, 65);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[2.0, 2.0, 5.0] [2.0, 5.0]', 1), (@q, 'B', '[2.0, 5.0] [2.0, 2.0, 5.0]', 0), (@q, 'C', '[2.0, 2.0, 5.0] [2.0, 2.0, 5.0]', 0), (@q, 'D', '[2.0, 5.0] [2.0, 5.0]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby-advanced'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"g": ["a", "a", "b"], "v": [1, 3, 5]})\ndf["share"] = df["v"] / df.groupby("g")["v"].transform("sum")\nprint(df["share"].tolist())', 'python', '[0.25, 0.75, 1.0]', 'transform keeps the original shape, so you can divide row by row.', 'transform(''sum'') gives each row its group''s total (4, 4, 5), so share = 1/4, 3/4, 5/5. Using agg here would misalign.', NULL, NULL, 66);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[nan, nan, nan]', 0), (@q, 'B', '[0.25, 0.75, 1.0]', 1), (@q, 'C', '[0.1111111111111111, 0.3333333333333333, 0.5555555555555556]', 0), (@q, 'D', 'ValueError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby-advanced'), 3, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\ndf = pd.DataFrame({"g": ["a", "a", "b", "b"], "v": [1, np.nan, np.nan, 7]})\ndf["v"] = df["v"].fillna(df.groupby("g")["v"].transform("mean"))\nprint(df["v"].tolist())', 'python', '[1.0, 1.0, 7.0, 7.0]', 'Fill each missing value with the mean of its own group.', 'transform(''mean'') gives a per-row group mean (a: 1, b: 7), and fillna uses it aligned by index. Group-wise imputation is common for features like ''price by category''.', NULL, NULL, 67);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1.0, nan, nan, 7.0]', 0), (@q, 'B', '[1.0, 1.0, 7.0, 7.0]', 1), (@q, 'C', '[1.0, 4.0, 4.0, 7.0]', 0), (@q, 'D', '[1.0, 0.0, 0.0, 7.0]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby-advanced'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"g": ["a", "a", "b"], "v": [1, 3, 5]})\nprint(df.groupby("g")["v"].cumsum().tolist(), df.groupby("g").cumcount().tolist())', 'python', '[1, 4, 5] [0, 1, 0]', 'Cumulative functions restart in each group.', 'cumsum runs within each group (1, 1+3, then 5 for b). cumcount numbers rows within the group starting at 0.', NULL, 'SQL window functions: SUM(v) OVER (PARTITION BY g ORDER BY ...), ROW_NUMBER() - 1.', 68);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 4, 9] [0, 1, 2]', 0), (@q, 'B', '[4, 4, 5] [1, 2, 1]', 0), (@q, 'C', '[1, 4, 5] [0, 1, 0]', 1), (@q, 'D', '[1, 4, 5] [1, 2, 1]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby-advanced'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"g": ["a", "a", "b"], "v": [1, 3, 5]})\nprint(df.groupby("g")["v"].shift(1).tolist())', 'python', '[nan, 1.0, nan]', 'shift moves values down by one, but not across group borders.', 'Within group a, 3''s previous value is 1; the first row of each group has nothing before it, so NaN. This is the safe way to build ''previous value'' features (SQL LAG).', NULL, NULL, 69);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1.0, 3.0, 5.0]', 0), (@q, 'B', '[nan, 1.0, nan]', 1), (@q, 'C', '[3.0, nan, nan]', 0), (@q, 'D', '[nan, 1.0, 3.0]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby-advanced'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"g": ["a", None, "a"], "v": [1, 2, 3]})\nprint(df.groupby("g")["v"].sum().to_dict(), df.groupby("g", dropna=False)["v"].sum().sum())', 'python', '{''a'': 4} 6', 'By default rows with a missing group key are dropped.', 'groupby drops rows whose key is NaN/None (dropna=True), silently losing value 2. dropna=False keeps a NaN group, so the total is 6 again.', NULL, NULL, 70);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{''a'': 4} 6', 1), (@q, 'B', '{''a'': 6} 6', 0), (@q, 'C', '{''a'': 4} 4', 0), (@q, 'D', '{''a'': 4, None: 2} 6', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby-advanced'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"g": ["a", "a", "b"], "v": [1, 3, 5]})\nr = df.groupby("g")["v"].apply(lambda s: s - s.mean())\nprint(r.tolist())', 'python', '[-1.0, 1.0, 0.0]', 'apply can return a whole Series per group, not just one value.', 'Here each group returns a same-length Series (centred values), so apply behaves like transform. apply is the flexible but slowest option; prefer transform when the output is row-shaped.', NULL, NULL, 71);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[-1.0, 1.0]', 0), (@q, 'B', '[2.0, 5.0]', 0), (@q, 'C', '[-1.0, 1.0, 0.0]', 1), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby-advanced'), 2, 'mcq', 'Which groupby method should you use to add a column ''customer_total'' to every order row?', NULL, NULL, 'transform', 'The result must have one value per ORIGINAL row.', 'transform returns an object indexed like the original rows, so it can be assigned straight back as a column. agg returns one row per customer.', NULL, NULL, 72);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'agg', 0), (@q, 'B', 'size', 0), (@q, 'C', 'transform', 1), (@q, 'D', 'filter', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby-advanced'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"g": ["a", "a", "b", "b", "b"], "v": [5, 9, 1, 8, 4]})\ntop = df.sort_values("v", ascending=False).groupby("g").head(1)\nprint(top["v"].tolist(), df.loc[df.groupby("g")["v"].idxmax(), "v"].tolist())', 'python', '[9, 8] [9, 8]', 'Two ways to get the top row of each group.', 'Sorting then head(1) per group keeps the largest v of each group in sorted order (9 then 8). idxmax returns the index label of each group''s max, which loc then fetches.', NULL, NULL, 73);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[9, 8] [5, 1]', 0), (@q, 'B', '[9] [9, 8]', 0), (@q, 'C', '[9, 8] [9, 8]', 1), (@q, 'D', '[8, 9] [9, 8]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby-advanced'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"g": pd.Categorical(["a", "a"], categories=["a", "b"]), "v": [1, 2]})\nprint(df.groupby("g", observed=False)["v"].sum().to_dict(), df.groupby("g", observed=True)["v"].sum().to_dict())', 'python', '{''a'': 3, ''b'': 0} {''a'': 3}', 'With a categorical key, unused categories can still appear as groups.', 'observed=False includes every declared category, even empty ones (sum of nothing = 0). observed=True shows only groups that actually occur; it will become the default in a future pandas release.', NULL, NULL, 74);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{''a'': 3} {''a'': 3, ''b'': 0}', 0), (@q, 'B', '{''a'': 3, ''b'': 0} {''a'': 3}', 1), (@q, 'C', '{''a'': 3, ''b'': nan} {''a'': 3}', 0), (@q, 'D', '{''a'': 3} {''a'': 3}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby-advanced'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"g": ["a", "b"], "v": [1, 2]})\nprint(df.groupby("g")["v"].sum(min_count=1).tolist(), df[df.v > 5].groupby("g")["v"].sum().tolist())', 'python', '[1, 2] []', 'An empty frame has no groups at all.', 'Each group has one value, so min_count=1 is satisfied. After filtering out every row there are no keys left, so the result is empty, not zeros.', NULL, NULL, 75);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2] []', 1), (@q, 'B', '[1, 2] [0, 0]', 0), (@q, 'C', '[1.0, 2.0] []', 0), (@q, 'D', '[1, 2] [0]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby-advanced'), 4, 'mcq', 'Why is `df.groupby(''g'').apply(f)` often much slower than `agg`/`transform` with built-in names like ''sum''?', NULL, NULL, 'Built-in names dispatch to optimised Cython group kernels; apply calls a Python function per group and must then infer how to stitch the results', 'Strings like ''sum'' vs a Python callable.', 'String aggregations (''sum'', ''mean'', ''size'') run in one compiled pass over all groups. apply builds a sub-DataFrame per group, calls Python, then guesses whether to concat, broadcast or reduce. With millions of small groups the per-group overhead dominates.', NULL, NULL, 76);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Built-in names dispatch to optimised Cython group kernels; apply calls a Python function per group and must then infer how to stitch the results', 1), (@q, 'B', 'apply copies the DataFrame to disk', 0), (@q, 'C', 'agg runs on multiple threads by default', 0), (@q, 'D', 'apply sorts the whole DataFrame twice', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merge'), 1, 'mcq', 'Which pandas function is the closest match to a SQL JOIN?', NULL, NULL, 'pd.merge (or df.merge)', 'Combine two tables on a matching key.', 'merge matches rows on key columns, with how=''inner''/''left''/''right''/''outer'' like the SQL join types. concat just stacks tables.', NULL, NULL, 77);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'pd.merge (or df.merge)', 1), (@q, 'B', 'df.pivot', 0), (@q, 'C', 'df.groupby', 0), (@q, 'D', 'pd.concat', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merge'), 1, 'code_output', 'What does this print?', 'import pandas as pd\nusers = pd.DataFrame({"uid": [1, 2, 3], "name": ["Ann", "Bob", "Cy"]})\norders = pd.DataFrame({"uid": [1, 1, 3], "amt": [10, 20, 5]})\nprint(len(users.merge(orders, on="uid")), len(users.merge(orders, on="uid", how="left")))', 'python', '3 4', 'Inner keeps only matches; left keeps every user.', 'Inner: Ann matches 2 orders, Cy 1, Bob none -> 3 rows. Left join also keeps Bob with NaN amt -> 4 rows.', 'users  orders     inner        left\n1 Ann  1 10       Ann 10       Ann 10\n2 Bob  1 20       Ann 20       Ann 20\n3 Cy   3  5       Cy   5       Bob NaN\n                               Cy   5', NULL, 78);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '2 3', 0), (@q, 'B', '3 3', 0), (@q, 'C', '3 4', 1), (@q, 'D', '4 4', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merge'), 1, 'true_false', 'The default `how` for `pd.merge` is ''inner''.', NULL, NULL, 'True', 'Same default as a plain SQL JOIN.', 'merge defaults to an inner join: only keys present in both tables survive. Pass how=''left'' to keep every row of the left table.', NULL, NULL, 79);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merge'), 2, 'code_output', 'What does this print?', 'import pandas as pd\na = pd.DataFrame({"k": [1, 1, 2], "x": ["a", "b", "c"]})\nb = pd.DataFrame({"k": [1, 1, 3], "y": ["p", "q", "r"]})\nprint(len(a.merge(b, on="k")), len(a.merge(b, on="k", how="outer")))', 'python', '4 6', 'Duplicate keys on BOTH sides multiply: every match pairs with every match.', 'Key 1 appears twice on each side -> 2 x 2 = 4 rows. Outer adds the unmatched k=2 and k=3 rows -> 6. This is how merges ''blow up'' row counts.', 'left k=1: a, b      right k=1: p, q\n              a-p   a-q\n              b-p   b-q     -> 4 rows for one key\nduplicate keys on both sides multiply rows', NULL, 80);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '4 4', 0), (@q, 'B', '4 6', 1), (@q, 'C', '2 4', 0), (@q, 'D', '2 5', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merge'), 2, 'code_output', 'What does this print?', 'import pandas as pd\na = pd.DataFrame({"id": [1, 2], "v": [10, 20]})\nb = pd.DataFrame({"id": [1, 2], "v": [30, 40]})\nprint(a.merge(b, on="id").columns.tolist())', 'python', '[''id'', ''v_x'', ''v_y'']', 'Two non-key columns share a name.', 'Overlapping non-key columns get suffixes _x (left) and _y (right). Use suffixes=(''_old'', ''_new'') for clearer names.', NULL, NULL, 81);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''id'', ''v'']', 0), (@q, 'B', '[''id'', ''v'', ''v'']', 0), (@q, 'C', 'ValueError', 0), (@q, 'D', '[''id'', ''v_x'', ''v_y'']', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merge'), 2, 'code_output', 'What does this print?', 'import pandas as pd\na = pd.DataFrame({"user_id": [1, 2], "v": [10, 20]})\nb = pd.DataFrame({"uid": [2, 3], "w": [5, 6]})\nr = a.merge(b, left_on="user_id", right_on="uid")\nprint(r.columns.tolist(), len(r))', 'python', '[''user_id'', ''v'', ''uid'', ''w''] 1', 'Different key names on each side keep both key columns.', 'left_on/right_on join columns with different names; both columns stay in the result. Only id 2 matches.', NULL, NULL, 82);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''uid'', ''v'', ''w''] 2', 0), (@q, 'B', '[''user_id'', ''v'', ''w''] 1', 0), (@q, 'C', '[''user_id'', ''v'', ''uid'', ''w''] 1', 1), (@q, 'D', 'KeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merge'), 3, 'code_output', 'What does this print?', 'import pandas as pd\na = pd.DataFrame({"k": [1, 2]})\nb = pd.DataFrame({"k": [2, 3]})\nr = a.merge(b, on="k", how="outer", indicator=True)\nprint(r["_merge"].astype(str).tolist())', 'python', '[''left_only'', ''both'', ''right_only'']', 'indicator adds a column saying where each row came from.', 'Key 1 only exists on the left, 2 in both, 3 only on the right. indicator=True is great for auditing joins.', NULL, NULL, 83);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''both'', ''left_only'', ''right_only'']', 0), (@q, 'B', '[True, True, True]', 0), (@q, 'C', '[''left_only'', ''both'', ''right_only'']', 1), (@q, 'D', '[''left'', ''both'', ''right'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merge'), 3, 'code_output', 'What does this print?', 'import pandas as pd\na = pd.DataFrame({"k": [1, 2], "x": [1, 2]})\nb = pd.DataFrame({"k": [1, 1], "y": [3, 4]})\ntry:\n    a.merge(b, on="k", validate="one_to_one")\nexcept Exception as e:\n    print(type(e).__name__)', 'python', 'MergeError', 'validate checks your assumption about key uniqueness.', 'validate=''one_to_one'' requires unique keys on both sides; b has k=1 twice, so merge raises MergeError instead of silently duplicating rows.', NULL, NULL, 84);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(nothing is printed)', 0), (@q, 'B', 'MergeError', 1), (@q, 'C', 'ValueError', 0), (@q, 'D', 'KeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merge'), 3, 'code_output', 'What does this print?', 'import pandas as pd\na = pd.DataFrame({"k": [1, 2]})\nb = pd.DataFrame({"k": ["1", "2"]})\nprint(a.merge(b, on="k"))', 'python', 'ValueError', 'int keys vs string keys.', 'pandas refuses to merge an int64 key with an object (string) key and raises ValueError (''You are trying to merge on int64 and object columns''). Convert types first.', NULL, NULL, 85);
