INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'concat'), 1, 'code_output', 'What does this print?', 'import pandas as pd\na = pd.DataFrame({"x": [1, 2]})\nb = pd.DataFrame({"x": [3]})\nr = pd.concat([a, b])\nprint(r["x"].tolist(), r.index.tolist())', 'python', '[1, 2, 3] [0, 1, 0]', 'concat stacks rows and keeps each piece''s original index.', 'Rows are stacked a then b; the index labels are kept as they were, so 0 appears twice. Use ignore_index=True for a fresh 0..n-1.', NULL, 'SQL: UNION ALL.', 91);
