INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshape'), 1, 'mcq', 'What does `melt` do?', NULL, NULL, 'Turns wide data (one column per measurement) into long data (one row per measurement)', 'Many columns become two: variable and value.', 'melt unpivots: columns like q1, q2, q3 become rows, with a ''variable'' column holding the old column name and a ''value'' column holding the number.', NULL, NULL, 99);
