INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshape'), 2, 'code_output', 'What does this print?', 'import pandas as pd\nlong = pd.DataFrame({"day": ["mon", "mon", "tue"], "city": ["P", "G", "P"], "t": [30, 28, 31]})\nw = long.pivot(index="day", columns="city", values="t")\nprint(w.shape, w.loc["tue", "G"])', 'python', '(2, 2) nan', 'pivot spreads one column''s values into new columns.', 'pivot makes one row per day and one column per city. Tuesday has no G reading, so that cell is NaN.', NULL, NULL, 101);
