INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshape'), 3, 'code_output', 'What does this print?', 'import pandas as pd\np = pd.DataFrame({"d": ["x", "x", "y"], "c": ["m", "n", "n"], "v": [1, 2, 3]})\nt = p.pivot_table(index="d", columns="c", values="v", aggfunc="sum", fill_value=0, margins=True)\nprint(t.loc["All", "All"], t.loc["y", "m"])', 'python', '6 0', 'margins adds totals; fill_value replaces empty cells.', 'margins=True adds an ''All'' row and column with grand totals (1 + 2 + 3 = 6). The empty (y, m) cell is filled with 0.', NULL, NULL, 104);
