INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshape'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"sex": ["M", "F", "F", "M"], "smoker": ["y", "n", "y", "y"]})\nprint(pd.crosstab(df["sex"], df["smoker"]).loc["M", "y"])', 'python', '2', 'crosstab counts how often each pair of values occurs.', 'crosstab builds a frequency table: M and y occurs twice.', NULL, NULL, 105);
