INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshape'), 2, 'mcq', 'A plotting library or model needs ''long'' (tidy) data: one row per observation. You have columns jan, feb, mar of sales per store. Which call fixes it?', NULL, NULL, 'df.melt(id_vars="store", var_name="month", value_name="sales")', 'Wide -> long.', 'melt turns the month columns into (month, sales) rows; var_name/value_name set the new column names. pivot goes the other way (long -> wide).', NULL, NULL, 106);
