INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'binning'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([1, 2, 3, 4, 5, 6, 7, 100])\nprint(pd.cut(s, 4, labels=False).value_counts().sort_index().tolist())', 'python', '[7, 1]', 'Equal-width bins over 1..100: where do most values fall?', 'cut(4) makes 4 bins of width ~25. Seven values land in the first bin and one in the last; value_counts omits the two empty bins.', NULL, NULL, 113);
