INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'binning'), 4, 'mcq', 'You bin ''income'' into quartiles with `pd.qcut` on the full dataset, then split into train and test. What is wrong?', NULL, NULL, 'The quartile edges were computed using test rows, leaking test information into the features', 'Where did the edges come from?', 'Bin edges are learned statistics. Compute them on the training set (pd.qcut(train, 4, retbins=True)) and apply the same edges to the test set with pd.cut(test, bins=edges).', NULL, NULL, 116);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The quartile edges were computed using test rows, leaking test information into the features', 1), (@q, 'B', 'qcut can''t be used on income', 0), (@q, 'C', 'Nothing; binning can never leak', 0), (@q, 'D', 'Quartiles must always be computed on the test set', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'datetime'), 1, 'code_output', 'What does this print?', 'import pandas as pd\nd = pd.to_datetime(pd.Series(["2024-03-15", "2024-12-01"]))\nprint(d.dt.year.tolist(), d.dt.month.tolist(), d.dt.day_name().tolist())', 'python', '[2024, 2024] [3, 12] [''Friday'', ''Sunday'']', 'The .dt accessor exposes date parts.', '.dt.year, .dt.month and .dt.day_name() pull parts out of each date. 15 March 2024 was a Friday; 1 December 2024 was a Sunday.', NULL, NULL, 117);
