INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'datetime'), 1, 'true_false', 'You can only use `.dt.year` on a column after it has been converted to a datetime dtype.', NULL, NULL, 'True', 'A string ''2024-03-15'' has no year attribute.', 'On an object (string) column, .dt raises AttributeError (''Can only use .dt accessor with datetimelike values''). Convert with pd.to_datetime first.', NULL, NULL, 118);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'datetime'), 3, 'code_output', 'What does this print?', 'import pandas as pd\nd = pd.to_datetime(pd.Series(["2024-01-31"]))\nprint((d + pd.Timedelta(days=1)).dt.strftime("%Y-%m-%d").tolist(), (d + pd.DateOffset(months=1)).dt.strftime("%Y-%m-%d").tolist())', 'python', '[''2024-02-01''] [''2024-02-29'']', 'Timedelta is a fixed length of time; DateOffset follows calendar rules.', 'Adding 1 day gives 1 Feb. Adding one calendar month to 31 Jan clips to the last day of February 2024 (a leap year): 29 Feb.', NULL, NULL, 119);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''2024-02-01''] [''2024-03-02'']', 0), (@q, 'B', '[''2024-02-01''] [''2024-02-29'']', 1), (@q, 'C', '[''2024-02-01''] [''2024-02-31'']', 0), (@q, 'D', '[''2024-01-32''] [''2024-02-29'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'datetime'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series(range(6), index=pd.date_range("2024-01-01", periods=6, freq="D"))\nprint(s.resample("2D").sum().tolist())', 'python', '[1, 5, 9]', 'resample groups consecutive time windows, like groupby on time.', '2-day buckets: (0+1), (2+3), (4+5) = 1, 5, 9.', NULL, 'Like GROUP BY date_trunc(''day'', ts) in SQL, but for any window size.', 120);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[3, 12]', 0), (@q, 'B', '[0, 1, 2, 3, 4, 5]', 0), (@q, 'C', '[1, 5, 9]', 1), (@q, 'D', '[1, 9]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'datetime'), 2, 'code_output', 'What does this print?', 'import pandas as pd\nidx = pd.to_datetime(["2024-01-10", "2024-01-20", "2024-02-05"])\ns = pd.Series([1, 2, 3], index=idx)\nprint(s.resample("MS").sum().tolist(), s["2024-01"].tolist())', 'python', '[3, 3] [1, 2]', '''MS'' = month start buckets; a partial date string selects a whole month.', 'January totals 1 + 2 = 3, February 3. On a DatetimeIndex, s[''2024-01''] selects every row in January (partial string indexing).', NULL, NULL, 121);
