INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'datetime'), 4, 'code_output', 'What does this print?', 'import pandas as pd\na = pd.Timestamp("2024-01-01")\nb = pd.Timestamp("2024-01-01", tz="UTC")\nprint(a < b)', 'python', 'TypeError', 'Can you compare a time with no zone to a time with a zone?', 'Comparing tz-naive and tz-aware timestamps raises TypeError: pandas won''t guess what zone the naive one is in. Localise or convert everything to UTC first.', NULL, NULL, 125);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False', 0), (@q, 'B', 'TypeError', 1), (@q, 'C', 'ValueError', 0), (@q, 'D', 'True', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'datetime'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([10, 20, 30], index=pd.to_datetime(["2024-01-01", "2024-01-02", "2024-01-05"]))\nprint(s.asfreq("D").isna().sum(), s.resample("D").sum().tolist()[-2:])', 'python', '2 [0, 30]', 'asfreq inserts missing days as NaN; resample-sum of an empty bucket is...?', 'asfreq(''D'') adds rows for 3 and 4 Jan with NaN. resample(''D'').sum() also creates those days, but the sum of an empty bucket is 0, which can hide gaps in time series.', NULL, NULL, 126);
