INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"x": 0, "y": [1, 2, 3]})\nprint(df["x"].tolist())', 'python', '[0, 0, 0]', 'A scalar can be stretched to fit.', 'A scalar value in the dict is broadcast to the length of the other columns, so x becomes [0, 0, 0].', NULL, NULL, 15);
