INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inspecting'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2, 3, 4], "b": [5, 6, 7, 8], "c": [9, 10, 11, 12]})\nprint(df.shape, len(df))', 'python', '(4, 3) 4', 'shape is (rows, columns); len counts rows.', 'There are 4 rows and 3 columns, so shape is (4, 3). len(df) is the number of rows, 4. df.size would be 12.', NULL, NULL, 20);
