INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"v": [1, 2, 3]})\nmask = pd.Series([True, False, True], index=[2, 1, 0])\nprint(df[mask]["v"].tolist())', 'python', '[1, 3]', 'A boolean Series mask is matched to rows by index label, not position.', 'The mask is aligned to df''s index first: label 0 -> True, 1 -> False, 2 -> True. Rows 0 and 2 are kept in df''s order: [1, 3].', NULL, NULL, 62);
