INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([1, 2, 3])\nprint((s * 2).tolist())', 'python', '[2, 4, 6]', 'Unlike a Python list, a Series does math on every element.', 's * 2 multiplies each value (vectorised). With a plain Python list, [1, 2, 3] * 2 would repeat the list instead.', NULL, NULL, 75);
