INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series(["lo", "hi", "lo"])\nprint(s.map({"lo": 0, "hi": 1}).tolist())', 'python', '[0, 1, 0]', 'map with a dict looks up each value.', 'Series.map(dict) replaces each value with its dict value, a common way to encode labels.', NULL, NULL, 76);
