INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2]})\nr = df.apply(lambda row: [row["a"], row["a"] * 10], axis=1, result_type="expand")\nprint(r.shape, r.columns.tolist())', 'python', '(2, 2) [0, 1]', 'result_type=''expand'' turns list results into columns.', 'Each returned list is spread over new columns labelled 0 and 1, giving a 2x2 DataFrame.', NULL, NULL, 83);
