INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'index-alignment'), 4, 'code_output', 'What does this print?', 'import pandas as pd\na = pd.Series([1, 2, 3], index=["x", "x", "y"])\nb = pd.Series([10, 20], index=["x", "y"])\nprint((a + b).tolist())', 'python', '[11, 12, 23]', 'Each x on the left finds the single x on the right.', 'Alignment matches labels; both x rows in a pair with b''s x (10) and y pairs with 20. With duplicates on BOTH sides, alignment does a many-to-many match and can multiply rows.', NULL, NULL, 96);
