INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 3, 'true_false', 'In pandas 2.2, copy-on-write is turned on by default.', NULL, NULL, 'False', 'It becomes the default in a later major version.', 'In 2.2 copy-on-write is opt-in (pd.options.mode.copy_on_write = True, or ''warn''). It becomes the only behaviour in pandas 3.0.', NULL, NULL, 97);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 2, 'mcq', 'What does SettingWithCopyWarning mean?', NULL, NULL, 'You may be modifying a temporary copy, so the original DataFrame might not change', 'It''s about whether your write actually reaches the original data.', 'pandas can''t tell if the object you''re writing to is a view of the original or a copy, so it warns that your change may be lost. Fix by doing the selection and assignment in ONE .loc call, or by calling .copy() explicitly.', NULL, NULL, 98);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Your DataFrame has duplicate column names', 0), (@q, 'B', 'You made too many copies and memory is low', 0), (@q, 'C', 'You may be modifying a temporary copy, so the original DataFrame might not change', 1), (@q, 'D', 'The column you set has the wrong dtype', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2, 3], "b": [10, 20, 30]})\ndf[df["a"] > 1]["b"] = 0\nprint(df["b"].tolist())', 'python', '[10, 20, 30]', 'Two separate [] steps: the first one makes a NEW frame.', 'df[mask] creates a new DataFrame (a copy). Setting [''b''] on that temporary copy is lost; pandas emits SettingWithCopyWarning. df is unchanged.', 'df --df[mask]--> temp copy --["b"] = 0--> temp changed\n |                                          (then discarded)\n +-- unchanged\n\ndf.loc[mask, "b"] = 0  --> writes straight into df', NULL, 99);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0, 0, 0]', 0), (@q, 'B', 'KeyError', 0), (@q, 'C', '[10, 20, 30]', 1), (@q, 'D', '[10, 0, 0]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2, 3], "b": [10, 20, 30]})\ndf.loc[df["a"] > 1, "b"] = 0\nprint(df["b"].tolist())', 'python', '[10, 0, 0]', 'One .loc call with both the row filter and the column.', 'loc[row_mask, column] = value writes directly into df, with no intermediate copy. This is the fix for SettingWithCopyWarning.', NULL, 'SQL: UPDATE df SET b = 0 WHERE a > 1, one statement.', 100);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[10, 20, 0]', 0), (@q, 'B', '[10, 20, 30]', 0), (@q, 'C', '[10, 0, 0]', 1), (@q, 'D', '[0, 0, 0]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 1, 'fill_blank', 'To get an independent DataFrame that you can change without touching the original, call `sub = df[df.a > 1].____()`.', NULL, NULL, 'copy', 'Make it explicit.', '.copy() returns a deep copy by default. Changing sub afterwards can never affect df, and no SettingWithCopyWarning is raised.', NULL, NULL, 101);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2, 3]})\ns = df["a"]\ns[0] = 100\nprint(df["a"].tolist())', 'python', '[100, 2, 3]', 'In pandas 2.2 without copy-on-write, df[''a''] can share memory with df.', 'With copy-on-write off (the 2.2 default), the column Series is a view of df''s data, so writing to it changes df. With copy-on-write on, df would stay [1, 2, 3].', NULL, NULL, 102);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[100, 100, 100]', 0), (@q, 'B', '[1, 2, 3]', 0), (@q, 'C', '[100, 2, 3]', 1), (@q, 'D', 'KeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 3, 'code_output', 'What does this print?', 'import pandas as pd\nwith pd.option_context("mode.copy_on_write", True):\n    df = pd.DataFrame({"a": [1, 2, 3]})\n    s = df["a"]\n    s[0] = 100\n    print(df["a"].tolist(), s.tolist())', 'python', '[1, 2, 3] [100, 2, 3]', 'Under copy-on-write, every derived object behaves like a copy.', 'With copy-on-write, s shares memory only until it is written to; the write triggers a real copy, so df is protected. Behaviour is predictable: only the object you modify changes.', 's = df["a"]      df --\\\n                      +--> [1, 2, 3]   (shared)\n                 s ---/\ns[0] = 100       df --> [1, 2, 3]\n                 s  --> [100, 2, 3]  (copied on write)', NULL, 103);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2, 3] [100, 2, 3]', 1), (@q, 'B', '[100, 2, 3] [100, 2, 3]', 0), (@q, 'C', 'ValueError', 0), (@q, 'D', '[1, 2, 3] [1, 2, 3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2, 3]})\ndf["a"][0] = 99\nprint(df["a"].tolist())', 'python', '[99, 2, 3]', 'In 2.2 with default settings, df[''a''] is a cached view of the column.', 'Chained assignment through a column still writes through in pandas 2.2 (with a FutureWarning saying it will stop working). Under copy-on-write / pandas 3.0 it never updates df. Use df.loc[0, ''a''] = 99.', NULL, NULL, 104);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[99, 2, 3]', 1), (@q, 'B', 'KeyError', 0), (@q, 'C', 'ValueError', 0), (@q, 'D', '[1, 2, 3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 4, 'code_output', 'What does this print?', 'import pandas as pd\nwith pd.option_context("mode.copy_on_write", True):\n    df = pd.DataFrame({"a": [1, 2, 3]})\n    df["a"][0] = 99\n    print(df["a"].tolist())', 'python', '[1, 2, 3]', 'Under copy-on-write, df[''a''] is always a new object as far as writes are concerned.', 'With copy-on-write, chained assignment never reaches df; pandas only emits a ChainedAssignmentError *warning*, so the code runs and df is unchanged. This is how pandas 3.0 behaves.', NULL, NULL, 105);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[99, 2, 3]', 0), (@q, 'B', 'ChainedAssignmentError', 0), (@q, 'C', '[1, 2, 3]', 1), (@q, 'D', 'KeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2, 3], "b": [4, 5, 6]})\nsub = df[["a"]]\nsub.loc[0, "a"] = 100\nprint(df["a"].tolist())', 'python', '[1, 2, 3]', 'Selecting columns with a list builds a new frame.', 'df[[''a'']] (list indexing) always returns a copy, so changing sub never affects df; pandas still warns because it cannot be sure. Under copy-on-write the warning disappears and the result is the same.', NULL, NULL, 106);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[100, 2, 3]', 0), (@q, 'B', '[100, 100, 100]', 0), (@q, 'C', '[1, 2, 3]', 1), (@q, 'D', 'KeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 3, 'mcq', 'A teammate''s function does `def clean(df): df[''x''] = df[''x''].fillna(0); return df`. What''s the design risk?', NULL, NULL, 'It mutates the caller''s DataFrame as a side effect', 'DataFrames are passed by reference, like objects in JS or Java.', 'The function receives a reference to the same object, so assigning a column modifies the caller''s frame too. Start with df = df.copy() (or use assign) to keep functions pure.', NULL, 'Same as mutating an object argument in a JS function: the caller sees the change.', 107);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It returns a copy, so the changes are lost', 0), (@q, 'B', 'fillna cannot be used inside a function', 0), (@q, 'C', 'It raises SettingWithCopyWarning every time', 0), (@q, 'D', 'It mutates the caller''s DataFrame as a side effect', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 4, 'mcq', 'Under pandas copy-on-write, why can `df2 = df.reset_index(drop=True)` be cheap even for a huge df?', NULL, NULL, 'The new object shares the underlying data until one of them is written to', 'Copying is deferred until it is actually needed.', 'Copy-on-write lets methods return new objects that share memory with the original; a real copy happens only when one side is modified. You get copy semantics at near-view cost.', NULL, 'Like fork() in Unix or immutable data structures: pages are shared until someone writes.', 108);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The new object shares the underlying data until one of them is written to', 1), (@q, 'B', 'It deletes df''s data and moves it into df2', 0), (@q, 'C', 'reset_index is always done lazily on disk', 0), (@q, 'D', 'copy-on-write skips creating df2 entirely', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 4, 'true_false', '`df.copy()` with the default `deep=True` also deep-copies Python objects stored inside object-dtype cells (e.g. lists in a cell).', NULL, NULL, 'False', 'The ''deep'' refers to the data arrays, not to Python objects within them.', 'deep=True copies the arrays, but for object dtype it copies the references, not the Python objects themselves. Mutating a list stored in a cell affects both copies. Use copy.deepcopy if you truly need it.', NULL, NULL, 109);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([1, None, 3])\nprint(s.dtype)', 'python', 'float64', 'NumPy integer arrays cannot store a missing value.', 'None becomes NaN, and NaN is a float, so pandas upcasts the whole column to float64. The ints are now 1.0 and 3.0.', NULL, NULL, 110);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'int64', 0), (@q, 'B', 'Int64', 0), (@q, 'C', 'object', 0), (@q, 'D', 'float64', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([1, None, 3], dtype="Int64")\nprint(s.dtype, s.tolist())', 'python', 'Int64 [1, <NA>, 3]', 'Capital-I Int64 is pandas'' nullable integer type.', 'Int64 (capital I) stores integers plus a mask of missing values, shown as <NA>. The ints stay ints.', NULL, NULL, 111);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'float64 [1.0, nan, 3.0]', 0), (@q, 'B', 'TypeError', 0), (@q, 'C', 'Int64 [1, <NA>, 3]', 1), (@q, 'D', 'int64 [1, nan, 3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 1, 'mcq', 'What dtype does pandas 2.2 give a column of Python strings by default?', NULL, NULL, 'object', 'The dedicated text type exists but isn''t the default yet.', 'Strings default to object dtype (an array of pointers to Python str objects). The ''string'' dtype exists and must be requested with dtype=''string'' or astype(''string'').', NULL, NULL, 112);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'object', 1), (@q, 'B', 'string', 0), (@q, 'C', 'category', 0), (@q, 'D', 'str', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series(["1", "2", "3"])\nprint(s.astype(int).sum(), s.sum())', 'python', '6 123', 'Adding strings joins them.', 'astype(int) converts text to numbers, so the sum is 6. Summing the object column concatenates the strings: ''123''.', NULL, NULL, 113);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '123 123', 0), (@q, 'B', '6 123', 1), (@q, 'C', '6 6', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2], "b": [1.5, 2.5], "c": ["x", "y"], "d": [True, False]})\nprint(df.dtypes.astype(str).tolist())', 'python', '[''int64'', ''float64'', ''object'', ''bool'']', 'Default NumPy-backed dtypes for each Python type.', 'ints -> int64, floats -> float64, str -> object, bools -> bool.', NULL, NULL, 114);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''int'', ''float'', ''str'', ''bool'']', 0), (@q, 'B', '[''int64'', ''float64'', ''object'', ''object'']', 0), (@q, 'C', '[''int64'', ''float64'', ''string'', ''bool'']', 0), (@q, 'D', '[''int64'', ''float64'', ''object'', ''bool'']', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 2, 'true_false', 'Converting a column with few distinct values (e.g. ''lo''/''hi'' over a million rows) to `category` usually saves a lot of memory.', NULL, NULL, 'True', 'Store each distinct string once.', 'category stores the unique values once plus a small integer code per row, instead of a Python string object per row.', 'object column           category column\n"lo" -> str obj         categories: ["hi", "lo"]\n"hi" -> str obj         codes (int8): 1 0 1 1 ...\n"lo" -> str obj\n...  one object per row  one byte per row', 'Like normalising a table: a lookup table of values plus a foreign-key integer column.', 115);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series(["lo", "hi", "lo", "lo"] * 1000)\nc = s.astype("category")\nprint(c.cat.categories.tolist(), c.cat.codes.dtype, c.memory_usage(deep=True) < s.memory_usage(deep=True) / 10)', 'python', '[''hi'', ''lo''] int8 True', 'Categories are sorted; with 2 categories the codes need only 1 byte.', 'Categories are stored sorted (hi, lo); the codes use the smallest integer type that fits (int8). Memory drops by over 10x.', NULL, NULL, 116);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''hi'', ''lo''] int64 True', 0), (@q, 'B', '[''hi'', ''lo''] int8 False', 0), (@q, 'C', '[''hi'', ''lo''] int8 True', 1), (@q, 'D', '[''lo'', ''hi''] int8 True', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 3, 'mcq', 'Why does `df.memory_usage()` report much less than `df.memory_usage(deep=True)` for a text column?', NULL, NULL, 'Without deep, object columns count only the 8-byte pointers, not the Python strings they point to', 'An object column is an array of references.', 'An object array stores pointers (8 bytes each). Only deep=True follows the pointers and adds the size of each Python str object, which is the real cost.', NULL, NULL, 117);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'deep=True also counts the memory of the index twice', 0), (@q, 'B', 'Without deep, object columns count only the 8-byte pointers, not the Python strings they point to', 1), (@q, 'C', 'deep=True includes the memory of the CSV file it came from', 0), (@q, 'D', 'Without deep, pandas compresses the strings first', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([1, 2, 300])\nprint(s.astype("int8").tolist())', 'python', '[1, 2, 44]', 'int8 holds -128..127, and astype doesn''t check range.', 'astype(''int8'') wraps around silently on overflow: 300 - 256 = 44. pd.to_numeric(s, downcast=''integer'') picks a safe size instead.', NULL, NULL, 118);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2, 44]', 1), (@q, 'B', '[1, 2, 127]', 0), (@q, 'C', 'OverflowError', 0), (@q, 'D', '[1, 2, 300]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series(["a", None], dtype="string")\no = pd.Series(["a", None])\nprint(s.isna().tolist(), repr(s[1]), repr(o[1]))', 'python', '[False, True] <NA> None', 'The string dtype uses pandas'' own missing marker.', 'The ''string'' dtype stores missing as pd.NA (printed <NA>). An object Series keeps the actual None object, though isna() treats both as missing.', NULL, NULL, 119);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[False, False] None None', 0), (@q, 'B', '[False, True] <NA> nan', 0), (@q, 'C', '[False, True] <NA> None', 1), (@q, 'D', '[False, True] nan None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([1, None], dtype="Int64")\nprint(s[1] == 1, s.sum())', 'python', '<NA> 1', 'pd.NA propagates through comparisons (three-valued logic, like SQL NULL).', 'pd.NA == 1 is pd.NA, not False, mirroring SQL where NULL = 1 is NULL. Aggregations skip NA, so the sum is 1 and stays an integer.', NULL, NULL, 120);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False 1.0', 0), (@q, 'B', 'False 1', 0), (@q, 'C', '<NA> 1', 1), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([1, None], dtype="Int64")\nif s[1] == 1:\n    print("yes")', 'python', 'TypeError', 'What is bool(pd.NA)?', 's[1] == 1 is pd.NA, and pd.NA refuses to be converted to True/False: TypeError (''boolean value of NA is ambiguous''). Check with pd.isna() first.', NULL, NULL, 121);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 1), (@q, 'B', 'ValueError', 0), (@q, 'C', 'yes', 0), (@q, 'D', '', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([True, False, None])\nprint(s.dtype, s.astype("boolean").sum())', 'python', 'object 1', 'A NumPy bool array has no slot for missing.', 'With a None present, the column can''t be bool, so it falls back to object. The nullable ''boolean'' dtype holds True/False/<NA>; its sum skips NA and counts 1 True.', NULL, NULL, 122);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'bool 1', 0), (@q, 'B', 'object TypeError', 0), (@q, 'C', 'object 1', 1), (@q, 'D', 'boolean 1', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 3, 'mcq', 'What is a MultiIndex?', NULL, NULL, 'An index with more than one level, so each row label is a tuple like (''Pune'', 2024)', 'Think of a composite key.', 'A MultiIndex (hierarchical index) has several levels; each label is a tuple. groupby on several columns and pivot results often produce one.', NULL, 'A composite primary key (city, year) in SQL.', 123);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'An index that allows duplicate labels', 0), (@q, 'B', 'Several DataFrames stored inside one', 0), (@q, 'C', 'An index with more than one level, so each row label is a tuple like (''Pune'', 2024)', 1), (@q, 'D', 'An index of multiple dtypes at once', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"city": ["Pune", "Pune", "Goa"], "year": [2023, 2024, 2024], "sales": [5, 7, 3]})\nm = df.set_index(["city", "year"])\nprint(m.loc[("Pune", 2024), "sales"], m.index.nlevels)', 'python', '7 2', 'Each row label is now a (city, year) tuple.', 'set_index with two columns builds a 2-level MultiIndex; loc[(''Pune'', 2024)] selects that exact row.', '         level 0  level 1\nindex:   (Pune,   2023)  -> sales 5\n         (Pune,   2024)  -> sales 7\n         (Goa,    2024)  -> sales 3', NULL, 124);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '7 2', 1), (@q, 'B', 'KeyError', 0), (@q, 'C', '7 1', 0), (@q, 'D', '5 2', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"city": ["Pune", "Pune", "Goa"], "year": [2023, 2024, 2024], "sales": [5, 7, 3]})\nm = df.set_index(["city", "year"])\nprint(m.loc["Pune"]["sales"].tolist(), m.loc["Pune"].index.tolist())', 'python', '[5, 7] [2023, 2024]', 'Selecting by the first level only drops that level.', 'loc[''Pune''] returns all rows for Pune, and the city level is dropped, leaving year as the index.', NULL, NULL, 125);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'KeyError', 0), (@q, 'B', '[5] [2023]', 0), (@q, 'C', '[5, 7] [2023, 2024]', 1), (@q, 'D', '[5, 7] [(''Pune'', 2023), (''Pune'', 2024)]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"city": ["Pune", "Pune", "Goa"], "year": [2023, 2024, 2024], "sales": [5, 7, 3]})\ns = df.set_index(["city", "year"])["sales"]\nprint(s.xs(2024, level="year").to_dict())', 'python', '{''Pune'': 7, ''Goa'': 3}', 'xs takes a cross-section on an inner level.', 'xs(2024, level=''year'') picks every row whose year is 2024 and drops the year level, keeping the original row order.', NULL, NULL, 126);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'KeyError', 0), (@q, 'B', '{''Pune'': 7, ''Goa'': 3}', 1), (@q, 'C', '{(''Pune'', 2024): 7, (''Goa'', 2024): 3}', 0), (@q, 'D', '{''Goa'': 3, ''Pune'': 7}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"city": ["Pune", "Pune", "Goa"], "year": [2023, 2024, 2024], "sales": [5, 7, 3]})\nw = df.set_index(["city", "year"])["sales"].unstack()\nprint(w.shape, w.columns.tolist(), w.isna().sum().sum())', 'python', '(2, 2) [2023, 2024] 1', 'unstack moves the innermost index level into the columns.', 'unstack pivots year into columns: rows Goa and Pune, columns 2023 and 2024. Goa has no 2023 row, so one cell is NaN.', '(city, year) sales        year  2023  2024\n(Pune, 2023)   5    ->   city\n(Pune, 2024)   7         Goa    NaN   3.0\n(Goa,  2024)   3         Pune   5.0   7.0', NULL, 127);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(2, 2) [''Goa'', ''Pune''] 1', 0), (@q, 'B', '(2, 2) [2023, 2024] 0', 0), (@q, 'C', '(2, 2) [2023, 2024] 1', 1), (@q, 'D', '(3, 1) [2024] 0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"g": ["a", "a", "b"], "v": [1, 2, 3]})\nr = df.groupby("g").agg(["sum", "max"])\nprint(r.columns.tolist())', 'python', '[(''v'', ''sum''), (''v'', ''max'')]', 'Several aggregations per column produce two levels of column labels.', 'agg with a list gives MultiIndex COLUMNS: (column, function). Flatten with [''_''.join(c) for c in r.columns] or use named aggregation.', NULL, NULL, 128);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''v'', ''sum'', ''max'']', 0), (@q, 'B', '[''v_sum'', ''v_max'']', 0), (@q, 'C', '[(''v'', ''sum''), (''v'', ''max'')]', 1), (@q, 'D', '[''sum'', ''max'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 4, 'true_false', 'Slicing a MultiIndex with `loc` by ranges (e.g. `m.loc[''A'':''C'']`) works reliably only when the index is lexsorted (call `sort_index()` first).', NULL, NULL, 'True', 'Range lookups need sorted keys.', 'On an unsorted MultiIndex, range slicing can raise UnsortedIndexError or be slow. sort_index() makes slicing work and lookups fast (binary search).', NULL, NULL, 129);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'index-alignment'), 2, 'mcq', 'In SQL terms, what does a DataFrame''s index most resemble?', NULL, NULL, 'A row key used to look up and align rows (like a primary key, though it may repeat)', 'It''s what loc looks things up by.', 'The index labels the rows: loc uses it for lookups and arithmetic aligns on it. Unlike a primary key, pandas allows duplicate labels.', NULL, NULL, 130);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A database index that only speeds up queries and is never visible', 0), (@q, 'B', 'An auto-increment column that can''t be changed', 0), (@q, 'C', 'A row key used to look up and align rows (like a primary key, though it may repeat)', 1), (@q, 'D', 'The list of column names', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 2, 'true_false', '`df.loc[:, ''a'':''c'']` and `df.iloc[:, 0:3]` select the same columns when the columns are a, b, c, d.', NULL, NULL, 'True', 'loc includes the end label; iloc excludes the end position.', 'loc ''a'':''c'' gives a, b, c. iloc 0:3 gives positions 0, 1, 2, which are also a, b, c.', NULL, NULL, 131);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 1, 'mcq', 'You have a DataFrame `df` indexed by user_id. Which gives the row for user_id 42?', NULL, NULL, 'df.loc[42]', 'user_id is a label, not a position.', 'loc[42] looks up the label 42. iloc[42] would be the 43rd row, whatever its id. df[42] looks for a COLUMN named 42.', NULL, NULL, 132);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df[42]', 0), (@q, 'B', 'df.get_row(42)', 0), (@q, 'C', 'df.loc[42]', 1), (@q, 'D', 'df.iloc[42]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 1, 'fill_blank', 'To keep only rows where column `city` is in a list, write `df[df[''city''].____([''Pune'', ''Goa''])]`.', NULL, NULL, 'isin', 'SQL''s IN.', 'Series.isin(values) returns a boolean mask that is True where the value is in the list.', NULL, NULL, 133);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 2, 'mcq', 'Which is the readable equivalent of `df[(df[''age''] > 30) & (df[''city''] == ''Pune'')]`?', NULL, NULL, 'df.query("age > 30 and city == ''Pune''")', 'One method takes a whole boolean expression as a string.', 'query() evaluates a string expression against the columns. df.filter selects columns/rows by LABEL name, not by value, and df.where keeps the shape and puts NaN where the condition is False.', NULL, NULL, 134);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df.query("age > 30 and city == ''Pune''")', 1), (@q, 'B', 'df.filter("age > 30 and city == ''Pune''")', 0), (@q, 'C', 'df.where("age > 30 and city == ''Pune''")', 0), (@q, 'D', 'df.select("age > 30 & city == Pune")', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"v": [1, 5, 3]})\nprint(df.where(df["v"] > 2)["v"].tolist())', 'python', '[nan, 5.0, 3.0]', 'where keeps the shape and blanks out the rest.', 'df.where(cond) returns the same shape, with NaN where cond is False (so ints become float). Filtering with df[cond] drops rows instead.', NULL, NULL, 135);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[nan, 5.0, 3.0]', 1), (@q, 'B', '[1, 5, 3]', 0), (@q, 'C', '[5, 3]', 0), (@q, 'D', '[False, True, True]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'selecting'), 3, 'true_false', '`df.filter(like=''price'')` keeps the rows whose price column matches a condition.', NULL, NULL, 'False', 'filter is about labels, not values.', 'DataFrame.filter selects columns (or rows) whose LABELS match items/like/regex, e.g. every column with ''price'' in its name. Value filtering is df[mask] or query().', NULL, NULL, 136);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'modifying'), 2, 'mcq', 'You want to rename every column to lower case. Which works?', NULL, NULL, 'df.columns = df.columns.str.lower()', 'df.columns is an Index, and it has a .str accessor.', 'Assigning a new Index to df.columns renames everything. df.rename(columns=str.lower) also works; df.rename(str.lower) would rename the row labels.', NULL, NULL, 137);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df.columns = df.columns.str.lower()', 1), (@q, 'B', 'df.columns.lower()', 0), (@q, 'C', 'df.rename(str.lower)', 0), (@q, 'D', 'df.lower(columns=True)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'modifying'), 2, 'fill_blank', 'To sort a DataFrame by its row labels rather than by a column, call `df.____()`.', NULL, NULL, 'sort_index', 'Sorting by the index.', 'sort_index() orders rows by the index labels; sort_values(col) orders by a column''s values.', NULL, NULL, 138);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'modifying'), 1, 'true_false', '`df.sort_values(''a'')` sorts df itself and returns None.', NULL, NULL, 'False', 'Which methods return a new object by default?', 'sort_values returns a new sorted DataFrame and leaves df as it was. Only inplace=True mutates df (and then returns None).', NULL, NULL, 139);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 2, 'mcq', 'Which statement about `Series.map` vs `Series.apply` is true?', NULL, NULL, 'map accepts a dict or Series as a lookup table; apply takes a function', 'Think about what you can pass as the argument.', 'map(dict) does a lookup (missing keys -> NaN); both map and apply also accept a function, which runs in Python per element. Neither mutates the Series.', NULL, NULL, 140);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'map is always vectorised C code; apply is always Python', 0), (@q, 'B', 'map accepts a dict or Series as a lookup table; apply takes a function', 1), (@q, 'C', 'map changes the Series in place', 0), (@q, 'D', 'apply works only on DataFrames', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 3, 'mcq', 'A senior reviewer says ''never use iterrows to compute a new column''. What is the best reason?', NULL, NULL, 'It is a Python loop that builds a Series per row, and it also upcasts mixed row dtypes', 'Two problems: speed and dtypes.', 'iterrows yields (index, Series) pairs: one Python object per row, which is slow, and each row Series has a single dtype, so ints can become floats. Use vectorised ops, or itertuples if you truly must loop.', NULL, NULL, 141);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It only works on numeric columns', 0), (@q, 'B', 'It is a Python loop that builds a Series per row, and it also upcasts mixed row dtypes', 1), (@q, 'C', 'It modifies the DataFrame while iterating', 0), (@q, 'D', 'It skips the first row', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inspecting'), 1, 'true_false', '`df[''a''].mean()` skips NaN values by default.', NULL, NULL, 'True', 'Look for the skipna parameter.', 'Reductions like mean, sum, max use skipna=True by default. NumPy''s np.mean on an array with NaN returns nan instead.', NULL, NULL, 142);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 4, 'mcq', 'What does `pd.options.mode.copy_on_write = ''warn''` do in pandas 2.2?', NULL, NULL, 'Keeps the old behaviour but warns wherever the result would change under copy-on-write', 'It''s a migration aid for pandas 3.0.', '''warn'' mode runs with today''s semantics but warns at every spot whose behaviour would change once copy-on-write is the default, so you can fix code before upgrading.', NULL, NULL, 143);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Copies every DataFrame on creation', 0), (@q, 'B', 'Disables SettingWithCopyWarning permanently', 0), (@q, 'C', 'Turns copy-on-write on and raises an error on chained assignment', 0), (@q, 'D', 'Keeps the old behaviour but warns wherever the result would change under copy-on-write', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 2, 'mcq', 'Under copy-on-write, which line is the correct way to set `b` to 0 for rows where `a > 1`?', NULL, NULL, 'df.loc[df["a"] > 1, "b"] = 0', 'One indexing operation, not two.', 'Only a single __setitem__ on df itself (via loc) modifies df. The other three are chained assignment: under copy-on-write they never update df.', NULL, NULL, 144);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df.loc[df["a"] > 1, "b"] = 0', 1), (@q, 'B', 'df[df["a"] > 1]["b"] = 0', 0), (@q, 'C', 'df["b"][df["a"] > 1] = 0', 0), (@q, 'D', 'df.b[df.a > 1] = 0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 3, 'mcq', 'A column of 10 million user_id strings with ~10 million distinct values is using lots of memory. Is `category` a good fit?', NULL, NULL, 'No: with almost all values unique, category stores every value anyway plus codes, so it saves little or nothing', 'When does category help?', 'category wins when the number of distinct values is small relative to rows. With near-unique values, the categories array is as big as the original plus a code array. Consider the ''string[pyarrow]'' dtype or an integer key instead.', NULL, NULL, 145);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'No: category can''t store strings', 0), (@q, 'B', 'Yes: category always halves memory', 0), (@q, 'C', 'No: with almost all values unique, category stores every value anyway plus codes, so it saves little or nothing', 1), (@q, 'D', 'Yes: category compresses strings with gzip', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 2, 'fill_blank', 'The nullable integer dtype that can hold missing values without becoming float is written `"____"` (capital letter matters).', NULL, NULL, 'Int64', 'Capital I.', '''Int64'' (capital I) is the pandas extension dtype with a mask; ''int64'' is the NumPy dtype that can''t hold NaN.', NULL, NULL, 146);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inspecting'), 1, 'true_false', 'In pandas, `df.shape` is a method, so you call it as `df.shape()`.', NULL, NULL, 'False', 'Is it an attribute or a function?', 'shape is an attribute holding a tuple (rows, cols). df.shape() raises TypeError: ''tuple'' object is not callable.', NULL, NULL, 147);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 3, 'mcq', 'What does `df.set_index([''city'', ''year''])` produce?', NULL, NULL, 'A DataFrame whose index is a 2-level MultiIndex of (city, year) tuples', 'A list of keys builds a composite key.', 'Passing a list to set_index creates a MultiIndex; each row label becomes a (city, year) tuple and both columns leave the data.', NULL, NULL, 148);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'An error, because set_index takes one column', 0), (@q, 'B', 'Two separate DataFrames, one per column', 0), (@q, 'C', 'A DataFrame with an index named ''city_year''', 0), (@q, 'D', 'A DataFrame whose index is a 2-level MultiIndex of (city, year) tuples', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 3, 'mcq', 'You have a MultiIndex DataFrame and want plain columns again (e.g. before saving to CSV or feeding scikit-learn). What do you call?', NULL, NULL, 'reset_index()', 'Undo set_index.', 'reset_index() moves every index level back into ordinary columns and gives a fresh 0..n-1 RangeIndex.', NULL, NULL, 149);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'drop_index()', 0), (@q, 'B', 'unstack()', 0), (@q, 'C', 'reset_index()', 1), (@q, 'D', 'flatten()', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 4, 'mcq', 'Why does pandas insist that `bool(series)` raises instead of returning True/False?', NULL, NULL, 'It''s ambiguous: should it mean ''any element is True'', ''all are True'' or ''not empty''?', 'There are several reasonable meanings.', 'Unlike a list (truthy if non-empty), a Series could reasonably mean .any(), .all() or not .empty, so pandas refuses to guess. That is why `and`, `or` and `if series:` raise ValueError.', NULL, NULL, 150);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It''s ambiguous: should it mean ''any element is True'', ''all are True'' or ''not empty''?', 1), (@q, 'B', 'Because Series can contain strings', 0), (@q, 'C', 'Series objects are always truthy, so it would be useless', 0), (@q, 'D', 'For performance: computing truthiness is too slow', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 3, 'mcq', 'A pipeline does `X = df.drop(columns=''target'')` then `X[''age''] = X[''age''].fillna(0)`. Does this change `df`?', NULL, NULL, 'No: drop returns a new DataFrame, so writing to X doesn''t touch df', 'drop builds a new object.', 'drop returns a new frame that owns its data (or, under copy-on-write, shares it until written). Either way, assigning a column on X leaves df unchanged.', NULL, NULL, 151);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Yes, but only the age column', 0), (@q, 'B', 'No: drop returns a new DataFrame, so writing to X doesn''t touch df', 1), (@q, 'C', 'Yes: X is a view of df', 0), (@q, 'D', 'It raises SettingWithCopyWarning and changes df', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2, 3]})\ntop = df.iloc[:2]\ntop.iloc[0, 0] = 100\nprint(df["a"].tolist())', 'python', '[100, 2, 3]', 'Copy-on-write is off by default in pandas 2.2. Is a positional slice a view?', 'A basic iloc slice of a single-dtype frame is a NumPy view, so without copy-on-write writing into `top` writes into df''s memory too. People guess [1, 2, 3] because they think every selection copies. It''s the same aliasing bug as two variables pointing at one mutable list. In a real pipeline, ''preview'' code like this can quietly corrupt the source frame. Call .copy() when you mean a separate frame.', 'df   ->  [ 1 | 2 | 3 ]   one buffer\ntop  ->  [ 1 | 2 ]       same memory (view)\ntop.iloc[0,0] = 100  ->  df sees 100 too', 'Two JavaScript variables holding the same array: push through one and the other sees it.', 152);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[100, 2, 3]', 1), (@q, 'B', '[1, 2, 3]', 0), (@q, 'C', '[100, 100, 3]', 0), (@q, 'D', 'SettingWithCopyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 3, 'true_false', 'With copy-on-write turned on, `top = df.iloc[:2]` followed by `top.iloc[0, 0] = 100` also changes `df`.', NULL, NULL, 'False', 'Under copy-on-write, which object does a write affect?', 'Copy-on-write keeps the slice as a lazy view and copies the shared block the moment you write to `top`. So `top` becomes [100, 2] and df stays [1, 2, 3]. The rule is ''only the object you modify changes'', and pandas 3.0 makes this the default. Code that relied on writing through a slice to edit the parent will silently stop doing so after the upgrade.', NULL, NULL, 153);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 4, 'code_output', 'What does this print?', 'import pandas as pd\nwith pd.option_context("mode.copy_on_write", True):\n    df = pd.DataFrame({"a": [1, 2, 3]})\n    arr = df["a"].to_numpy()\n    arr[0] = 5\n    print(df["a"].tolist())', 'python', 'ValueError', 'Under copy-on-write, pandas can''t let you write into its buffer behind its back.', 'With copy-on-write, to_numpy() returns a zero-copy view of the column, and pandas marks it read-only. Otherwise you could change df through the array without pandas knowing, which breaks the CoW promise. NumPy raises ValueError: assignment destination is read-only. Use to_numpy(copy=True) (or np.array(...)) when an algorithm needs to mutate the array, e.g. an in-place shuffle before training.', NULL, NULL, 154);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[5, 2, 3]', 0), (@q, 'B', 'ValueError', 1), (@q, 'C', 'ChainedAssignmentError', 0), (@q, 'D', '[1, 2, 3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2], "b": [3, 4]})\nv = df.values\nv[0, 0] = 99\nm = pd.DataFrame({"a": [1, 2], "b": ["x", "y"]})\nw = m.values\nw[0, 0] = 99\nprint(df.loc[0, "a"], m.loc[0, "a"])', 'python', '99 1', 'One frame has a single dtype block; the other has to build an object array.', 'With copy-on-write off (the 2.2 default), `.values` on an all-int64 frame can return a view of the single 2-D block, so the write reaches df. The mixed int/str frame has no single block to view, so pandas builds a fresh object array and the write goes nowhere. Whether you get a view depends on the dtypes, not the method name. That''s why ''modify the result of .values'' is never a safe way to edit a DataFrame.', NULL, NULL, 155);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1 1', 0), (@q, 'B', '1 99', 0), (@q, 'C', '99 1', 1), (@q, 'D', '99 99', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 3, 'mcq', 'Under copy-on-write, what happens here?\n\n`sub = df[df[''a''] > 1]` then `sub[''a''] = 0`', NULL, NULL, 'sub''s column becomes 0, df is unchanged, and no warning is raised', 'There is only one assignment, and it targets sub.', 'With copy-on-write, `sub` behaves as its own object, so writing to it changes only `sub`. The old SettingWithCopyWarning ("is this a view or a copy?") goes away because the answer is always ''a copy, as far as you can tell''. The tempting answer is the warning, but that''s pre-CoW behaviour. In practice this removes the need for defensive .copy() calls after filtering, while df[mask][''a''] = 0 (chained) still never updates df.', NULL, NULL, 156);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Both sub and df change, because sub is a view', 0), (@q, 'B', 'SettingWithCopyWarning is raised and df may or may not change', 0), (@q, 'C', 'ChainedAssignmentError is raised and nothing changes', 0), (@q, 'D', 'sub''s column becomes 0, df is unchanged, and no warning is raised', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 4, 'mcq', 'This line works in pandas 2.2 with default settings and fills df[''a'']. What happens with copy-on-write on (the pandas 3.0 default)?', 'import pandas as pd\nimport numpy as np\ndf = pd.DataFrame({"a": [1.0, np.nan]})\ndf["a"].fillna(0, inplace=True)', 'python', 'df is unchanged: the inplace call fills a temporary Series; write df[''a''] = df[''a''].fillna(0) instead', '`df[''a'']` is a selection. What does copy-on-write say about modifying a selection?', '`df[''a''].fillna(0, inplace=True)` is chained assignment in disguise: the first step selects a column and the second mutates that object. Without CoW the column Series happens to share memory with df, so the fill shows up. With CoW the Series is its own object, so df keeps its NaN. pandas 2.2 already warns (FutureWarning) about this pattern. This is one of the most common silent breakages when upgrading notebooks to pandas 3, so search your code for `inplace=True` on column selections.', NULL, NULL, 157);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df is unchanged: the inplace call fills a temporary Series; write df[''a''] = df[''a''].fillna(0) instead', 1), (@q, 'B', 'It still fills df[''a''], because inplace=True always edits the parent', 0), (@q, 'C', 'It raises TypeError because inplace is removed', 0), (@q, 'D', 'It fills df[''a''] and also every other column', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([1, 2, 3], index=["a", "b", "a"])\nprint(s.loc["a":"b"].tolist())', 'python', 'KeyError', 'Where does a label slice start when the start label appears twice and the index isn''t sorted?', 'A label slice needs one start position and one end position. With ''a'' at positions 0 and 2 in an unsorted index there is no single start, so pandas raises KeyError: cannot get left slice bound for non-unique label. [1, 2] is what you''d guess if pandas used the first ''a''. It refuses to guess instead. Duplicate labels often sneak in after concat without ignore_index. Check df.index.is_unique, or sort_index() (a sorted index with duplicates can be sliced).', 'pos:    0    1    2\nlabel: ''a''  ''b''  ''a''\n         ^         ^\n   left bound for ''a'' = 0 or 2?  -> KeyError', NULL, 158);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2]', 0), (@q, 'B', '[1, 2, 3]', 0), (@q, 'C', 'KeyError', 1), (@q, 'D', '[2, 3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 3, 'mcq', '`df` has index [0, 1]. What does `df.loc[[0, 5], ''v'']` do?', 'import pandas as pd\ndf = pd.DataFrame({"v": [10, 20]})\nprint(df.reindex([0, 5])["v"].tolist())', 'python', 'Raises KeyError, because label 5 is not in the index', 'Older pandas filled missing labels with NaN. What changed in pandas 1.0?', 'Since pandas 1.0, loc with a list that contains any missing label raises KeyError instead of quietly inserting NaN rows. If you really want ''NaN where missing'' (like a LEFT JOIN against a list of ids), say so with df.reindex([0, 5]). Being explicit matters in feature lookups: a typo''d id should fail loudly rather than add an all-NaN row to your training data.', NULL, NULL, 159);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Treats 5 as a position and raises IndexError', 0), (@q, 'B', 'Returns the value for 0 and NaN for 5', 0), (@q, 'C', 'Raises KeyError, because label 5 is not in the index', 1), (@q, 'D', 'Returns only the row for label 0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 4, 'true_false', '`df.iloc[df[''v''] > 1]` works exactly like `df.loc[df[''v''] > 1]`.', NULL, NULL, 'False', 'iloc is position-based. A boolean Series carries labels.', 'iloc refuses a boolean Series, because a Series brings an index that iloc can''t use. You get NotImplementedError ("iLocation based boolean indexing on an integer type is not available"). Pass a plain array instead: df.iloc[(df[''v''] > 1).to_numpy()]. Or use loc, which aligns the mask by label. The tempting belief is that ''a mask is a mask''. The difference is a reminder that loc aligns and iloc doesn''t.', NULL, NULL, 160);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 3, 'mcq', 'You need column ''b'' for every row from the 2nd one onward, by position, on a frame with string row labels. Which line is correct?', NULL, NULL, 'df.iloc[1:, df.columns.get_loc(''b'')]', 'iloc wants positions on BOTH axes.', 'iloc accepts only integers, slices and boolean arrays, so turn the column name into its position with df.columns.get_loc(''b''). df[''b''].iloc[1:] works too. df.iloc[1:, ''b''] raises because ''b'' isn''t a position, and df.loc[1:, ''b''] fails because 1 isn''t a label in a string index. .ix was removed in pandas 1.0. Mixing label and position lookups explicitly like this avoids bugs when the index later changes from RangeIndex to ids.', NULL, NULL, 161);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df.loc[1:, ''b'']', 0), (@q, 'B', 'df.iloc[1:, ''b'']', 0), (@q, 'C', 'df.iloc[1:, df.columns.get_loc(''b'')]', 1), (@q, 'D', 'df.ix[1:, ''b'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'index-alignment'), 3, 'code_output', 'What does this print?', 'import pandas as pd\na = pd.Series([1, 2], index=["x", "y"])\nb = pd.Series([1, 2], index=["y", "x"])\nprint((a == b).tolist())', 'python', 'ValueError', 'Arithmetic aligns. Do comparison operators?', '`+` and `-` align on labels, but `==`, `<` and friends on two Series require identically-labelled Series (same labels in the same order), otherwise ValueError: Can only compare identically-labeled Series objects. pandas refuses to silently reorder a comparison you''ll probably use as a mask. Use a.eq(b), which aligns first, or compare a.sort_index() with b.sort_index() when you mean ''same values per label''.', NULL, NULL, 162);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[True, True]', 0), (@q, 'B', 'ValueError', 1), (@q, 'C', '[False, False]', 0), (@q, 'D', '[True, False]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'index-alignment'), 4, 'code_output', 'What does this print?', 'import pandas as pd\na = pd.Series([1, 2], index=["x", "y"])\nb = pd.Series([2, 1], index=["y", "x"])\nprint(a.eq(b).tolist(), a.equals(b), (a + b).tolist())', 'python', '[True, True] False [2, 4]', 'eq and + align by label; equals is stricter.', 'a.eq(b) aligns first: x is 1 vs 1 and y is 2 vs 2, so both are True. `+` aligns the same way: [2, 4]. equals() compares the objects as stored, element by element in position order with the index included, so the reordered b is not ''equal''. In tests, use pd.testing.assert_series_equal(a, b.reindex(a.index)) when order shouldn''t matter. Otherwise a reordered but correct result fails the test.', NULL, NULL, 163);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[True, True] False [2, 4]', 1), (@q, 'B', '[False, False] False [3, 3]', 0), (@q, 'C', '[True, True] True [2, 4]', 0), (@q, 'D', 'ValueError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'index-alignment'), 4, 'mcq', '`a` has integer labels 0, 1. `b` came from a JSON payload and has string labels ''0'', ''1''. What is `a + b`?', 'import pandas as pd\na = pd.Series([1, 2], index=[0, 1])\nb = pd.Series([10, 20], index=["0", "1"])\nr = a + b\nprint(len(r), int(r.isna().sum()))', 'python', '4 rows, all NaN: 0 and ''0'' are different labels, so nothing aligns', 'Alignment compares labels with ==. Is 0 == ''0'' in Python?', 'Alignment is an outer join on the index, and the int 0 never equals the string ''0''. The result has the union of the labels (four of them) and every value is NaN. There''s no error, so the bug shows up later as a column of NaN. It''s the same as joining an INT key to a VARCHAR key in a database that doesn''t cast. Normalise index dtypes at the boundary (b.index = b.index.astype(int)) whenever data arrives from JSON, CSV or an API.', NULL, 'Like a SQL join on user_id where one table stores it as INT and the other as VARCHAR: no rows match.', 164);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '4 rows, all NaN: 0 and ''0'' are different labels, so nothing aligns', 1), (@q, 'B', '2 rows, all NaN', 0), (@q, 'C', 'TypeError, because the index types differ', 0), (@q, 'D', '2 rows with the element-wise sums, since the labels look the same', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'index-alignment'), 4, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\na = pd.Series([1.0, np.nan], index=["x", "y"])\nb = pd.Series([10.0], index=["x"])\nprint(a.add(b, fill_value=0).tolist())', 'python', '[11.0, nan]', 'fill_value fills a label that is missing on ONE side. What about a NaN that is already there?', 'For y, b has no label, so fill_value=0 stands in for b. But a''s own value at y is NaN, and NaN + 0 is still NaN. fill_value only patches holes created by alignment, not existing missing values. The tempting [11.0, 0.0] assumes it fills NaN everywhere. When summing per-user totals from two sources, fillna(0) both sides first if a missing value really means zero.', NULL, NULL, 165);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[11.0, 10.0]', 0), (@q, 'B', '[11.0, 1.0]', 0), (@q, 'C', '[11.0, 0.0]', 0), (@q, 'D', '[11.0, nan]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'index-alignment'), 4, 'mcq', 'How can you make pandas fail fast when a step in your pipeline introduces duplicate row labels?', 'import pandas as pd\ns = pd.Series([1, 2], index=["a", "b"]).set_flags(allows_duplicate_labels=False)\nprint(s.flags.allows_duplicate_labels)', 'python', 'df = df.set_flags(allows_duplicate_labels=False): operations that would create duplicates raise DuplicateLabelError', 'It''s a per-object flag, not a global option.', 'set_flags(allows_duplicate_labels=False) marks the frame, and pandas raises DuplicateLabelError if the frame has, or would get, duplicate labels (for example via a concat or loc enlargement that propagates the flag). is_unique is a read-only property, and the option doesn''t exist. It works like a UNIQUE constraint on a primary key, and it''s handy at the top of a feature pipeline where duplicate ids would silently double-count rows.', NULL, 'A UNIQUE constraint on the primary key column, enforced at write time.', 166);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'There''s no way; you must call df.index.duplicated().any() after every step', 0), (@q, 'B', 'pd.options.mode.unique_index = True', 0), (@q, 'C', 'df = df.set_flags(allows_duplicate_labels=False): operations that would create duplicates raise DuplicateLabelError', 1), (@q, 'D', 'df.index.is_unique = True', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-features'), 3, 'mcq', 'A feature frame has two numeric columns and one forgotten text column. What does `X = df.to_numpy()` give you?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2], "b": [0.5, 1.5]})\nprint(df.to_numpy().dtype, df.assign(c=["x", "y"]).to_numpy().dtype)', 'python', 'A single array of dtype object, so every number becomes a Python object and most models fail or crawl', 'A NumPy array has exactly one dtype.', 'to_numpy() must find one dtype that fits every column. int + float gives float64, but adding any str column forces object. scikit-learn then either raises ''could not convert string to float'' or runs slowly on boxed Python objects. Check X.dtypes, or build X with select_dtypes / an explicit column list, before converting. That one-line check catches a surprising number of ''my model won''t train'' bugs.', NULL, NULL, 167);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'An array with the text column dropped automatically', 0), (@q, 'B', 'A single array of dtype object, so every number becomes a Python object and most models fail or crawl', 1), (@q, 'C', 'A float64 array with NaN in place of the text', 0), (@q, 'D', 'One NumPy array per column, each with its own dtype', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-features'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1], "b": [True], "c": [1.5], "d": ["x"]})\nprint(df.select_dtypes("number").columns.tolist())', 'python', '[''a'', ''c'']', 'Is bool a ''number'' in pandas'' dtype hierarchy?', 'select_dtypes(''number'') matches integer and float dtypes, but bool is a separate kind and is excluded. Python says True + 1 == 2, which tempts people towards [''a'', ''b'', ''c'']. If your numeric-feature list is built this way, boolean flags like is_premium silently drop out of the model. Use select_dtypes(include=[''number'', ''bool'']) or list the features explicitly.', NULL, NULL, 168);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''c'']', 0), (@q, 'B', '[''a'', ''c'']', 1), (@q, 'C', '[''a'', ''b'', ''c'', ''d'']', 0), (@q, 'D', '[''a'', ''b'', ''c'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-features'), 4, 'code_output', 'What does this print?', 'import pandas as pd\nfrom sklearn.model_selection import train_test_split\ndf = pd.DataFrame({"x": range(10), "y": range(10)})\nXtr, Xte, ytr, yte = train_test_split(df[["x"]], df["y"], test_size=0.3, random_state=0)\nXtr = Xtr.reset_index(drop=True)\nboth = pd.concat([Xtr, ytr], axis=1)\nprint(both.shape, int(both["y"].isna().sum()))', 'python', '(9, 2) 2', 'train_test_split keeps the original row labels. Which of the two did you renumber?', 'Xtr now has labels 0..6, while ytr keeps the shuffled original labels (a subset of 0..9). concat(axis=1) aligns on labels: the union has 9 labels, and the two labels only Xtr has get NaN in y. Worse, the rows that do line up pair x with the wrong y. Reset both or neither. Mixing them is a classic way to train on scrambled labels and get a mysteriously useless model.', 'Xtr (reset): 0 1 2 3 4 5 6\nytr (orig) : 9 1 6 7 3 0 5      <- labels, not positions\nconcat aligns labels -> 0..6 plus 9, 7 = 9 rows\nx and y now paired by label, not by sample', NULL, 169);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(9, 2) 2', 1), (@q, 'B', '(7, 2) 0', 0), (@q, 'C', 'ValueError', 0), (@q, 'D', '(14, 2) 7', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-features'), 4, 'mcq', 'A model was fit on a DataFrame with columns [''a'', ''b'']. At serving time the request builds a frame with columns [''b'', ''a'']. What does scikit-learn 1.6 do on predict?', 'import pandas as pd\nfrom sklearn.linear_model import LinearRegression\nX = pd.DataFrame({"a": [1.0, 2.0, 3.0], "b": [0.0, 1.0, 0.0]})\nm = LinearRegression().fit(X, [1.0, 2.0, 3.0])\nprint(m.feature_names_in_.tolist())', 'python', 'Raises ValueError: the feature names must be in the same order as during fit', 'The estimator stored feature_names_in_. Does it reorder or check?', 'Since scikit-learn 1.2, an estimator fitted on a DataFrame records feature_names_in_, and predict raises ValueError if the names, or their order, differ. It checks but doesn''t fix. That''s lucky: silently using positions would apply a''s weight to b. In a service, align explicitly with X = X[model.feature_names_in_] (or reindex) before predict, like a typed API contract.', NULL, NULL, 170);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Reorders the columns automatically by name', 0), (@q, 'B', 'Silently predicts using the columns by position (b as a)', 0), (@q, 'C', 'Raises ValueError: the feature names must be in the same order as during fit', 1), (@q, 'D', 'Warns and drops the extra ordering information', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-features'), 3, 'true_false', 'If a scikit-learn model was fit on a DataFrame, calling `predict` with a plain NumPy array of the same shape raises an error.', NULL, NULL, 'False', 'A NumPy array has no column names to check.', 'It only warns (''X does not have valid feature names'') and then uses the columns by position. That''s exactly the dangerous case: the names check can''t protect you, so a column-order bug goes straight into predictions. Keep DataFrames all the way to predict, or keep the column order in one place (a saved feature list) and enforce it.', NULL, NULL, 171);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-features'), 3, 'mcq', 'What does `StandardScaler().set_output(transform=''pandas'').fit_transform(X)` return when X is a DataFrame with index [10, 20]?', 'import pandas as pd\nfrom sklearn.preprocessing import StandardScaler\nX = pd.DataFrame({"a": [1.0, 3.0], "b": [2.0, 2.0]}, index=[10, 20])\nout = StandardScaler().set_output(transform="pandas").fit_transform(X)\nprint(type(out).__name__, out.index.tolist(), out["a"].tolist())', 'python', 'A DataFrame with the same column names and the same index [10, 20]', 'set_output was added so pipelines can stay in pandas.', 'By default transformers return NumPy arrays and lose the column names. set_output(transform=''pandas'') (scikit-learn 1.2+) makes them return a DataFrame that keeps the names and the original index. Feature importances and debugging stay readable, and later pandas steps can still select by name. Because the index is kept, concatenating the output with other frames aligns correctly.', NULL, NULL, 172);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A DataFrame with the same column names and the same index [10, 20]', 1), (@q, 'B', 'A DataFrame with columns 0, 1 and a fresh RangeIndex', 0), (@q, 'C', 'A NumPy array, because scalers always return arrays', 0), (@q, 'D', 'A dict of column name -> scaled array', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-features'), 3, 'fill_blank', 'At serving time, force a request frame to the training columns (same order, missing ones as 0, extra ones dropped): `X = X.____(columns=train_cols, fill_value=0)`', 'import pandas as pd\ntrain_cols = ["age", "city_Goa", "city_Pune"]\nreq = pd.DataFrame({"city_Pune": [1], "age": [30], "city_Delhi": [1]})\nprint(req.reindex(columns=train_cols, fill_value=0).values.tolist())', 'python', 'reindex', 'It conforms an axis to a given list of labels.', 'reindex(columns=train_cols, fill_value=0) puts the columns in training order, adds any missing one-hot columns as 0 and drops unknown extras. That''s the standard fix for ''test has a category train never saw'' and ''test lacks a category train had''. Save train_cols with the model artifact so training and serving share one source of truth.', 'request: city_Pune age city_Delhi\n            \\       |      x  (unknown, dropped)\ntrain  : age  city_Goa  city_Pune\n         30     0 (new)     1', NULL, 173);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-features'), 3, 'mcq', 'Why is `X, y = df.drop(columns=''target''), df[''target'']` safer than building X and y from separate queries or separate CSV files?', NULL, NULL, 'They come from one frame with one index, so row i of X and row i of y describe the same sample', 'What keeps a feature row and its label together?', 'X and y split from the same frame share the index, so every later filter, sort or split can be applied to both consistently. Two separate queries can return rows in different orders (SQL without ORDER BY guarantees nothing), and the model then learns from mismatched pairs without any error. If you must load them separately, join them on an id first and assert the ids match.', NULL, 'Like selecting both columns in one SQL query instead of running two queries without ORDER BY and zipping the results.', 174);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'drop is faster than selecting columns', 0), (@q, 'B', 'They come from one frame with one index, so row i of X and row i of y describe the same sample', 1), (@q, 'C', 'scikit-learn requires y to be named ''target''', 0), (@q, 'D', 'It automatically removes leakage columns', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 4, 'code_output', 'What does this print?', 'import pandas as pd\nprint(pd.NA ** 0, pd.NA | True, pd.NA & False, pd.NA & True)', 'python', '1 True False <NA>', 'pd.NA means ''unknown''. Is the result the same whatever the unknown value is?', 'pd.NA follows three-valued (SQL-style) logic: when the answer is the same whatever the unknown value is, you get that answer. x**0 is always 1, unknown OR True is always True, and unknown AND False is always False. unknown AND True depends on the unknown, so it stays <NA>. That''s exactly SQL''s NULL truth table. If you expect NA to swallow everything you''ll mispredict filters built from nullable boolean columns.', '  AND  | True   False  NA\n ------+-------------------\n  NA   |  NA    False   NA\n  OR   | True   False  NA\n ------+-------------------\n  NA   | True    NA     NA', NULL, 175);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '<NA> <NA> <NA> <NA>', 0), (@q, 'C', '1 True False True', 0), (@q, 'D', '1 True False <NA>', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([1, 2, None], dtype="Int64")\nprint((s / 2).dtype, (s // 2).dtype, (s > 1).dtype)', 'python', 'Float64 Int64 boolean', 'Nullable dtypes stay nullable through operations.', 'True division can produce fractions, so Int64 / 2 becomes the nullable Float64 (capital F), floor division stays Int64, and a comparison gives the nullable boolean dtype with <NA> where the input was missing. The NumPy-flavoured answers (float64, bool) are what you''d get from int64 data. Once you opt into nullable dtypes the whole chain stays nullable, which is good for correctness. Some older libraries choke on Float64 and boolean, though, so convert at the model boundary.', NULL, NULL, 176);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'float64 int64 bool', 0), (@q, 'B', 'Float64 Float64 bool', 0), (@q, 'C', 'Float64 Int64 boolean', 1), (@q, 'D', 'object Int64 boolean', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 3, 'true_false', 'On an object column with a None in it, `s.str.len()` returns float64, but on a `''string''` dtype column it returns the nullable `Int64`.', 'import pandas as pd\no = pd.Series(["a", "bb", None])\nprint(o.str.len().dtype, o.astype("string").str.len().dtype)', 'python', 'True', 'Lengths are integers. What does each dtype family use for ''missing''?', 'Object columns mark missing as NaN, and NaN can only live in a float column, so the lengths become float64 (1.0, 2.0, nan). The ''string'' dtype uses pd.NA and returns Int64 lengths (1, 2, <NA>). It''s a small difference until you use the lengths as dictionary keys or compare them to ints from another table.', NULL, NULL, 177);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 3, 'mcq', 'What happens here, and what''s the fix?', 'import pandas as pd\ns = pd.Series(["a", "b"], dtype="category")\ntry:\n    s[0] = "z"\nexcept TypeError:\n    print("TypeError")', 'python', 'TypeError: ''z'' is not one of the categories; call s.cat.add_categories(''z'') first (or work in object/string dtype)', 'A categorical''s set of allowed values is part of its dtype.', 'A category column is an integer code per row plus a fixed list of categories, and there is no code for ''z''. pandas raises TypeError: Cannot setitem on a Categorical with a new category. That strictness is a feature: it''s how a category dtype behaves like a CHECK constraint or an enum column. In ML data prep, decide deliberately what to do with unseen values (map them to an ''other'' category) rather than letting them sneak in.', NULL, 'Like inserting a value into a Postgres ENUM column that the enum type doesn''t list.', 178);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError: ''z'' is not one of the categories; call s.cat.add_categories(''z'') first (or work in object/string dtype)', 1), (@q, 'B', 'The value silently becomes NaN', 0), (@q, 'C', 'The value becomes ''z'' and the category list grows automatically', 0), (@q, 'D', 'ValueError: categoricals are read-only', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 4, 'code_output', 'What does this print?', 'import pandas as pd\na = pd.Series(["x", "y"], dtype="category")\nb = pd.Series(["y", "z"], dtype="category")\nc = pd.Series(["x", "y"], dtype="category")\nprint(pd.concat([a, b]).dtype, pd.concat([a, c]).dtype)', 'python', 'object category', 'concat keeps the category dtype only when the dtypes are identical.', 'a and b have different category lists, so concat can''t keep one categorical dtype and falls back to object. All the memory savings vanish without a warning. a and c have identical categories, so the result stays category. This bites when monthly files each get astype(''category'') separately. Fix it with a shared pd.CategoricalDtype(all_values), or pandas.api.types.union_categoricals.', NULL, NULL, 179);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'object category', 1), (@q, 'B', 'category object', 0), (@q, 'C', 'object object', 0), (@q, 'D', 'category category', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 3, 'fill_blank', 'To convert every column of a DataFrame to the best nullable dtype (Int64, string, boolean, Float64) in one call, use `df.____()`.', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, None], "b": ["x", None], "c": [True, None]})\nprint(df.convert_dtypes().dtypes.astype(str).tolist())', 'python', 'convert_dtypes', 'It''s a single method that ''converts dtypes''.', 'convert_dtypes() inspects each column and picks the nullable extension dtype that fits it: ints with missing values become Int64 instead of float64, text becomes string, and True/False/None becomes boolean. It''s a quick way to stop None from upcasting ints after loading messy data.', NULL, NULL, 180);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 4, 'mcq', 'You switch a 10-million-row text column from object to `dtype=''string''` (the default python storage) to save memory. What happens?', NULL, NULL, 'Little or no saving: ''string[python]'' still stores one Python str object per row; pyarrow-backed strings (''string[pyarrow]'') are the compact option', 'What does the ''python'' in ''string[python]'' refer to?', 'The ''string'' dtype gives you clear semantics: only strings or pd.NA, and Int64/boolean results from .str methods. With python storage it still holds an array of Python str objects, so memory_usage(deep=True) barely changes. pyarrow storage keeps all the characters in one contiguous buffer plus offsets, which is often several times smaller and faster. pandas 3.0 makes the pyarrow-backed str the default when pyarrow is installed. For low-cardinality text, category is still the biggest win.', NULL, NULL, 181);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Little or no saving: ''string[python]'' still stores one Python str object per row; pyarrow-backed strings (''string[pyarrow]'') are the compact option', 1), (@q, 'B', 'It raises because string dtype needs a fixed width', 0), (@q, 'C', 'Memory drops about 8x because string dtype packs characters into one buffer', 0), (@q, 'D', 'Memory doubles because every value is stored twice', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 3, 'mcq', 'Which statement about `np.nan` vs `pd.NA` is correct?', NULL, NULL, 'np.nan is a float that is unequal to everything; pd.NA is a dtype-independent ''unknown'' that propagates through comparisons (pd.NA == 1 is <NA>)', 'Think of IEEE floats on one side and SQL NULL on the other.', 'np.nan comes from IEEE floating point: it''s a float, so ints with NaN become float64, and nan == nan is False. pd.NA is pandas'' own missing marker for nullable dtypes (Int64, boolean, string). Comparisons with it give <NA>, like SQL NULL, and bool(pd.NA) raises TypeError. Code that checks `x == x` to detect missing values breaks with pd.NA. Use pd.isna(x) everywhere.', NULL, NULL, 182);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'np.nan is a float that is unequal to everything; pd.NA is a dtype-independent ''unknown'' that propagates through comparisons (pd.NA == 1 is <NA>)', 1), (@q, 'B', 'np.nan works in Int64 columns, pd.NA only in float columns', 0), (@q, 'C', 'They are the same object with two names', 0), (@q, 'D', 'pd.NA is just None, so pd.NA == None is True', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2], "b": [0.5, 1.5]})\nprint(df.apply(lambda r: r["a"], axis=1).tolist())\ndf["c"] = ["x", "y"]\nprint(df.apply(lambda r: r["a"], axis=1).tolist())', 'python', '[1.0, 2.0]\n[1, 2]', 'apply(axis=1) hands your function each row as a Series. What dtype must that Series have?', 'Each row is packed into one Series, which needs one dtype. With int and float columns the row is float64, so r[''a''] is 1.0. Once a str column joins, the row has to be object, and the original int survives as 1. So the same lambda returns different types depending on unrelated columns. It''s one more reason (besides speed) to use column-wise vectorised code. An ID column read through apply(axis=1) can quietly become 1.0 and then fail a dictionary lookup.', NULL, NULL, 183);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2]\n[1, 2]', 0), (@q, 'B', '[1.0, 2.0]\n[1, 2]', 1), (@q, 'C', '[1.0, 2.0]\n[1.0, 2.0]', 0), (@q, 'D', '[1, 2]\n[''1'', ''2'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 3, 'mcq', 'A teammate wraps a Python function with `np.vectorize(f)` and applies it to a 5-million-row column, saying it is now vectorised. Is it as fast as `df[''a''] * 2`?', NULL, NULL, 'No: np.vectorize is a convenience loop that still calls f once per element in Python', 'Read the NumPy docs'' note on np.vectorize performance.', 'np.vectorize only gives f broadcasting semantics. Under the hood it''s essentially a for loop, so it runs at Series.apply speed, about 100x slower than real array ops. True vectorisation means expressing the logic with whole-array operations: arithmetic, np.where/np.select, .str/.dt methods, map with a dict. Interviewers like this one because the name misleads so many people.', NULL, 'Like calling a stored procedure once per row from your app versus one set-based UPDATE: the wrapper''s name doesn''t change the round-trips.', 184);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Yes: np.vectorize compiles f to C', 0), (@q, 'B', 'No, it''s slower because it runs on the GPU', 0), (@q, 'C', 'Yes, as long as f only uses arithmetic', 0), (@q, 'D', 'No: np.vectorize is a convenience loop that still calls f once per element in Python', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 3, 'fill_blank', 'Inside `df.query(...)`, a column name that contains a space (like unit price) must be wrapped in ____.', 'import pandas as pd\ndf = pd.DataFrame({"unit price": [4, 8, 12]})\nprint(df.query("`unit price` > 5").shape)', 'python', 'backticks', 'It''s the same character Markdown uses for inline code.', 'query parses its string as an expression, so `unit price` must be quoted with backticks: df.query(''`unit price` > 5''). Plain quotes would make it a string literal. It''s similar to quoting an identifier with spaces in SQL ("unit price" in Postgres, `unit price` in MySQL). Renaming columns to snake_case at load time avoids the issue.', NULL, NULL, 185);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 4, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\ns = pd.Series([1.0, np.nan])\nprint(s.isin([np.nan]).tolist(), (s == np.nan).tolist())', 'python', '[False, True] [False, False]', 'isin uses hashing, not ==.', '`== np.nan` is always False, because NaN is unequal to itself under IEEE rules. isin works like a hash-set lookup, and pandas'' hash table treats all NaNs as the same key, so NaN is found. The inconsistency is real: a filter written with isin([..., np.nan]) keeps missing rows, while the equivalent == chain drops them. When you mean missing, say so: s.isna() | s.isin(values).', NULL, NULL, 186);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[False, False] [False, False]', 0), (@q, 'B', '[False, True] [False, False]', 1), (@q, 'C', '[False, True] [False, True]', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 4, 'true_false', 'Indexing an `Int64` Series with a boolean mask that contains `<NA>` (e.g. `s[s > 1]` where s has a missing value) raises ValueError.', 'import pandas as pd\ns = pd.Series([1, None, 3], dtype="Int64")\nprint(s[s > 1].tolist())', 'python', 'False', 'Object-dtype masks with NaN raise. Nullable boolean masks follow a different rule.', 'Since pandas 1.0.2, a nullable boolean mask treats <NA> as False when indexing, so s[s > 1] on [1, <NA>, 3] returns [3]. An object-dtype mask holding NaN (say, from .str.contains on an object column) still raises ValueError. So the same filter code can work or crash depending on the column''s dtype. Write .fillna(False) on masks when you can''t control the dtype.', NULL, NULL, 187);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 4, 'mcq', '`m` has a sorted (city, year) MultiIndex. Which expression selects the ''v'' values for every city in 2024?', 'import pandas as pd\ndf = pd.DataFrame({"city": ["Goa", "Goa", "Pune", "Pune"], "year": [2023, 2024, 2023, 2024], "v": [1, 2, 3, 4]})\nm = df.set_index(["city", "year"]).sort_index()\nprint(m.loc[pd.IndexSlice[:, 2024], "v"].tolist())', 'python', 'm.loc[pd.IndexSlice[:, 2024], ''v'']', 'You need a slice object for the outer level, and Python syntax doesn''t allow a bare colon inside a tuple.', 'pd.IndexSlice lets you write slices per level: idx[:, 2024] means ''all cities, year 2024''. `(:, 2024)` is a SyntaxError. m.loc[2024] looks 2024 up in the OUTER level (city) and raises KeyError, and ''*'' is just a literal label. m.xs(2024, level=''year'') is the other idiom. Slicing like this needs a lexsorted index, so call sort_index() first or pandas raises UnsortedIndexError.', 'city  year | v\nGoa   2023 | 1\nGoa   2024 | 2   <- idx[:, 2024]\nPune  2023 | 3\nPune  2024 | 4   <-', NULL, 188);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'm.loc[pd.IndexSlice[:, 2024], ''v'']', 1), (@q, 'B', 'm.loc[(:, 2024), ''v'']', 0), (@q, 'C', 'm.loc[(''*'', 2024), ''v'']', 0), (@q, 'D', 'm.loc[2024, ''v'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"city": ["Goa", "Goa", "Pune"], "year": [2023, 2024, 2023], "v": [1, 2, 3]})\nm = df.set_index(["city", "year"])\nprint(m.loc[["Goa", "Pune"]].shape, m.loc[[("Goa", 2024), ("Pune", 2023)]].shape)', 'python', '(3, 1) (2, 1)', 'A list of plain labels matches the outer level; a list of tuples matches full keys.', 'm.loc[[''Goa'', ''Pune'']] picks every row whose OUTER label is Goa or Pune: all 3 rows. A list of tuples is a list of complete (city, year) keys, so exactly those 2 rows come back. A single tuple, m.loc[(''Goa'', 2024)], is one full key, which is why list-vs-tuple matters so much with a MultiIndex. It''s like WHERE city IN (...) versus WHERE (city, year) IN (...).', NULL, NULL, 189);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'KeyError', 0), (@q, 'B', '(2, 1) (2, 1)', 0), (@q, 'C', '(3, 1) (2, 1)', 1), (@q, 'D', '(3, 1) (3, 1)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 3, 'true_false', '`unstack()` on an int64 Series whose (row, col) combinations are not all present keeps the int64 dtype.', 'import pandas as pd\ns = pd.Series([1, 2, 3], index=pd.MultiIndex.from_tuples([("a", "x"), ("a", "y"), ("b", "x")]))\nprint(s.unstack().dtypes.astype(str).tolist(), s.unstack(fill_value=0)["y"].tolist())', 'python', 'False', 'What goes in the missing cells?', 'The missing combinations become NaN, and NaN forces float64, so the whole table turns float. Pass fill_value=0 (s.unstack(fill_value=0)) to keep integers when ''missing'' really means zero, e.g. counts. Otherwise a count matrix used as model features quietly becomes floats with NaN, and many estimators reject the NaN.', NULL, NULL, 190);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 3, 'code_output', 'What does this print?', 'import io\nimport pandas as pd\ncsv = "country\\nNA\\nIN"\na = pd.read_csv(io.StringIO(csv))\nb = pd.read_csv(io.StringIO(csv), keep_default_na=False)\nprint(int(a["country"].isna().sum()), int(b["country"].isna().sum()))', 'python', '1 0', '''NA'' is on read_csv''s default list of missing-value markers.', 'By default read_csv treats strings like ''NA'', ''N/A'', ''null'', ''NaN'' and '''' as missing, so Namibia''s ISO code ''NA'' becomes NaN. keep_default_na=False turns that list off. You can then pass your own na_values=[''''] if blanks should still be missing. The same trap hits a ''NULL'' surname or an ''NA'' (not applicable) answer that is a real category. Always check value_counts(dropna=False) on text columns after loading.', NULL, NULL, 191);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1 1', 0), (@q, 'B', '1 0', 1), (@q, 'C', '0 1', 0), (@q, 'D', '0 0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 3, 'fill_blank', 'A CSV has amounts written like "1,234". To parse them as integers, call `pd.read_csv(f, ____=",")`.', 'import io\nimport pandas as pd\ncsv = ''amount\\n"1,234"\\n5''\nprint(pd.read_csv(io.StringIO(csv), thousands=",")["amount"].tolist())', 'python', 'thousands', 'The parameter names the separator used between groups of digits.', 'thousands='','' tells the parser to strip the grouping separator, so "1,234" becomes 1234 (int64) instead of the column staying object. For European files, combine thousands=''.'' with decimal='',''. The alternative, cleaning the strings afterwards with .str.replace, is slower and easy to forget.', NULL, NULL, 192);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 4, 'mcq', 'A CSV column `flag` holds True/False, but one row is blank. What dtype does read_csv give it?', 'import io\nimport pandas as pd\nclean = "flag\\nTrue\\nFalse"\ndirty = "flag,x\\nTrue,1\\n,2\\nFalse,3"\nprint(pd.read_csv(io.StringIO(clean))["flag"].dtype, pd.read_csv(io.StringIO(dirty))["flag"].dtype)', 'python', 'object: True, False and NaN mixed, because NumPy bool has no missing value', 'Without the blank it would be bool. What can hold a NaN?', 'A clean True/False column parses as bool. One blank means a missing value, NumPy bool can''t hold NaN, and read_csv''s default (NumPy-backed) parser falls back to object. The nullable ''boolean'' answer is what you''d get with dtype={''flag'': ''boolean''} or dtype_backend=''numpy_nullable''. On an object column, df[df[''flag'']] raises ValueError because the mask contains NaN. That''s how a single blank cell in a nightly file can break the training job.', NULL, NULL, 193);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'object: True, False and NaN mixed, because NumPy bool has no missing value', 1), (@q, 'B', 'boolean (nullable), with <NA> for the blank', 0), (@q, 'C', 'bool, with the blank read as False', 0), (@q, 'D', 'float64, with 1.0/0.0 and NaN', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 4, 'mcq', 'Loading a 5 GB CSV prints `DtypeWarning: Columns (7) have mixed types`. What is going on, and what is the proper fix?', NULL, NULL, 'The parser infers types chunk by chunk; column 7 looked numeric in some chunks and text in others, so it became object with mixed int/str values. Pass dtype={...} for that column', 'With low_memory=True (the default) the C parser works in chunks.', 'Type inference happens per chunk. If early chunks are all digits (zip codes 41001) and a later one has ''41001-A'', the column ends up object holding a mix of int and str. Then ''41001'' and 41001 never compare equal, and groupby splits one value into two keys. low_memory=False only hides the symptom by inferring once over the whole column. Declaring dtype={''zip'': ''string''} states the contract, much like a schema in a database.', 'chunk 1: 41001, 41002  -> int\nchunk 2: 41003         -> int\nchunk 3: ''41001-A''     -> str\ncolumn = object [41001, 41002, 41003, ''41001-A'']\n         41001 != ''41001''  -> groupby splits keys', NULL, 194);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The file encoding is wrong; pass encoding=''latin-1''', 0), (@q, 'B', 'The parser infers types chunk by chunk; column 7 looked numeric in some chunks and text in others, so it became object with mixed int/str values. Pass dtype={...} for that column', 1), (@q, 'C', 'Column 7 has too many rows; pass nrows=', 0), (@q, 'D', 'It''s harmless; pandas converts the whole column to float at the end', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'series-vs-df'), 2, 'mcq', '`s` is a Series of ages indexed by name (Ann, Bob). What does `''Ann'' in s` check?', 'import pandas as pd\ns = pd.Series([30, 25], index=[''Ann'', ''Bob''])\nprint(''Ann'' in s, 30 in s, 30 in s.values)', 'python', 'Whether ''Ann'' is one of the index labels', 'A Series behaves a lot like a dict.', 'Like a Python dict, `in` on a Series tests the keys (the index), not the values: ''Ann'' in s is True but 30 in s is False even if 30 is an age. To test values, use `30 in s.values` or `s.isin([30]).any()`. A wrong membership check silently returns False and skips a branch you thought ran.', NULL, 'dict membership: `''Ann'' in {''Ann'': 30}` is True, `30 in {''Ann'': 30}` is False.', 195);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Whether ''Ann'' is one of the values', 0), (@q, 'B', 'Whether ''Ann'' is one of the index labels', 1), (@q, 'C', 'Whether ''Ann'' appears in either the labels or the values', 0), (@q, 'D', 'Nothing: `in` raises ValueError on a Series', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'series-vs-df'), 1, 'true_false', '`df.loc[''r1'']` on a DataFrame returns a Series whose index is the DataFrame''s column names.', NULL, NULL, 'True', 'One row, turned on its side.', 'Selecting one row gives a 1-D Series: the column names become its index and the cells become its values. That is why row[''age''] works on a row from loc or iterrows. It is the same idea as one record from a JSON array: keys are field names.', NULL, NULL, 196);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 1, 'fill_blank', 'The pandas function that loads a CSV file into a DataFrame is `pd.____(''data.csv'')`.', NULL, NULL, 'read_csv', 'read_... followed by the file format.', 'pd.read_csv parses the file, uses the first line as column names and guesses a dtype for each column. Its siblings follow the same pattern: read_json, read_parquet, read_excel, read_sql.', NULL, NULL, 197);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 2, 'mcq', 'You build `pd.DataFrame(records)` from API JSON where some records have no `email` key. What happens?', 'import pandas as pd\nrecords = [{''id'': 1, ''email'': ''a@x.io''}, {''id'': 2}]\nprint(pd.DataFrame(records))', 'python', 'You get an email column with NaN in the rows whose record lacked the key', 'pandas takes the union of all keys.', 'From a list of dicts, the columns are the union of the keys; a record missing a key gets NaN in that cell. This is like a LEFT JOIN that leaves NULLs, not an error. Check df[''email''].isna().sum() before you trust the column, because downstream code that expects strings will meet floats (NaN).', NULL, NULL, 198);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The email column is dropped because not every record has it', 0), (@q, 'B', 'The missing emails are filled with empty strings', 0), (@q, 'C', 'You get an email column with NaN in the rows whose record lacked the key', 1), (@q, 'D', 'pandas raises KeyError because the records have different keys', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 2, 'fill_blank', 'A 3 GB CSV has 200 columns but your model needs 5. To parse only those, pass `pd.read_csv(path, ____=[''a'', ''b'', ''c'', ''d'', ''e''])`.', NULL, NULL, 'usecols', 'Which columns to use.', 'usecols skips the other columns during parsing, so they never take up memory or parse time. Loading everything and then doing df[cols] still pays the full cost first.', NULL, 'SELECT a, b FROM t instead of SELECT * FROM t and throwing columns away in the app.', 199);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 4, 'mcq', 'pandas 2.2, copy-on-write OFF (the default). You do `df = pd.DataFrame(arr)` with a 2-D float NumPy array, then `arr[0, 0] = 9`. What happens to df?', 'import numpy as np\nimport pandas as pd\narr = np.zeros((2, 2))\ndf = pd.DataFrame(arr)\narr[0, 0] = 9\nprint(df.iloc[0, 0])', 'python', 'df changes too: the constructor wrapped the array without copying it', 'A single-dtype 2-D array can be used as the frame''s data block as it is.', 'Without CoW, DataFrame(ndarray) defaults to copy=False and the frame shares the array''s memory, so writes to arr show up in df (this prints 9.0). With pd.options.mode.copy_on_write = True (the pandas 3.0 default) the constructor copies NumPy input by default and df stays 0. If you need isolation in 2.2, pass copy=True or build from arr.copy().', 'no CoW:  arr --+--> [ 9. 0. | 0. 0. ]\n         df  --+     (one shared buffer)\n\nCoW:     arr ----> [ 9. 0. | 0. 0. ]\n         df  ----> [ 0. 0. | 0. 0. ]  (own copy)', NULL, 200);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df changes only if you passed copy=True', 0), (@q, 'B', 'df changes too: the constructor wrapped the array without copying it', 1), (@q, 'C', 'NumPy raises because the array is now owned by pandas', 0), (@q, 'D', 'df is unchanged: DataFrame() always copies its input', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inspecting'), 2, 'mcq', 'You run `df[''city''].value_counts()` on a column with 40 missing values. Where are those 40 rows in the result?', NULL, NULL, 'Not shown: value_counts drops NaN unless you pass dropna=False', 'Many pandas counting methods skip missing values by default.', 'value_counts() has dropna=True, so the counts add up to the non-missing rows only. Pass dropna=False to see a NaN row. It''s easy to report ''Pune is 60% of users'' when you actually divided by the non-null count, so check how many rows are missing before you trust the percentages.', NULL, NULL, 201);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'In a row labelled NaN at the top', 0), (@q, 'B', 'In a row labelled ''None''', 0), (@q, 'C', 'Not shown: value_counts drops NaN unless you pass dropna=False', 1), (@q, 'D', 'Counted under the most common city', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inspecting'), 3, 'true_false', 'For `s = pd.Series([''a'', ''b'', None, ''a''])`, `s.nunique()` is 2 but `len(s.unique())` is 3.', NULL, NULL, 'True', 'One of them has a dropna default.', 'nunique() defaults to dropna=True and ignores the missing value; unique() returns every distinct value including None. Use nunique(dropna=False) when a missing value should count as its own category, for example when sizing a one-hot encoding.', NULL, NULL, 202);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inspecting'), 3, 'mcq', '`df.info()` ends with `memory usage: 164.0+ bytes`. What does the `+` mean?', 'import pandas as pd\ndf = pd.DataFrame({''t'': [''a'', ''bb''], ''n'': [1, 2]})\ndf.info()', 'python', 'Object columns were counted only as 8-byte pointers, so the real size is larger; use memory_usage=''deep''', 'What does a column of Python strings actually store in its array?', 'An object column stores pointers to Python objects. By default info() counts only the pointers and marks the total with + to say it is a lower bound. df.info(memory_usage=''deep'') or df.memory_usage(deep=True) also measures the string objects, often several times more. Use the deep number when you size a container or a batch job.', NULL, NULL, 203);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The index is excluded from the total', 0), (@q, 'B', 'The frame is still growing and info() could not finish measuring', 0), (@q, 'C', 'Object columns were counted only as 8-byte pointers, so the real size is larger; use memory_usage=''deep''', 1), (@q, 'D', 'pandas rounded the number up to the nearest kilobyte', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'selecting'), 2, 'mcq', 'A column is named `unit price` (with a space). Which line selects it?', NULL, NULL, 'df[''unit price'']', 'Dot access only works for names that are valid Python identifiers.', 'Square brackets accept any column label. Dot access needs a valid identifier (no spaces, no leading digit, not a method name like count). df.unit_price is a different name and raises AttributeError, and df.loc[''unit price''] looks for a row label. Use brackets in production code; dot access is a notebook shortcut.', NULL, NULL, 204);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df.loc[''unit price'']', 0), (@q, 'B', 'df[''unit price'']', 1), (@q, 'C', 'df.unit_price', 0), (@q, 'D', 'df.unit price', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'selecting'), 3, 'fill_blank', 'To keep every column EXCEPT the numeric ones (e.g. to list the text columns you still have to encode), write `df.select_dtypes(____=''number'')`.', NULL, NULL, 'exclude', 'select_dtypes takes two keyword arguments: one to keep, one to drop.', 'select_dtypes(include=...) keeps the matching dtypes and select_dtypes(exclude=...) drops them. A quick `df.select_dtypes(exclude=''number'').columns` before training lists the object/category/bool columns a model can''t take raw. Remember bool is not ''number'' here, so bool columns show up in the exclude list.', NULL, NULL, 205);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 2, 'true_false', '`df.iloc[0, ''price'']` reads the price of the first row.', NULL, NULL, 'False', 'iloc wants positions on BOTH axes.', 'iloc is position-only, so a column name raises ValueError. Write df[''price''].iloc[0], df.loc[df.index[0], ''price''], or df.iloc[0, df.columns.get_loc(''price'')]. Mixing a label and a position in one call is a very common first-week bug; pick one system per call.', NULL, NULL, 206);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 3, 'true_false', '`df.at[''r1'', ''price'']` reads one cell faster than `df.loc[''r1'', ''price'']`, but it cannot take slices or lists.', NULL, NULL, 'True', 'at and iat exist for exactly one cell.', 'at (labels) and iat (positions) skip the general indexing machinery that loc/iloc need for slices, lists and masks, so a single read or write is cheaper. Passing a slice to at raises. If you''re calling at in a hot loop, though, the real fix is usually to vectorise the loop.', NULL, NULL, 207);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 3, 'mcq', 'A script builds a frame row by row: `for r in rows: df.loc[len(df)] = r`. With 3,000 rows it takes about 2 seconds; with 100,000 it seems to hang. Why, and what is the fix?', NULL, NULL, 'Each enlargement reallocates and copies the whole frame, so the loop is O(n^2); collect rows in a list and call pd.DataFrame(rows) once', 'A DataFrame''s columns are fixed-size NumPy arrays.', 'NumPy arrays can''t grow in place, so every new row means new arrays plus a copy of all existing rows: quadratic time. Appending dicts to a Python list is O(1) each, and one DataFrame(rows) call builds the arrays once; in a quick test that was about 500x faster for 3,000 rows. iloc can''t enlarge at all (IndexError).', NULL, 'Like running one INSERT per row with a full table rewrite each time, instead of a single bulk insert.', 208);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'loc is slower than iloc; use df.iloc[len(df)] = r', 0), (@q, 'B', 'Each enlargement reallocates and copies the whole frame, so the loop is O(n^2); collect rows in a list and call pd.DataFrame(rows) once', 1), (@q, 'C', 'The index isn''t sorted; call sort_index() inside the loop', 0), (@q, 'D', 'len(df) is slow on big frames; keep a counter instead', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 1, 'true_false', '`df[df[''age''] > 30]` removes the younger rows from df.', NULL, NULL, 'False', 'Did you assign the result anywhere?', 'Boolean filtering returns a NEW DataFrame with the matching rows; df itself keeps every row. Write adults = df[df[''age''] > 30] (or reassign df = ...) to keep the result. Like a SQL SELECT ... WHERE, a filter reads, it doesn''t DELETE.', NULL, NULL, 209);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 3, 'mcq', '`df[df[''name''].str.contains(''a'')]` raises `ValueError: Cannot mask with non-boolean array containing NA / NaN values`. What''s the clean fix?', 'import numpy as np\nimport pandas as pd\ndf = pd.DataFrame({''name'': [''apple'', np.nan, ''kiwi'']})\nprint(df[''name''].str.contains(''a'').tolist())\nprint(df[df[''name''].str.contains(''a'', na=False)])', 'python', 'Pass na=False: df[df[''name''].str.contains(''a'', na=False)]', 'What does str.contains return for a missing name?', 'On an object column, str.contains gives NaN for missing values, and a mask with NaN in it isn''t a valid boolean mask. na=False says ''treat missing as not matching''. dropna() on the whole frame would also throw away rows that are missing in other, unrelated columns.', NULL, NULL, 210);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Use `and` instead of the mask', 0), (@q, 'B', 'Call df.dropna() on the whole frame first', 0), (@q, 'C', 'Pass na=False: df[df[''name''].str.contains(''a'', na=False)]', 1), (@q, 'D', 'Wrap the mask in bool(): df[bool(df[''name''].str.contains(''a''))]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 2, 'mcq', 'After `f = df[df[''v''] > 2]`, the index of f is [0, 2]. Your next line is `f.loc[1]`, meaning ''the second row''. What happens?', NULL, NULL, 'KeyError: label 1 was filtered out; use f.iloc[1] or f.reset_index(drop=True) first', 'Filtering keeps the original row labels.', 'A filter keeps the surviving rows'' labels, leaving gaps (0, 2). loc looks up label 1, which is gone, so it raises KeyError. For ''the nth row'' use iloc; if you want 0..n-1 labels again (for example before concatenating with a NumPy result) call reset_index(drop=True).', 'df            f = df[df.v > 2]\nlabel  v      label  v\n  0    5        0    5    <- iloc[0]\n  1    1        2    7    <- iloc[1]\n  2    7      (label 1 no longer exists)', NULL, 211);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It returns the second row (label 2)', 0), (@q, 'B', 'KeyError: label 1 was filtered out; use f.iloc[1] or f.reset_index(drop=True) first', 1), (@q, 'C', 'It returns an empty DataFrame', 0), (@q, 'D', 'It returns row 1 from the original df', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 3, 'mcq', 'Your API passes a user-supplied city into a filter. Which version should you ship?', 'import pandas as pd\ndf = pd.DataFrame({''city'': ["O''Brien Nagar", ''Pune'']})\ncity = "O''Brien Nagar"\nprint(df.query(''city == @city'').shape)', 'python', 'df.query(''city == @city'')', 'What happens when city is "O''Brien Nagar"?', '@city passes the Python variable as a value, so quotes or odd characters in it can''t break the expression. Pasting the value into the string with an f-string fails on an apostrophe (a tokenizer error) and, like SQL built by string concatenation, lets input change the expression itself. For a plain equality, df[df[''city''] == city] is just as safe.', NULL, '@var is a bound parameter in a prepared SQL statement; the f-string is string-concatenated SQL.', 212);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df.query(f"city == ''{city}''")', 0), (@q, 'B', 'eval(f"df[df.city == ''{city}'']")', 0), (@q, 'C', 'df.query(''city == '' + city)', 0), (@q, 'D', 'df.query(''city == @city'')', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'modifying'), 1, 'mcq', 'Which line removes the column `tmp` from df and keeps the result?', NULL, NULL, 'df = df.drop(columns=''tmp'')', 'Two things to get right: which axis, and keeping the result.', 'drop(columns=...) says you mean a column, and the assignment keeps the new frame. df.drop(''tmp'') looks for a ROW labelled ''tmp'' (KeyError) and throws the result away anyway; del df.tmp tries to delete an attribute (del df[''tmp''] would work).', NULL, NULL, 213);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df.drop(''tmp'')', 0), (@q, 'B', 'df = df.drop(columns=''tmp'')', 1), (@q, 'C', 'df = df.drop(''tmp'')', 0), (@q, 'D', 'del df.tmp', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'modifying'), 2, 'true_false', '`sort_values` puts NaN at the end both when ascending and when `ascending=False`.', NULL, NULL, 'True', 'Missing values don''t take part in the comparison.', 'na_position defaults to ''last'' for both directions, so a descending sort does not bring NaN to the top. Pass na_position=''first'' to change it. This matters for ''top 10'' reports: missing scores never appear in df.sort_values(''score'', ascending=False).head(10), so you may not notice how many there are.', NULL, NULL, 214);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'modifying'), 4, 'mcq', 'Events are already in time order. You run `df.sort_values(''user_id'')` and expect each user''s events to stay in time order. Is that guaranteed?', NULL, NULL, 'No: the default kind=''quicksort'' isn''t stable, so ties can be reordered; pass kind=''stable'' (or sort by [''user_id'', ''ts''])', 'What does ''stable'' mean for rows with equal keys?', 'A stable sort keeps rows with equal keys in their original order. A single-column sort_values uses NumPy quicksort (an introsort), which doesn''t promise that: in a 40-row test with two key values, the tied rows came out shuffled. kind=''stable'' (or ''mergesort'') fixes it; sorting by both keys says what you mean even more clearly. Multi-column sorts are stable already. This bug looks like ''events out of order'' in session features, and it only shows up on larger data.', 'before:  (u1,t1) (u2,t1) (u1,t2) (u1,t3)\nstable:  (u1,t1) (u1,t2) (u1,t3) (u2,t1)\nquick:   (u1,t3) (u1,t1) (u1,t2) (u2,t1)  <- ties shuffled', NULL, 215);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Yes, but only if the index is a RangeIndex', 0), (@q, 'B', 'No: the default kind=''quicksort'' isn''t stable, so ties can be reordered; pass kind=''stable'' (or sort by [''user_id'', ''ts''])', 1), (@q, 'C', 'No, and there is no way to get a stable sort in pandas', 0), (@q, 'D', 'Yes: pandas sorts are always stable', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'modifying'), 2, 'fill_blank', 'To remove rows that are exact repeats of an earlier row, call `df.____()`.', NULL, NULL, 'drop_duplicates', 'drop_... the repeats.', 'drop_duplicates() keeps the first copy of each identical row by default (keep=''first'') and returns a new frame. Pass subset=[''email''] to dedupe on a key instead of on the whole row, like SELECT DISTINCT vs a unique constraint on one column.', NULL, NULL, 216);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 2, 'mcq', '`s` holds ''a'', ''b'', ''c''. You want ''a'' turned into 1 and every other value left alone. Which call does that?', 'import pandas as pd\ns = pd.Series([''a'', ''b'', ''c''])\nprint(s.replace({''a'': 1}).tolist(), s.map({''a'': 1}).tolist())', 'python', 's.replace({''a'': 1})', 'One of these treats the dict as the complete lookup table.', 'replace only changes the values it finds in the dict and keeps the rest, giving [1, ''b'', ''c'']. map treats the dict as the full mapping: any value not in it becomes NaN, so you''d get [1.0, NaN, NaN]. na_action=''ignore'' only skips values that were already missing. Use map for full lookups like encoding labels, and replace for patching a few values.', NULL, NULL, 217);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 's.map({''a'': 1})', 0), (@q, 'B', 's.replace({''a'': 1})', 1), (@q, 'C', 's.map({''a'': 1}, na_action=''ignore'')', 0), (@q, 'D', 's.astype({''a'': 1})', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 3, 'true_false', 'On a default object-dtype column of strings, `s.str.lower()` runs about as fast as numeric vectorised math like `n * 2`, because .str methods are compiled C loops.', NULL, NULL, 'False', 'What is stored in an object column?', 'On object dtype, .str methods still call a Python string method once per element; they''re tidier and NaN-safe, but in a 1M-row test str.lower took about 0.16 s, apply took 0.25 s and n * 2 took 0.007 s. Converting to ''string[pyarrow]'' moved str.lower to about 0.035 s, because Arrow strings have real compiled kernels. So ''use .str instead of apply'' is about clarity first; for big text columns the speed comes from the dtype.', NULL, NULL, 218);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 4, 'mcq', 'You must use `df.apply(f)` column-wise with a custom NumPy-only function. What does `df.apply(f, raw=True)` change?', 'import pandas as pd\ndf = pd.DataFrame({''a'': [1, 2, 3]})\nprint(df.apply(lambda c: type(c).__name__).tolist(), df.apply(lambda c: type(c).__name__, raw=True).tolist())', 'python', 'f receives each column as a plain ndarray instead of a Series, skipping Series construction and index handling, which is often faster', 'What object does f get with and without it?', 'By default apply builds a Series (values + index + name) for every column or row it hands to f. raw=True passes the bare ndarray, which removes that cost and lets f use NumPy directly. f still runs once per column/row in Python, so it is not vectorisation; and f loses access to labels (no row[''age'']). It helps most with axis=1 on many rows, where building one Series per row dominates.', NULL, NULL, 219);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Nothing; raw only affects how the result is printed', 0), (@q, 'B', 'f runs in compiled C instead of Python', 0), (@q, 'C', 'f receives the whole frame at once as a 2-D array', 0), (@q, 'D', 'f receives each column as a plain ndarray instead of a Series, skipping Series construction and index handling, which is often faster', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'index-alignment'), 1, 'mcq', 'What does `df.set_index(''user_id'')` do?', NULL, NULL, 'Returns a new frame where the user_id column becomes the row labels (and is no longer a regular column)', 'Think ''primary key''.', 'set_index moves the column into the index, so you can then look rows up with df.loc[42] and arithmetic aligns on user_id. Like most pandas methods it returns a new frame, so write df = df.set_index(''user_id''). It doesn''t sort; call sort_index() if you need that.', NULL, 'Declaring user_id as the table''s primary key: rows are now addressed by it.', 220);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Adds a user_id column filled with 0, 1, 2, ...', 0), (@q, 'B', 'Sorts df by user_id', 0), (@q, 'C', 'Changes df itself and returns None', 0), (@q, 'D', 'Returns a new frame where the user_id column becomes the row labels (and is no longer a regular column)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'index-alignment'), 3, 'mcq', 'df has index [2, 0, 1]. Which statement about these two assignments is correct?\n`df[''l''] = [10, 20, 30]` and `df[''s''] = pd.Series([10, 20, 30])`', 'import pandas as pd\ndf = pd.DataFrame({''a'': [1, 2, 3]}, index=[2, 0, 1])\ndf[''l''] = [10, 20, 30]\ndf[''s''] = pd.Series([10, 20, 30])\nprint(df)', 'python', 'The list is placed by position; the Series is matched by label, so df[''s''] becomes [30, 10, 20]', 'Only one of the two has labels.', 'A list or ndarray has no index, so it is written top to bottom. A Series brings labels 0, 1, 2, and pandas aligns them with df''s labels 2, 0, 1, so label 2 gets 30. This bites after a sort or a filter: assign model.predict(X) (an ndarray) and it lands by position; assign a Series built elsewhere and it lands by label, with NaN for labels it lacks.', 'label | list (by position) | Series (by label)\n  2   |        10          |   s[2] = 30\n  0   |        20          |   s[0] = 10\n  1   |        30          |   s[1] = 20', NULL, 221);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The list is placed by position; the Series is matched by label, so df[''s''] becomes [30, 10, 20]', 1), (@q, 'B', 'Both are placed by position, giving [10, 20, 30] each', 0), (@q, 'C', 'Both are matched by label', 0), (@q, 'D', 'The Series assignment raises because the index order differs', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'index-alignment'), 3, 'mcq', 'You want to centre each ROW of a numeric df (subtract that row''s mean from every cell). Which line is correct?', NULL, NULL, 'df.sub(df.mean(axis=1), axis=0)', 'By default, a Series is lined up with the columns.', 'df - series matches the Series'' labels against the COLUMN names. Row means are labelled by row (0, 1, ...), so df - df.mean(axis=1) gives an all-NaN frame with extra columns. axis=0 tells sub to match the Series against the index instead. df - df.mean() is valid but centres each column, which is a different thing.', NULL, NULL, 222);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df.sub(df.mean(axis=1))', 0), (@q, 'B', 'df - df.mean()', 0), (@q, 'C', 'df - df.mean(axis=1)', 0), (@q, 'D', 'df.sub(df.mean(axis=1), axis=0)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'index-alignment'), 4, 'fill_blank', 'To get both Series reindexed to their shared labels only (an inner join on the index) in one call, write `a2, b2 = a.____(b, join=''inner'')`.', NULL, NULL, 'align', 'The verb for what pandas does silently before arithmetic.', 'align returns both objects reindexed to a common index: join=''outer'' (union, what + uses), ''inner'', ''left'' or ''right''. Making it explicit lets you check len(a2) and catch a key mismatch before it turns into NaNs, the same way you''d check row counts after a SQL join.', NULL, NULL, 223);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 1, 'true_false', '`df2 = df` makes a copy, so changing df2 leaves df unchanged.', NULL, NULL, 'False', 'Python assignment never copies objects.', 'Assignment only binds a second name to the same object, just like `b = a` with a JS object or a Python list. Any change through df2 is a change to df. Use df2 = df.copy() when you need an independent frame.', NULL, 'Two variables holding the same object reference, like `const b = a` for a JS object.', 224);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 4, 'mcq', 'pandas 2.2 with `pd.options.mode.copy_on_write = True`. You run `df[''a''][0] = 5`. What happens?', NULL, NULL, 'df is unchanged, and pandas emits a ChainedAssignmentError warning telling you to use df.loc[0, ''a''] = 5', 'Under CoW, df[''a''] behaves as a brand-new object.', 'With CoW, df[''a''] acts like a separate Series; writing into it can never reach df, so chained assignment never works. pandas 2.2 detects the pattern and warns with ChainedAssignmentError (a Warning, not an exception). With CoW off, 2.2 still updates df but warns with a FutureWarning that this changes in 3.0. Either way the fix is one indexing call: df.loc[0, ''a''] = 5.', 'df[''a''][0] = 5\n \\_____/ \\___/\n  step 1  step 2: writes into step 1''s result\nCoW: step 1 is a new object -> df never changes\nfix: df.loc[0, ''a''] = 5   (one call, writes to df)', NULL, 225);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df[''a''][0] becomes 5, exactly as with CoW off', 0), (@q, 'B', 'df[''a''] becomes 5 in every row', 0), (@q, 'C', 'It raises SettingWithCopyError and stops the script', 0), (@q, 'D', 'df is unchanged, and pandas emits a ChainedAssignmentError warning telling you to use df.loc[0, ''a''] = 5', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 2, 'mcq', 'A `price` column read from a scraped file holds strings like ''12.5'', ''7'' and ''N/A''. `astype(float)` raises. Which call turns the good values into numbers and the junk into NaN?', 'import pandas as pd\ns = pd.Series([''12.5'', ''7'', ''N/A''])\nprint(pd.to_numeric(s, errors=''coerce'').tolist())', 'python', 'pd.to_numeric(df[''price''], errors=''coerce'')', 'One option means ''force it, and mark failures as missing''.', 'errors=''coerce'' converts what it can and makes unparseable values NaN, giving a float64 column. errors=''raise'' (the default) fails like astype; astype(errors=''ignore'') returns the original strings unchanged. Afterwards, count the new NaNs (and look at a few raw values) so a format change in the source doesn''t quietly turn half the column into NaN.', NULL, NULL, 226);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'pd.to_numeric(df[''price''], errors=''coerce'')', 1), (@q, 'B', 'pd.to_numeric(df[''price''], errors=''raise'')', 0), (@q, 'C', 'df[''price''].astype(float, errors=''ignore'')', 0), (@q, 'D', 'df[''price''].astype(''Int64'')', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 3, 'fill_blank', 'To shrink an int64 column of small numbers to the smallest integer dtype that fits (e.g. int8), call `pd.to_numeric(s, ____=''integer'')`.', NULL, NULL, 'downcast', 'The opposite of upcasting.', 'downcast=''integer'' picks the smallest of int8/int16/int32/int64 that holds every value, so [1, 2, 3] becomes int8: 1 byte per value instead of 8. Unlike astype(''int8''), it checks the range first, so it never wraps large values around. ''float'' and ''unsigned'' work the same way.', NULL, NULL, 227);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 4, 'mcq', '`size` is a plain (unordered) category column with values ''S'', ''M'', ''L''. What does `df[df[''size''] > ''M'']` do?', 'import pandas as pd\nt = pd.CategoricalDtype([''S'', ''M'', ''L''], ordered=True)\ns = pd.Series([''S'', ''L'', ''M'']).astype(t)\nprint((s > ''M'').tolist(), s.sort_values().tolist())', 'python', 'Raises TypeError: unordered categoricals only support == and !=', 'Does pandas know that S < M < L just from the strings?', 'An unordered categorical has no ranking, so <, > and sorting by meaning aren''t defined and pandas raises TypeError. Declare the order: pd.CategoricalDtype([''S'', ''M'', ''L''], ordered=True). Then > ''M'' keeps L, and sort_values sorts S, M, L instead of alphabetically (L, M, S). The same idea is useful for ordinal features like education level.', NULL, NULL, 228);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Returns an empty frame', 0), (@q, 'B', 'Keeps rows that sort after ''M'' alphabetically (''S'')', 0), (@q, 'C', 'Raises TypeError: unordered categoricals only support == and !=', 1), (@q, 'D', 'Keeps ''L'' rows, because pandas knows S < M < L', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 3, 'true_false', '`df.groupby([''city'', ''year''])[''sales''].sum()` returns a Series whose index is a MultiIndex of (city, year) pairs.', NULL, NULL, 'True', 'Each result row needs both keys to identify it.', 'Grouping by two keys gives one result per (city, year) combination, so pandas labels the result with a two-level index. That''s why m.loc[''Pune''] works on it afterwards. If you want flat columns (for a CSV, a chart or a model), call .reset_index() or pass as_index=False to groupby.', 'groupby([''city'',''year'']).sum()\ncity  year    sales\nGoa   2023      3\n      2024      1\nPune  2024      2\n(city, year) = 2-level row labels', NULL, 229);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-features'), 3, 'mcq', 'Training used `pd.get_dummies(train)` on a `city` column with Goa, Pune and Delhi. At serving time a request batch contains only Pune. What goes wrong?', NULL, NULL, 'The batch gets only a city_Pune column, so the columns don''t match the model; reindex to the saved training columns with fill_value=0', 'get_dummies only sees the data you pass it right now.', 'get_dummies makes one column per value present in THIS frame, so a small batch produces fewer (and differently ordered) columns, and scikit-learn rejects it (or, with NumPy input, silently misreads it). Save train_cols = X_train.columns and do X.reindex(columns=train_cols, fill_value=0), or use a fitted OneHotEncoder(handle_unknown=''ignore''), which keeps the training categories.', NULL, 'Like an API whose response schema changes depending on which rows the query happened to return.', 230);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The batch gets all three columns but filled with NaN', 0), (@q, 'B', 'The batch gets only a city_Pune column, so the columns don''t match the model; reindex to the saved training columns with fill_value=0', 1), (@q, 'C', 'get_dummies raises because Goa and Delhi are missing', 0), (@q, 'D', 'Nothing; get_dummies remembers the training categories', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-features'), 4, 'mcq', 'Before splitting, a notebook runs `df[''age''] = df[''age''].fillna(df[''age''].mean())`, then `train_test_split`. What is the problem?', NULL, NULL, 'Leakage: the mean includes the test rows, so test data influences training; compute the mean on the training split only and reuse it for test', 'Which rows went into that mean?', 'Any statistic you learn from the data (means, scaler parameters, category lists) must be fitted on the training split only and then applied to the test split, or your test score is optimistic. Here the effect is small, but the same pattern with target encoding or scaling can inflate metrics a lot. In practice, put SimpleImputer in a Pipeline so fit only ever sees training data.', 'wrong:  mean(all rows) -> fill -> split\n                  ^ test rows leak in\nright:  split -> m = mean(train)\n               -> train.fillna(m), test.fillna(m)', NULL, 231);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'fillna doesn''t work before a split', 0), (@q, 'B', 'None; the mean is the same either way', 0), (@q, 'C', 'Leakage: the mean includes the test rows, so test data influences training; compute the mean on the training split only and reuse it for test', 1), (@q, 'D', 'It changes the dtype of age to object', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-features'), 2, 'true_false', '`X = df[[''b'', ''a'']]` gives X with columns in the order b, a, even if df stores them as a, b.', NULL, NULL, 'True', 'The list you pass is a request, in order.', 'Selecting with a list returns the columns in the list''s order. That makes df[train_cols] a simple way to force serving data into the training column order. It also means a hand-typed list in a different order quietly gives a different X.', NULL, NULL, 232);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-features'), 4, 'mcq', 'A team encodes city as `X[''city''] = X[''city''].astype(''category'').cat.codes`, separately on the training data (Goa, Pune) and on each serving batch. Why do predictions go wrong?', 'import pandas as pd\ntrain = pd.Series([''Goa'', ''Pune'']).astype(''category'').cat.codes.tolist()\nbatch = pd.Series([''Pune'']).astype(''category'').cat.codes.tolist()\nprint(train, batch)', 'python', 'Codes depend on which values are in each frame: in a batch of only Pune, Pune gets code 0, which meant Goa in training', 'Codes come from the sorted list of categories found in that frame.', 'astype(''category'') builds its category list from the values present, so the same city can get different codes in different frames. Nothing raises; the model just reads the wrong city. Save the training categories and reuse them: astype(pd.CategoricalDtype(train_cats)). An unseen city then gets code -1, which you can handle on purpose.', 'train:  Goa -> 0   Pune -> 1\nbatch:  Pune -> 0          (only Pune present)\nmodel reads 0 as Goa  -> wrong feature, no error\nfix:    astype(CategoricalDtype([''Goa'', ''Pune'']))', NULL, 233);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'cat.codes returns strings, which models can''t use', 0), (@q, 'B', 'Codes are random on every run', 0), (@q, 'C', 'astype(''category'') drops rows that are new', 0), (@q, 'D', 'Codes depend on which values are in each frame: in a batch of only Pune, Pune gets code 0, which meant Goa in training', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 4, 'mcq', 'pandas 2.2: `s = pd.Series([1, None], dtype=''Int64'')`. What does `s.to_numpy()` return?', 'import pandas as pd\ns = pd.Series([1, None], dtype=''Int64'')\nprint(s.to_numpy(), s.to_numpy().dtype)', 'python', 'A float64 array [1.0, nan]', 'This changed in pandas 2.2.', 'Since 2.2, to_numpy() on nullable numeric dtypes picks a matching NumPy dtype: int64 when nothing is missing, float64 with NaN when something is. Before 2.2 it gave an object array of pd.NA, which broke NumPy and scikit-learn code. Nullable boolean with a missing value still gives object. In shared code, be explicit: s.to_numpy(dtype=''float64'', na_value=np.nan).', NULL, NULL, 234);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'An object array [1, <NA>]', 0), (@q, 'B', 'It raises because pd.NA can''t go into NumPy', 0), (@q, 'C', 'An int64 array, with the missing value as 0', 0), (@q, 'D', 'A float64 array [1.0, nan]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inspecting'), 1, 'mcq', 'Which call shows the LAST 3 rows of a DataFrame?', NULL, NULL, 'df.tail(3)', 'head looks at the top; what looks at the bottom?', 'tail(n) returns the last n rows, the mirror of head(n). head(-3) means ''everything EXCEPT the last 3 rows'', the opposite of what you want. df[-3] looks for a COLUMN labelled -3 and raises KeyError, and iloc[3] is the single row at position 3. Checking the tail of a freshly loaded file catches footer junk like ''Total'' rows or a truncated last line.', NULL, NULL, 235);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df.tail(3)', 1), (@q, 'B', 'df.iloc[3]', 0), (@q, 'C', 'df[-3]', 0), (@q, 'D', 'df.head(-3)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'series-vs-df'), 1, 'true_false', '`df[''price''].mean()` returns a single number, not a Series.', NULL, NULL, 'True', 'One column in, one summary out.', 'df[''price''] is a Series, and reducing a Series with mean(), sum() or max() gives one scalar (a NumPy float64). Calling df.mean(numeric_only=True) on the whole DataFrame instead returns a Series: one mean per column, indexed by column name. Knowing which one you have tells you whether you can format it with f''{x:.2f}'' or need to pick a column first.', NULL, NULL, 236);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'selecting'), 1, 'fill_blank', 'To see the column names of a DataFrame, look at `df.____` (no parentheses).', NULL, NULL, 'columns', 'It''s an attribute, the column counterpart of df.index.', 'df.columns is an Index object holding the column labels; df.columns.tolist() gives a plain list. It''s also assignable: df.columns = [''a'', ''b''] renames every column at once (the list must have the right length). Printing it right after loading catches stray spaces like ''price '' that make df[''price''] raise KeyError.', NULL, NULL, 237);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'modifying'), 1, 'mcq', 'How do you rename the column `amt` to `amount` and keep the result?', NULL, NULL, 'df = df.rename(columns={''amt'': ''amount''})', 'A dict maps OLD name to NEW name, and the method returns a new frame.', 'rename takes a mapping {old: new} passed as columns=, and returns a new DataFrame that you assign back. The second option raises TypeError (rename takes a mapping, not two names), and even a valid call there would throw its result away. The last option has the mapping backwards and, without columns=, tries to rename ROW labels, so nothing visible happens. Like ALTER TABLE ... RENAME COLUMN, except pandas gives you a new table instead of changing the old one.', NULL, NULL, 238);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df = df.rename(columns={''amt'': ''amount''})', 1), (@q, 'B', 'df[''amount''] = df.rename(''amt'')', 0), (@q, 'C', 'df = df.rename({''amount'': ''amt''})', 0), (@q, 'D', 'df.rename(''amt'', ''amount'')', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 1, 'mcq', 'Which line keeps every row whose city is NOT ''Pune''?', NULL, NULL, 'df[df[''city''] != ''Pune'']', 'Comparison operators work element-wise on a column.', '!= compares every value and returns a True/False mask; df[mask] keeps the True rows. ''is not'' checks whether the whole Series is the same object as the string (always True), so it''s not a mask at all. ''not'' tries to turn the whole Series into one bool and raises ValueError. drop(''Pune'') looks for a row LABEL ''Pune''. SQL: WHERE city <> ''Pune'' (careful: rows where city is NaN are kept by != but dropped by SQL''s <>).', NULL, NULL, 239);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df[not df[''city''] == ''Pune'']', 0), (@q, 'B', 'df.drop(''Pune'')', 0), (@q, 'C', 'df[df[''city''] is not ''Pune'']', 0), (@q, 'D', 'df[df[''city''] != ''Pune'']', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 1, 'mcq', 'You save a cleaned DataFrame with `df.to_csv(''clean.csv'')` and load it back. There''s a new column `Unnamed: 0`. How do you avoid it?', NULL, NULL, 'Save with df.to_csv(''clean.csv'', index=False), since the 0..n-1 index isn''t real data', 'to_csv writes one extra thing by default.', 'to_csv writes the index as the first column by default, with an empty header, and read_csv names that column ''Unnamed: 0''. index=False skips it. If the index IS meaningful (user ids), keep it and load with index_col=0 instead. header=None would treat the header row as data. Many ''mystery feature'' columns in ML datasets are just a saved RangeIndex.', NULL, NULL, 240);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It''s a bug in read_csv; upgrade pandas', 0), (@q, 'B', 'Save with df.to_csv(''clean.csv'', index=False), since the 0..n-1 index isn''t real data', 1), (@q, 'C', 'Rename the column after loading every time', 0), (@q, 'D', 'Load with pd.read_csv(''clean.csv'', header=None)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 1, 'true_false', '`df.iloc[0]` returns the first row of the table even when the index labels are something like [105, 7, 42].', NULL, NULL, 'True', 'iloc never looks at labels.', 'iloc is purely positional: position 0 is whatever row is physically first, here the one labelled 105. df.loc[0] would look for the LABEL 0 and raise KeyError on this index. After sorting or filtering, labels and positions no longer agree, so choose deliberately: loc for ''the row with id 42'', iloc for ''the first row''.', 'position:   0     1    2\nlabel:     105    7   42\niloc[0] -> position 0 -> row 105\nloc[0]  -> label 0    -> KeyError', NULL, 241);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 1, 'mcq', 'You need a `price_with_tax` column equal to price x 1.18 for 2 million rows. Which is the idiomatic pandas way?', NULL, NULL, 'df[''price_with_tax''] = df[''price''] * 1.18', 'Let the whole column do the math at once.', 'Arithmetic on a Series is vectorised: one compiled loop over the whole array, typically 50-100x faster than Python-level loops. The list comprehension and apply call Python once per value, and the loc loop is the slowest of all, since every assignment goes through indexing machinery. Like one UPDATE t SET price_with_tax = price * 1.18 instead of 2 million single-row updates.', NULL, NULL, 242);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df[''price_with_tax''] = df[''price''] * 1.18', 1), (@q, 'B', 'for i in range(len(df)): df.loc[i, ''price_with_tax''] = df.loc[i, ''price''] * 1.18', 0), (@q, 'C', 'df[''price_with_tax''] = [p * 1.18 for p in df[''price'']]', 0), (@q, 'D', 'df[''price_with_tax''] = df[''price''].apply(lambda p: p * 1.18)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'index-alignment'), 1, 'mcq', 'You build `pd.DataFrame({''a'': [5, 6, 7]})` without giving an index. What are the row labels?', NULL, NULL, '0, 1, 2: a RangeIndex', 'pandas numbers rows the way Python numbers list items.', 'Without index=, pandas creates a RangeIndex starting at 0. It''s cheap (stored as start/stop/step, not as an array) and it''s what df.reset_index(drop=True) gives you back. Every row always has a label. That label, not the position, is what pandas uses to line up rows in arithmetic and assignment, which is the source of many surprises later.', NULL, NULL, 243);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '5, 6, 7, taken from the first column', 0), (@q, 'B', '1, 2, 3', 0), (@q, 'C', '0, 1, 2: a RangeIndex', 1), (@q, 'D', 'There are no row labels', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 1, 'fill_blank', 'To see the dtype of every column at once (int64, float64, object...), look at `df.____`.', NULL, NULL, 'dtypes', 'Plural of dtype.', 'df.dtypes is a Series mapping each column name to its dtype; s.dtype (singular) is for one Series. df.info() shows the same plus non-null counts and memory. Check it right after loading: a numeric column that shows object usually hides a stray string like ''N/A'' or ''1,200''.', NULL, NULL, 244);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inspecting'), 2, 'mcq', 'A CSV export is sorted by signup date. Why is `df.sample(10, random_state=0)` a better first look than `df.head(10)`?', NULL, NULL, 'head only shows the oldest rows, which can hide problems that appear later in the file; sample draws rows from everywhere, and random_state makes it repeatable', 'What do the first 10 rows of a sorted file have in common?', 'In a file sorted by date, id or region, the top rows are not representative: a format change in 2024, a new category or a column that only fills in later won''t show in head(). sample picks random rows, and random_state=0 gives the same rows on every run, so a notebook stays reproducible. It''s like checking a few random log lines from across the day instead of only the first minute after a deploy.', NULL, NULL, 245);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'head only shows the oldest rows, which can hide problems that appear later in the file; sample draws rows from everywhere, and random_state makes it repeatable', 1), (@q, 'B', 'sample is faster than head', 0), (@q, 'C', 'sample returns the 10 most typical rows', 0), (@q, 'D', 'head modifies the DataFrame', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'selecting'), 2, 'mcq', 'A config lists optional columns. What does `df.get(''discount'')` return when df has no ''discount'' column?', NULL, NULL, 'None (or the default you pass as the second argument), instead of raising KeyError', 'DataFrame behaves like a dict of columns here.', 'DataFrame.get works like dict.get: it returns the column if it exists, otherwise None or the default you pass (df.get(''discount'', 0)). df[''discount''] raises KeyError. Handy for optional fields in loosely structured data, but in a training pipeline a missing feature column should usually fail loudly rather than silently become None.', NULL, NULL, 246);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'None (or the default you pass as the second argument), instead of raising KeyError', 1), (@q, 'B', 'A column of NaN', 0), (@q, 'C', 'An empty Series', 0), (@q, 'D', 'KeyError, like df[''discount'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 2, 'mcq', 'Which line selects columns `b` and `c` only for the rows where `a > 1`?', NULL, NULL, 'df.loc[df[''a''] > 1, [''b'', ''c'']]', 'loc takes [rows, columns], and the row part can be a mask.', 'loc accepts a boolean mask for rows and a list of labels for columns in one call. That''s one clean selection, and the same form (df.loc[mask, ''b''] = 0) is the safe way to ASSIGN. iloc takes positions, not names. Plain df[...] with a tuple looks for a column called (mask, list). The last option has rows and columns swapped. SQL: SELECT b, c FROM df WHERE a > 1.', NULL, NULL, 247);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df.loc[df[''a''] > 1, [''b'', ''c'']]', 1), (@q, 'B', 'df[df[''a''] > 1, [''b'', ''c'']]', 0), (@q, 'C', 'df.iloc[df[''a''] > 1, [''b'', ''c'']]', 0), (@q, 'D', 'df.loc[[''b'', ''c''], df[''a''] > 1]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 2, 'true_false', '`df[df[''email''] != None]` keeps only the rows that have an email.', 'import pandas as pd\ne = pd.Series([''a@x'', None, ''b@x''])\nprint((e != None).tolist(), e.notna().tolist())', 'python', 'False', 'How does pandas compare values to None?', 'pandas treats None in a comparison like a missing value, so every element compares as ''not equal'' and the mask is all True: you keep every row, including the missing ones. (== None gives all False.) Use df[df[''email''].notna()]. The same goes for == np.nan. Missing values are tested with isna/notna, just as SQL needs IS NULL instead of = NULL.', NULL, NULL, 248);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'modifying'), 2, 'mcq', 'A city column mixes old and new names. Which line turns every ''Bombay'' into ''Mumbai'' and leaves other values alone?', NULL, NULL, 'df[''city''] = df[''city''].replace({''Bombay'': ''Mumbai''})', 'One of these turns every unmapped value into NaN.', 'replace swaps only the values found in the dict and keeps everything else. map with a dict looks up EVERY value, so all cities not in the dict become NaN, a classic data-loss bug. rename changes index labels, not values. The last line computes a result but never assigns it (and it would also change ''Bombay Central'' inside longer strings). Use map when the dict covers every value (encoding), replace when it''s a partial fix-up.', NULL, NULL, 249);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df[''city''] = df[''city''].replace({''Bombay'': ''Mumbai''})', 1), (@q, 'B', 'df[''city''] = df[''city''].map({''Bombay'': ''Mumbai''})', 0), (@q, 'C', 'df[''city''].str.replace(''Bombay'', ''Mumbai'')', 0), (@q, 'D', 'df[''city''] = df[''city''].rename({''Bombay'': ''Mumbai''})', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 2, 'fill_blank', 'To label each temperature in one vectorised call, write `df[''band''] = np.____(df[''t''] > 30, ''hot'', ''ok'')`.', NULL, NULL, 'where', 'NumPy''s element-wise if/else.', 'np.where(condition, value_if_true, value_if_false) evaluates the condition for every row at once and picks one of the two values, replacing an apply with an if/else inside. For more than two outcomes, use np.select with a list of conditions. It''s the CASE WHEN t > 30 THEN ''hot'' ELSE ''ok'' END of pandas.', NULL, NULL, 250);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'index-alignment'), 2, 'true_false', 'After `df = df.set_index(''user_id'')`, `user_id` is still available as a normal column too.', NULL, NULL, 'False', 'Check the drop= default of set_index.', 'set_index moves the column into the index (drop=True by default), so df[''user_id''] now raises KeyError. You reach it as df.index or with df.loc[42]. Pass drop=False to keep a copy as a column, or reset_index() to move it back. Code that later does df[''user_id''] or merge(on=''user_id'') breaks after this, so many teams keep ids as columns and only set an index where they need fast label lookups.', NULL, NULL, 251);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 2, 'mcq', 'A 50-million-row feature frame has 40 float64 columns. Roughly how much memory do you save by converting them all to float32?', NULL, NULL, 'About half: each value goes from 8 bytes to 4, so roughly 16 GB becomes 8 GB', 'float64 = 64 bits; float32 = 32 bits.', 'Numeric columns are plain arrays: 50M rows x 40 columns x 8 bytes is about 16 GB, and float32 halves that. You lose precision (about 7 significant digits instead of 15-16), which is usually fine for model features (many GPU frameworks train in float32 anyway) but not for money or ids. The conversion briefly needs both copies in memory, so convert column by column or set dtype= at load time.', NULL, NULL, 252);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Nothing, because pandas stores floats compressed', 0), (@q, 'B', 'It doubles memory because of the conversion', 0), (@q, 'C', 'About 90%', 0), (@q, 'D', 'About half: each value goes from 8 bytes to 4, so roughly 16 GB becomes 8 GB', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-features'), 2, 'mcq', 'Why do you usually drop a `user_id` column from X before training, even though it''s numeric?', NULL, NULL, 'An id is an arbitrary label: the model may learn spurious patterns (for example, later signups have bigger ids), which won''t generalise to new users', 'Does user 50,001 have ''1 more'' of anything than user 50,000?', 'The numeric value of an id carries no meaning, but it often correlates with time (auto-increment) or source system, so a tree model can split on it and look good offline. New users at serving time have ids outside the training range. Keep the id in the DataFrame for joining and debugging, but build X with df.drop(columns=[''user_id'', ''target'']) or an explicit feature list.', NULL, NULL, 253);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Dropping columns makes training more accurate in general', 0), (@q, 'B', 'ids always contain missing values', 0), (@q, 'C', 'scikit-learn refuses integer columns', 0), (@q, 'D', 'An id is an arbitrary label: the model may learn spurious patterns (for example, later signups have bigger ids), which won''t generalise to new users', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 2, 'true_false', '`pd.read_csv` turns a column of ISO dates like ''2024-01-15'' into datetime64 automatically.', 'import io\nimport pandas as pd\ncsv = ''signup\\n2024-01-15''\nprint(pd.read_csv(io.StringIO(csv)).dtypes.iloc[0], pd.read_csv(io.StringIO(csv), parse_dates=[''signup'']).dtypes.iloc[0])', 'python', 'False', 'Check df.dtypes after loading.', 'By default read_csv leaves date strings as object; you have to ask: pd.read_csv(path, parse_dates=[''signup'']) (plus date_format= when you know the format), or convert afterwards with pd.to_datetime. Until then, .dt raises AttributeError and comparisons like df[''signup''] > ''2024-01-01'' compare strings, which only works by luck for ISO formats.', NULL, NULL, 254);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 3, 'mcq', 'With copy-on-write on (opt-in in pandas 2.2, the default in 3.0), a helper receives `df`. Which change inside the helper is STILL visible to the caller?', 'import pandas as pd\nwith pd.option_context(''mode.copy_on_write'', True):\n    df = pd.DataFrame({''a'': [1, 2]})\n    sub = df[[''a'']]\n    sub.loc[0, ''a''] = 99\n    df[''x''] = 1\n    print(df[''a''].tolist(), df.columns.tolist())', 'python', 'df[''x''] = 1 on the df argument itself, because the caller holds the very same object', 'CoW is about objects DERIVED from df, not about df itself.', 'Copy-on-write guarantees that any object you derive from df (a selection, a method result) behaves as an independent copy, so writing to sub or d2 never touches df. But the argument df is the caller''s object, not a derived one, so adding or changing a column on it mutates the caller''s frame, exactly like a list passed into a function. So under CoW the defensive df = df.copy() at the top of every helper is mostly unnecessary, and costs memory. The clean style is to not mutate inputs at all: return df.assign(x=1).', NULL, 'Like passing a JavaScript object into a function: reassigning or spreading it is safe, but setting obj.x = 1 changes the caller''s object.', 255);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'sub = df[[''a'']]; sub.loc[0, ''a''] = 99', 0), (@q, 'B', 'df[''x''] = 1 on the df argument itself, because the caller holds the very same object', 1), (@q, 'C', 'None of them; CoW makes every function argument a private copy', 0), (@q, 'D', 'd2 = df.reset_index(drop=True); d2.loc[0, ''a''] = 99', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 3, 'true_false', '`df.loc[df[''a''] > 1, ''flag''] = 1` on a frame without a `flag` column creates it, with NaN in the rows where the mask is False.', 'import pandas as pd\ndf = pd.DataFrame({''a'': [1, 2, 3]})\ndf.loc[df[''a''] > 1, ''flag''] = 1\nprint(df[''flag''].tolist(), df[''flag''].dtype)', 'python', 'True', 'Only some rows get a value. What do the others hold?', 'Assigning through loc to a new column label creates the column; rows outside the mask have no value, so they get NaN, and the NaN makes the column float64 (1.0 rather than 1). If you want 0/1 flags, initialise first (df[''flag''] = 0, then the loc assignment) or write it in one go: df[''flag''] = (df[''a''] > 1).astype(int).', NULL, NULL, 256);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 3, 'mcq', 'You compute `m = f[''v''] > 2` on a FILTERED frame `f = df[df[''v''] > 1]` and then run `df[m]` on the original. What happens in pandas 2.2?', NULL, NULL, 'It raises IndexingError (''Unalignable boolean Series''), because the mask has no entry for some of df''s labels', 'A boolean Series mask is matched to rows by LABEL.', 'pandas aligns a boolean Series to the frame''s index. m has labels only for the rows that survived the first filter, so labels in df that are missing from m can''t be decided, and pandas raises IndexingError (after a UserWarning about reindexing). It never silently treats missing labels as False. Fix it by building the mask on the same frame you filter, or combine conditions up front: df[(df[''v''] > 1) & (df[''v''] > 2)].', NULL, NULL, 257);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It raises IndexingError (''Unalignable boolean Series''), because the mask has no entry for some of df''s labels', 1), (@q, 'B', 'It keeps the first len(m) rows of df', 0), (@q, 'C', 'It works because masks are applied by position', 0), (@q, 'D', 'It fills the missing mask labels with False and works silently', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 3, 'mcq', '`codes` is a Series of ''P'', ''G''. `lookup = pd.Series({''P'': ''Pune'', ''G'': ''Goa''})`. What does `codes.map(lookup)` do?', 'import pandas as pd\nlookup = pd.Series({''P'': ''Pune'', ''G'': ''Goa''})\nprint(pd.Series([''G'', ''P'', ''X'']).map(lookup).tolist())', 'python', 'Uses lookup''s INDEX as the keys and its values as results, like a dict, giving ''Pune''/''Goa'', and NaN for codes not in the index', 'A Series is a labelled mapping, just like a dict.', 'map accepts a dict, a function or a Series. With a Series it matches each value against lookup''s index and returns the matching value, so a dimension table stored as a Series (indexed by code) works as a fast lookup. Unknown codes become NaN, as with a dict. It''s a one-column LEFT JOIN: df[''city''] = df[''code''].map(cities.set_index(''code'')[''name'']). If the lookup index has duplicates, map raises (InvalidIndexError), unlike merge, which would duplicate rows.', NULL, NULL, 258);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Uses lookup''s INDEX as the keys and its values as results, like a dict, giving ''Pune''/''Goa'', and NaN for codes not in the index', 1), (@q, 'B', 'Raises TypeError, because map only accepts dicts and functions', 0), (@q, 'C', 'Pairs codes and lookup by position', 0), (@q, 'D', 'Returns lookup unchanged', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'index-alignment'), 3, 'true_false', 'Adding two DataFrames with columns [''x'', ''y''] and [''y'', ''z''] gives a result with columns x, y and z, where x and z are all NaN.', 'import pandas as pd\na = pd.DataFrame({''x'': [1], ''y'': [2]})\nb = pd.DataFrame({''y'': [10], ''z'': [20]})\nprint((a + b).columns.tolist(), (a + b).values.tolist())', 'python', 'True', 'Alignment happens on BOTH axes.', 'DataFrame arithmetic aligns rows by index and columns by name, taking the union of both. Only y exists in both frames, so only y gets numbers; x and z have a partner missing and become NaN. Use a.add(b, fill_value=0) to treat the missing side as 0, or select the shared columns first. In a feature pipeline this silently turns typos in column names into NaN columns.', NULL, NULL, 259);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 3, 'fill_blank', 'To get Arrow-backed result dtypes like int64[pyarrow] and string[pyarrow] straight from read_csv (not just the Arrow parser), pass `pd.read_csv(path, ____=''pyarrow'')`.', NULL, NULL, 'dtype_backend', 'It chooses the backend of the dtypes, not the engine.', 'dtype_backend=''pyarrow'' makes every column an Arrow-backed dtype: integers with missing values stay integers, and strings are stored compactly. dtype_backend=''numpy_nullable'' gives Int64/string/boolean instead. engine=''pyarrow'' is a different option: it only swaps in a faster multithreaded parser, and by default still returns NumPy dtypes. You can combine both for large files.', NULL, NULL, 260);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 3, 'mcq', '`s` is a sales Series with a (city, year) MultiIndex. Which line gives total sales per year across all cities?', 'import pandas as pd\ns = pd.DataFrame({''city'': [''P'', ''P'', ''G''], ''year'': [2023, 2024, 2024], ''v'': [1, 2, 3]}).set_index([''city'', ''year''])[''v'']\nprint(s.groupby(level=''year'').sum().to_dict())', 'python', 's.groupby(level=''year'').sum()', 'Group by an index level instead of a column.', 'groupby(level=...) groups by one level of the index, here year, and sums over the other level. sum(axis=...) on a Series has only one axis. s.loc[''year''] looks for a CITY called ''year''. s.unstack().sum() puts years in columns and sums each column, so it gives the same numbers but takes a detour and builds a wide table first. SQL: SELECT year, SUM(sales) FROM t GROUP BY year.', NULL, NULL, 261);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 's.unstack().sum()', 0), (@q, 'B', 's.loc[''year''].sum()', 0), (@q, 'C', 's.groupby(level=''year'').sum()', 1), (@q, 'D', 's.sum(axis=''year'')', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inspecting'), 3, 'mcq', 'A new dataset has 300 columns. Why is `df.nunique().sort_values()` a useful early check?', NULL, NULL, 'Columns with 1 distinct value carry no information, and columns with about as many distinct values as rows are ids or free text; both usually need dropping or special handling', 'Think about both ends of the sorted list.', 'nunique per column (NaN excluded by default) shows the cardinality profile at a glance. 1 means a constant column, useless to a model. Close to len(df) means an id, timestamp or free text, which leaks or overfits if used as a category. Low counts are candidates for category dtype or one-hot encoding. It''s the pandas version of SELECT COUNT(DISTINCT col) for every column of a new table.', 'col          nunique\ncountry           1   <- constant: drop\nplan              4   <- category / one-hot\nage              70   <- numeric feature\nuser_id     100000    <- id: not a feature (rows = 100000)', NULL, 262);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It finds duplicate rows', 0), (@q, 'B', 'Columns with 1 distinct value carry no information, and columns with about as many distinct values as rows are ids or free text; both usually need dropping or special handling', 1), (@q, 'C', 'It shows which columns are numeric', 0), (@q, 'D', 'It counts the missing values per column', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 3, 'mcq', '`pd.DataFrame({''a'': 1, ''b'': 2})` raises ValueError: ''If using all scalar values, you must pass an index''. Why, and what''s the fix?', NULL, NULL, 'With only scalars pandas can''t tell how many rows to make; pass index=[0], or wrap it as a list of one record: pd.DataFrame([{''a'': 1, ''b'': 2}])', 'A scalar can be broadcast, but to what length?', 'Scalars are broadcast to the length of the other columns. When EVERY value is a scalar, there''s no length to broadcast to, so pandas asks for an index. A list of dicts (one per row) is the natural shape for a single JSON record, for example a serving request. pd.DataFrame([payload]) is the usual one-liner for turning one API request into a one-row feature frame.', NULL, NULL, 263);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Dicts can''t be used to build DataFrames', 0), (@q, 'B', 'With only scalars pandas can''t tell how many rows to make; pass index=[0], or wrap it as a list of one record: pd.DataFrame([{''a'': 1, ''b'': 2}])', 1), (@q, 'C', 'Column values must always be strings', 0), (@q, 'D', 'The column names must be integers', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'selecting'), 3, 'fill_blank', 'To keep only the columns whose names start with ''feat_'', write `df.filter(____=''^feat_'')`.', NULL, NULL, 'regex', 'filter can match names by substring, by exact list or by pattern.', 'DataFrame.filter selects COLUMNS (or rows with axis=0) by label: items= for an exact list, like= for a substring, regex= for a pattern. It never looks at the values, despite the name. A naming convention like feat_* plus filter(regex=...) is a cheap way to keep the feature list in sync with the frame, though an explicit saved list of training columns is safer for serving.', NULL, NULL, 264);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 4, 'mcq', 'You take `s = df[''a'']`, then write `df.loc[0, ''a''] = 9`. What is `s` afterwards in pandas 2.2 with default settings, and with copy-on-write on?', 'import pandas as pd\ndf = pd.DataFrame({''a'': [1, 2, 3]})\ns = df[''a'']\ndf.loc[0, ''a''] = 9\nwith pd.option_context(''mode.copy_on_write'', True):\n    df2 = pd.DataFrame({''a'': [1, 2, 3]})\n    s2 = df2[''a'']\n    df2.loc[0, ''a''] = 9\n    print(s.tolist(), s2.tolist())', 'python', '[9, 2, 3] by default (s is a view on df''s memory), [1, 2, 3] with CoW (the write to df makes df copy first, so s keeps the old data)', 'CoW protects in BOTH directions: parent to child and child to parent.', 'Without CoW, selecting a column returns a Series that shares memory with df, so an in-place write to df shows through s (and vice versa). With CoW, df and s share memory only until one of them is written to. The write to df first copies the data, so s keeps the snapshot it was created with. Code that keeps a reference to a column and relies on it ''updating itself'' silently breaks when you upgrade to pandas 3.0. Re-select the column after changes instead of caching it.', 'before write:   df[''a''] --\\\n                           >--  [1, 2, 3]   (shared buffer)\n                s ---------/\ndefault 2.2:    df.loc[0,''a'']=9 writes the shared buffer -> s sees 9\nCoW:            df copies first -> df [9,2,3], s still [1,2,3]', 'Like a git branch: both point at the same commit until one side commits a change.', 265);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[9, 2, 3] by default (s is a view on df''s memory), [1, 2, 3] with CoW (the write to df makes df copy first, so s keeps the old data)', 1), (@q, 'B', '[9, 2, 3] in both cases', 0), (@q, 'C', '[1, 2, 3] by default, [9, 2, 3] with CoW', 0), (@q, 'D', '[1, 2, 3] in both cases', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 4, 'mcq', 'A `country` column with 200 distinct values over 10 million rows is converted to `category`. What dtype are the codes, and why does that matter?', 'import pandas as pd\nprint(pd.Categorical([str(i) for i in range(126)]).codes.dtype, pd.Categorical([str(i) for i in range(200)]).codes.dtype)', 'python', 'int16: pandas picks the smallest signed integer that fits (int8 only for fewer than 127 categories, since -1 is kept for NaN), so 10M rows cost about 20 MB of codes', 'Signed int8 tops out at 127, and one code is reserved.', 'Codes are signed so that -1 can mean missing. int8 is used only up to 126 categories, int16 up to 32,766, then int32. 200 categories therefore cost 2 bytes per row plus one small array of the 200 strings, compared with roughly 50-60 bytes per row for object strings. Past a few hundred thousand distinct values the codes reach int32 and the categories array itself gets big, so the savings shrink. Categoricals pay off for low-cardinality columns, not for ids.', NULL, NULL, 266);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'int64, like every pandas integer', 0), (@q, 'B', 'int16: pandas picks the smallest signed integer that fits (int8 only for fewer than 127 categories, since -1 is kept for NaN), so 10M rows cost about 20 MB of codes', 1), (@q, 'C', 'int8, because there are fewer than 256 categories', 0), (@q, 'D', 'object, because the categories are strings', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'modifying'), 4, 'mcq', '`df[''qty'']` is int64. In pandas 2.2 you run `df.loc[:, ''qty''] = [1.5, 2.5]`. What happens, and how does it differ from `df[''qty''] = [1.5, 2.5]`?', NULL, NULL, 'loc tries to write into the existing int64 column: 2.2 upcasts it to float64 with a FutureWarning (''Setting an item of incompatible dtype is deprecated''), and pandas 3.0 raises; df[''qty''] = ... simply replaces the column with a new float64 one', 'One form means ''set these values in the existing array'', the other ''swap in a new column''.', 'df.loc[:, col] = values is an in-place setitem that has to respect the existing dtype. Silently changing the dtype is being phased out (PDEP-6): 2.2 still upcasts but warns, and 3.0 raises instead. df[col] = values replaces the whole column, so the new dtype is simply float64 with no warning. When you mean to change the type, say so: df[''qty''] = df[''qty''].astype(float) before the partial write, or assign the whole column.', NULL, NULL, 267);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'loc replaces the column; df[''qty''] = ... writes in place', 0), (@q, 'B', 'loc tries to write into the existing int64 column: 2.2 upcasts it to float64 with a FutureWarning (''Setting an item of incompatible dtype is deprecated''), and pandas 3.0 raises; df[''qty''] = ... simply replaces the column with a new float64 one', 1), (@q, 'C', 'Both raise TypeError in 2.2', 0), (@q, 'D', 'Both silently truncate the values to 1 and 2', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'index-alignment'), 4, 'mcq', 'A team moves a pipeline from pandas to Polars. What is the key DESIGN difference around the row index that changes how arithmetic and assignment behave?', NULL, NULL, 'Polars has no row index: operations line up rows by position (lengths must match) and any matching by key is an explicit join, while pandas silently aligns on index labels', 'What would a + b mean if there were no labels?', 'pandas'' implicit alignment is powerful (rows stay matched after a sort or filter) but it surprises people: reordered or differently filtered frames produce NaN instead of an error, and assignment aligns instead of pasting. Polars, like SQL, has no index. Columns combine positionally inside one frame, and combining data from two frames means an explicit join on named keys. That makes Polars code more predictable and easier to parallelise. The price is that you must carry keys as ordinary columns. A port fails when the pandas code silently relied on index alignment.', 'pandas:  a[x=1, y=2] + b[y=10, z=20] -> x NaN, y 12, z NaN\n         (matched by label)\nPolars:  a [1, 2] + b [10, 20]       -> [11, 22]\n         (matched by position; keyed match = explicit join)', 'SQL tables have no implicit row index either: to combine two tables you write a JOIN ON key.', 268);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Polars aligns on labels too, but sorts them first', 0), (@q, 'B', 'Polars has no row index: operations line up rows by position (lengths must match) and any matching by key is an explicit join, while pandas silently aligns on index labels', 1), (@q, 'C', 'Polars always copies data, pandas never does', 0), (@q, 'D', 'There is no difference; both align by index', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-features'), 4, 'fill_blank', 'In scikit-learn 1.6, `HistGradientBoostingClassifier` treats pandas `category` columns as categorical features automatically, because its `categorical_features` default is `''____''`.', NULL, NULL, 'from_dtype', 'The categorical columns are detected from the column dtype.', 'With categorical_features=''from_dtype'' (the default in 1.6), every column of category dtype in the input DataFrame is handled with native categorical splits, with no one-hot encoding needed. This only works if the training and serving frames use the same categories, so fix them with pd.Categorical(..., categories=train_cats). If you pass a NumPy array, there are no dtypes to read, so nothing is treated as categorical: the int codes become plain numbers.', NULL, NULL, 269);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 4, 'mcq', 'On a 50-million-row frame, why can `df.eval(''a + b * c'')` be faster and lighter on memory than `df[''a''] + df[''b''] * df[''c'']`?', 'import pandas as pd\ndf = pd.DataFrame({''a'': [1, 2], ''b'': [3, 4], ''c'': [5, 6]})\nprint(df.eval(''a + b * c'').tolist())', 'python', 'With numexpr installed, eval computes the expression in cache-sized chunks on several threads, without materialising the full-size temporary b * c array', 'How many full-length arrays does the plain version create?', 'The plain expression first builds a full 50M-element array for b * c (400 MB for float64) and then another for the sum. numexpr streams through the data in blocks and fuses the operations, so temporaries stay small and work is spread over cores. On small frames, parsing the string costs more than it saves. Use eval for big, arithmetic-heavy expressions and keep plain vectorised code elsewhere.', NULL, 'Like a database pipelining a computed column row block by row block instead of writing intermediate tables to disk.', 270);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'With numexpr installed, eval computes the expression in cache-sized chunks on several threads, without materialising the full-size temporary b * c array', 1), (@q, 'B', 'eval compiles the expression to GPU code', 0), (@q, 'C', 'eval is always faster, even on 100-row frames', 0), (@q, 'D', 'eval skips NaN values', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 4, 'true_false', '`df.loc[mask]` with a boolean NumPy array selects rows by POSITION, while `df.loc[mask_series]` with a boolean Series matches rows by index LABEL.', 'import numpy as np\nimport pandas as pd\ndf = pd.DataFrame({''v'': [10, 20, 30]}, index=[2, 0, 1])\nm = pd.Series([True, False, True], index=[0, 1, 2])\nprint(df.loc[np.array([True, False, True])][''v''].tolist(), df.loc[m][''v''].tolist())', 'python', 'True', 'A NumPy array has no labels to align.', 'A plain array (or list) of booleans is taken position by position, so it must have exactly len(df) entries. A boolean Series is first aligned to df''s index. On an index like [2, 0, 1], the same True/False values pick different rows depending on whether they come in as an array or as a Series with its own labels. Masks created with .values or .to_numpy() quietly switch from label to position semantics. That''s harmless when the order matches and a silent bug when it doesn''t.', 'df index:     2    0    1        values: 10 20 30\narray mask:   T    F    T   -> positions 0, 2 -> [10, 30]\nSeries mask:  {0: T, 1: F, 2: T} aligned to labels\n              label 2 -> T, 0 -> T, 1 -> F    -> [10, 20]', NULL, 271);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 4, 'true_false', 'On a sorted index [''a'', ''b'', ''d''], `s.loc[''b'':''c'']` works even though ''c'' is not a label, but on an unsorted index the same kind of slice raises KeyError.', 'import pandas as pd\ns = pd.Series([1, 2, 3], index=[''a'', ''b'', ''d''])\nprint(s.loc[''b'':''c''].tolist(), s.loc[''a'':''c''].tolist())', 'python', 'True', 'With a monotonic index, pandas can binary-search where ''c'' WOULD go.', 'For a monotonic index, label slicing uses searchsorted, so slice bounds don''t have to exist: ''b'':''c'' means ''every label from b up to c'', giving just b here. On a non-monotonic index there''s no ''where it would be'', so a missing bound raises KeyError. Date slices like df.loc[''2024-01-01'':''2024-01-31''] rely on this: sort_index() first, and missing days at the edges don''t matter.', NULL, NULL, 272);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'series-vs-df'), 4, 'mcq', 'You need ONE row of a mixed-type feature frame to pass to `model.predict`. Why is `df.iloc[[0]]` better than `df.iloc[0]`?', 'import pandas as pd\ndf = pd.DataFrame({''a'': [1], ''b'': [1.5], ''c'': [''x'']})\nprint(df.iloc[0].dtype, df.iloc[[0]].dtypes.astype(str).tolist())', 'python', 'iloc[[0]] returns a 1-row DataFrame that keeps each column''s dtype and the column names; iloc[0] returns a Series, which forces one common dtype (often object) and is 1-D', 'A list inside iloc keeps the result 2-D.', 'A single position collapses the row into a Series: the columns become its index and the values must share one dtype, so int, float and str together become object. scikit-learn then gets a 1-D object array, which fails or gets misread. A list of positions keeps the DataFrame shape (1, n_features), the dtypes and the feature names that the model checks. The same rule applies to loc: df.loc[[label]] vs df.loc[label].', 'df.iloc[0]    -> Series, dtype object      (1-D, dtypes lost)\n                 a  1 | b  1.5 | c  ''x''\ndf.iloc[[0]]  -> DataFrame shape (1, 3)    (2-D, dtypes kept)\n                 a:int64  b:float64  c:object', NULL, 273);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'iloc[0] is slower to compute', 0), (@q, 'B', 'iloc[[0]] returns a copy, iloc[0] a view', 0), (@q, 'C', 'There is no difference for predict', 0), (@q, 'D', 'iloc[[0]] returns a 1-row DataFrame that keeps each column''s dtype and the column names; iloc[0] returns a Series, which forces one common dtype (often object) and is 1-D', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 4, 'true_false', 'Converting an int64 id column to float64 (which happens silently when one id is missing) keeps every id exactly.', 'import pandas as pd\nprint(int(pd.Series([2**53 + 1]).astype(float)[0]) == 2**53 + 1)', 'python', 'False', 'float64 has 53 bits of mantissa.', 'float64 represents every integer exactly only up to 2**53 (about 9 x 10^15). Larger ids, such as 64-bit snowflake ids or some order numbers, get rounded to a neighbouring value, so two different ids can collide and joins match the wrong rows. Keep ids as strings or as the nullable ''Int64'' dtype (read_csv(dtype={''id'': ''Int64''})), so a missing value doesn''t force a float conversion.', NULL, 'The same reason JavaScript''s Number can''t hold a 64-bit id from a backend, and why APIs send big ids as strings.', 274);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 1, 'mcq', 'In matplotlib, what is the difference between a Figure and an Axes?', NULL, NULL, 'The Figure is the whole canvas/window; an Axes is one plot area inside it, with its own x and y axis', 'One is the page, the other is a chart drawn on the page.', 'A Figure is the top-level container (the image you save). Each Axes is a single plot with its own data, ticks, labels and title. One Figure can hold many Axes.', '+---------------- Figure ----------------+\n|  +---- Axes ----+   +---- Axes ----+   |\n|  |  title       |   |  title       |   |\n|  |  y  /\\_/     |   |  y   . .     |   |\n|  |     x        |   |      x       |   |\n|  +--------------+   +--------------+   |\n+----------------------------------------+', 'Figure = the browser page; Axes = one chart component on that page.', 1);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The Figure is the x axis and the Axes is the y axis', 0), (@q, 'B', 'An Axes holds several Figures', 0), (@q, 'C', 'The Figure is the whole canvas/window; an Axes is one plot area inside it, with its own x and y axis', 1), (@q, 'D', 'They are two names for the same thing', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 1, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nprint(type(fig).__name__, type(ax).__name__, len(fig.axes))', 'python', 'Figure Axes 1', 'With no arguments, subplots makes one plot area.', 'plt.subplots() returns a (Figure, Axes) pair; the figure holds exactly one Axes.', NULL, NULL, 2);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Axes Figure 1', 0), (@q, 'B', 'Figure Axes 1', 1), (@q, 'C', 'Figure ndarray 1', 0), (@q, 'D', 'Figure Axes 0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 1, 'fill_blank', 'The recommended way to start a plot is `fig, ax = plt.____()`.', NULL, NULL, 'subplots', 'It creates the figure and the axes in one call.', 'plt.subplots() returns the Figure and Axes objects so you can call methods on ax directly (the object-oriented style).', NULL, NULL, 3);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 1, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nax.plot([1, 2, 3], [4, 5, 6])\nax.plot([1, 2, 3], [6, 5, 4])\nprint(len(ax.lines))', 'python', '2', 'Each plot() call adds a line to the same Axes.', 'Calling ax.plot twice draws two lines on the same axes; ax.lines holds both Line2D objects.', NULL, NULL, 4);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0', 0), (@q, 'B', '6', 0), (@q, 'C', '1', 0), (@q, 'D', '2', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 2, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nresult = ax.plot([1, 2, 3])\nprint(type(result).__name__, len(result), type(result[0]).__name__)', 'python', 'list 1 Line2D', 'plot can draw several lines in one call, so it returns a container.', 'ax.plot returns a list of Line2D objects (one per line drawn). Hence the idiom `line, = ax.plot(...)` to unpack a single line.', NULL, NULL, 5);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'list 3 float', 0), (@q, 'B', 'Line2D 1 Line2D', 0), (@q, 'C', 'Axes 1 Line2D', 0), (@q, 'D', 'list 1 Line2D', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 1, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nax.plot([1, 2, 3], [1, 4, 9])\nx, y = ax.lines[0].get_data()\nprint([int(v) for v in x], [int(v) for v in y])', 'python', '[1, 2, 3] [1, 4, 9]', 'plot(x, y): first argument is x.', 'With two arguments the first is x and the second is y. The Line2D object stores both.', NULL, NULL, 6);
