INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 2, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nprint(plt.rcParams["figure.figsize"], plt.rcParams["figure.dpi"])\nfig = plt.figure(figsize=(8, 3))\nprint(fig.get_size_inches().tolist())', 'python', '[6.4, 4.8] 100.0\n[8.0, 3.0]', 'figsize is (width, height) in inches.', 'The default size is 6.4 x 4.8 inches at 100 dpi (640 x 480 pixels). figsize=(8, 3) means 8 inches wide, 3 tall.', NULL, NULL, 8);
