INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 3, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig = plt.figure()\nax1 = fig.add_subplot(1, 2, 1)\nax2 = fig.add_subplot(1, 2, 2)\nax3 = ax1.twinx()\nprint(len(fig.axes))', 'python', '3', 'twinx creates a brand-new Axes sharing the x axis.', 'Two subplots plus a twin axes (a second y axis on the right of ax1) = 3 Axes objects in the figure.', NULL, NULL, 9);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '4', 0), (@q, 'B', '2', 0), (@q, 'C', '3', 1), (@q, 'D', '1', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 3, 'mcq', 'What is an ''Artist'' in matplotlib?', NULL, NULL, 'Any object that can be drawn on a figure: Figure, Axes, Line2D, Text, Patch, etc.', 'Everything you see is one.', 'Everything visible is an Artist. Containers (Figure, Axes) hold primitives (Line2D, Rectangle, Text). Calling ax.plot creates Line2D artists and adds them to the Axes.', NULL, NULL, 10);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A colour theme', 0), (@q, 'B', 'A function that saves a figure', 0), (@q, 'C', 'The backend that renders PNG files', 0), (@q, 'D', 'Any object that can be drawn on a figure: Figure, Axes, Line2D, Text, Patch, etc.', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 4, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nax.plot([1, 2])\nax.bar(["a", "b"], [1, 2])\nax.scatter([1, 2], [3, 4])\nax.text(0, 0, "hi")\nprint(len(ax.lines), len(ax.patches), len(ax.collections), len(ax.texts))', 'python', '1 2 1 1', 'Each chart type creates a different kind of Artist and stores it in a different list.', 'A line is a Line2D in ax.lines; each bar is a Rectangle patch (2 patches); scatter is one PathCollection in ax.collections; text goes to ax.texts.', NULL, NULL, 11);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1 2 1 1', 1), (@q, 'B', '4 0 0 0', 0), (@q, 'C', '1 2 2 1', 0), (@q, 'D', '1 1 1 1', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 2, 'mcq', 'Why does calling `ax.plot` twice put two lines on the same chart instead of replacing the first one?', NULL, NULL, 'An Axes is a container: every plotting call adds artists to it until you clear it', 'Think about what ax.plot does to ax.', 'An Axes accumulates artists. That is why overlaying train and val curves is just two plot calls, and why you must use ax.cla() or a new Axes to start fresh.', NULL, NULL, 12);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'matplotlib merges the two datasets into one line', 0), (@q, 'B', 'The second call creates a hidden second figure', 0), (@q, 'C', 'An Axes is a container: every plotting call adds artists to it until you clear it', 1), (@q, 'D', 'The first line is replaced but stays in memory', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'plot-types'), 1, 'mcq', 'Which chart is best for showing how training loss changes over 50 epochs?', NULL, NULL, 'Line plot', 'Ordered x values, a trend over time.', 'A line plot connects values in order, which makes the trend (going down, levelling off, going up) easy to see.', NULL, NULL, 13);
