INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'plot-types'), 1, 'mcq', 'Which chart shows the relationship between two numeric variables, such as height and weight for 500 people?', NULL, NULL, 'Scatter plot', 'One dot per person.', 'A scatter plot puts one point per row at (height, weight), so you can see correlation, clusters and outliers. A line plot would connect points in row order, which means nothing here.', NULL, NULL, 14);
