INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'labels-legends'), 3, 'true_false', '`plt.title(''x'')` and `ax.set_title(''x'')` can set titles on different plots if `ax` is not the current Axes.', NULL, NULL, 'True', 'pyplot functions act on the ''current'' Axes.', 'plt.title targets plt.gca(), the most recently active Axes. In a multi-plot figure that may not be the ax you think. Using ax.set_title is explicit.', NULL, NULL, 35);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'labels-legends'), 2, 'mcq', 'Your legend covers the most important part of the plot. What''s the cleanest fix?', NULL, NULL, 'ax.legend(loc=''best'') or place it outside with bbox_to_anchor', 'legend has placement options.', 'loc=''best'' (the default for Axes legends) tries to avoid data; loc=''upper right'' etc. choose a corner; bbox_to_anchor=(1.02, 1), loc=''upper left'' puts it outside the plot.', NULL, NULL, 36);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ax.legend(loc=''best'') or place it outside with bbox_to_anchor', 1), (@q, 'B', 'Call plt.show() twice', 0), (@q, 'C', 'Make the lines thinner', 0), (@q, 'D', 'Delete the legend and explain colours in the title', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'subplots'), 1, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, axs = plt.subplots(2, 3)\nprint(axs.shape, len(fig.axes))', 'python', '(2, 3) 6', 'subplots(nrows, ncols).', 'subplots(2, 3) makes 2 rows x 3 columns = 6 Axes, returned as a 2-D NumPy array of shape (2, 3).', 'axs[0,0]  axs[0,1]  axs[0,2]\naxs[1,0]  axs[1,1]  axs[1,2]', 'Like a CSS grid with 2 rows and 3 columns: each cell is its own chart component.', 37);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(2, 3) 6', 1), (@q, 'B', '(3, 2) 6', 0), (@q, 'C', '(2, 3) 1', 0), (@q, 'D', '(6,) 6', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'subplots'), 2, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, axs = plt.subplots(1, 3)\nprint(axs.shape)', 'python', '(3,)', 'A single row gets squeezed.', 'By default (squeeze=True) a 1-row or 1-column grid returns a 1-D array, so you index axs[0], not axs[0, 0]. squeeze=False always gives 2-D.', NULL, NULL, 38);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(3,)', 1), (@q, 'B', '(3, 1)', 0), (@q, 'C', '(1, 3)', 0), (@q, 'D', '3', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'subplots'), 2, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, axs = plt.subplots(1, 3)\naxs[0, 1].plot([1, 2])', 'python', 'IndexError', 'What is the shape of axs here?', 'axs is 1-D with shape (3,), so a 2-D index raises IndexError (''too many indices for array''). Use axs[1].', NULL, NULL, 39);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'IndexError', 1), (@q, 'B', '(nothing is printed)', 0), (@q, 'C', 'KeyError', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'subplots'), 2, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, axs = plt.subplots(2, 2)\nfor ax in axs.flat:\n    ax.plot([1, 2])\nprint(sum(len(ax.lines) for ax in fig.axes))', 'python', '4', 'axs.flat walks every Axes in the grid.', 'axs.flat (or axs.ravel()) iterates all 4 Axes regardless of grid shape; each gets one line.', NULL, NULL, 40);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '4', 1), (@q, 'B', '8', 0), (@q, 'C', '2', 0), (@q, 'D', '1', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'subplots'), 3, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig = plt.figure()\nax = fig.add_subplot(2, 2, 3)\nprint(ax.get_subplotspec().rowspan.start, ax.get_subplotspec().colspan.start)', 'python', '1 0', 'Numbering goes left to right, top to bottom, starting at 1.', 'In a 2x2 grid, position 3 is the first plot of the second row: row 1, column 0 (0-based).', 'add_subplot(2, 2, k)\n+---+---+\n| 1 | 2 |\n+---+---+\n| 3 | 4 |\n+---+---+', NULL, 41);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1 0', 1), (@q, 'B', '0 2', 0), (@q, 'C', '2 0', 0), (@q, 'D', '1 1', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'subplots'), 2, 'mcq', 'What does `plt.subplots(2, 1, sharex=True)` do?', NULL, NULL, 'Both rows use the same x-axis range, so zooming/limits stay in sync and the top plot''s x tick labels can be hidden', 'Shared axis = shared limits.', 'sharex links the x limits of the Axes, ideal for stacking, say, loss and learning rate over the same epochs.', NULL, NULL, 42);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It shares the colour of the lines', 0), (@q, 'B', 'It draws the same data twice', 0), (@q, 'C', 'It puts both plots on the same Axes', 0), (@q, 'D', 'Both rows use the same x-axis range, so zooming/limits stay in sync and the top plot''s x tick labels can be hidden', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'subplots'), 3, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, axs = plt.subplots(2, 1, sharex=True)\naxs[0].plot([0, 10], [0, 1])\naxs[1].plot([0, 5], [0, 1])\nprint(axs[0].get_xlim() == axs[1].get_xlim())', 'python', 'True', 'Shared axes autoscale together.', 'With sharex=True both Axes use one x range that covers all data (0..10 plus margins), so the limits are equal.', NULL, NULL, 43);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'None', 0), (@q, 'B', 'ValueError', 0), (@q, 'C', 'False', 0), (@q, 'D', 'True', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'subplots'), 2, 'mcq', 'Labels of neighbouring subplots overlap each other. What''s the usual fix?', NULL, NULL, 'fig.tight_layout() (or plt.subplots(..., layout=''constrained''))', 'Ask matplotlib to recompute spacing.', 'tight_layout / constrained layout adjust the spacing so titles, tick labels and axis labels don''t collide.', NULL, NULL, 44);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Call plt.show() before adding labels', 0), (@q, 'B', 'fig.tight_layout() (or plt.subplots(..., layout=''constrained''))', 1), (@q, 'C', 'Use fewer data points', 0), (@q, 'D', 'Set dpi=300', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'subplots'), 3, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, axs = plt.subplots(2, 2)\nfig.delaxes(axs[1, 1])\nprint(len(fig.axes))', 'python', '3', 'delaxes removes an Axes from the figure.', 'With 3 plots in a 2x2 grid, removing the unused 4th Axes avoids an empty box. axs still references it, but the figure no longer holds it.', NULL, NULL, 45);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '2', 0), (@q, 'B', 'ValueError', 0), (@q, 'C', '4', 0), (@q, 'D', '3', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'subplots'), 4, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, axd = plt.subplot_mosaic([["loss", "loss"], ["acc", "lr"]])\nprint(sorted(axd), len(fig.axes))', 'python', '[''acc'', ''loss'', ''lr''] 3', 'Repeated names in the mosaic make one Axes that spans those cells.', 'subplot_mosaic returns a dict name -> Axes. ''loss'' spans the whole top row, so there are 3 Axes, not 4.', '+---------------+\n|     loss      |\n+-------+-------+\n|  acc  |  lr   |\n+-------+-------+', NULL, 46);
