INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'pandas-plot'), 1, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nimport pandas as pd\ndf = pd.DataFrame({"train": [1.0, 0.6, 0.4], "val": [1.1, 0.8, 0.7]})\nax = df.plot()\nprint(type(ax).__name__, len(ax.lines))', 'python', 'Axes 2', 'df.plot() draws one line per numeric column and returns the Axes.', 'DataFrame.plot is a wrapper around matplotlib: it returns the Axes so you can keep customising (ax.set_xlabel...).', NULL, 'Like a UI component library wrapping raw DOM calls: quick defaults, and you can still reach the underlying element.', 47);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Axes 2', 1), (@q, 'B', 'Axes 1', 0), (@q, 'C', 'DataFrame 2', 0), (@q, 'D', 'Figure 2', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'pandas-plot'), 2, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nimport pandas as pd\ndf = pd.DataFrame({"loss": [3, 2, 1]}, index=pd.Index([1, 2, 3], name="epoch"))\nax = df.plot()\nprint(ax.get_xlabel(), [t.get_text() for t in ax.get_legend().get_texts()])', 'python', 'epoch [''loss'']', 'pandas uses the index for x and the column names for the legend.', 'The index becomes the x axis and its name becomes the x label; each column becomes a labelled line with an automatic legend.', NULL, NULL, 48);
