INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'pandas-plot'), 3, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nimport pandas as pd\ndf = pd.DataFrame({"a": [1, 2, 3], "b": [3, 2, 1]})\naxs = df.plot(subplots=True)\nprint(type(axs).__name__, axs.shape)', 'python', 'ndarray (2,)', 'subplots=True gives one Axes per column.', 'With subplots=True pandas creates one Axes per column, stacked vertically, and returns them as a NumPy array.', NULL, NULL, 49);
