INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'pandas-plot'), 2, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nimport pandas as pd\ns = pd.Series([1, 2, 2, 3, 3, 3])\nax = s.plot(kind="hist")\nprint(ax.get_ylabel())', 'python', 'Frequency', 'pandas fills in a default y label for histograms.', 'Series.plot(kind=''hist'') (same as s.plot.hist()) labels the y axis ''Frequency''.', NULL, NULL, 51);
