INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'pandas-plot'), 2, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nimport pandas as pd\nfig, axs = plt.subplots(1, 2)\ns = pd.Series([3, 1, 2])\ns.plot(ax=axs[1])\nprint(len(axs[0].lines), len(axs[1].lines))', 'python', '0 1', 'ax= tells pandas where to draw.', 'Passing ax= makes pandas draw on that existing Axes instead of the current one, which is how you put pandas plots into a subplot grid.', NULL, NULL, 52);
