INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'pandas-plot'), 3, 'mcq', 'You call `df.plot()` on a DataFrame with columns name (text), age and salary. What happens to `name`?', NULL, NULL, 'It is skipped: only numeric columns are plotted', 'What is the y value of ''Ann''?', 'pandas plots numeric columns only. To put names on the x axis use df.plot(x=''name'', y=''salary'', kind=''bar'') or set_index(''name'') first.', NULL, NULL, 54);
